// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":77,"question":"يقول: إنَّ الإسلام والإيمان ليسا محصورين برسالة سيدنا محمدٍ عليه الصلاة والسلام فقط، بل إنَّ الإسلام والإيمان يخصَّان كلَّ إنسانٍ يعبد الله بأي صورةٍ كانت، قبل وبعد البعثة المحمدية المباركة؟","title":"حكم من بلغته رسالة الإسلام ولم يدخل فيه","answer":"الجواب: أما قبل بعث محمدٍ ﷺ: فكل مَن آمن بالرسل الماضين فهو من أهل الجنة: مَن آمن بموسى، بعيسى، بهود، بصالح، بجميع الرسل، فهو من أهل الجنة إذا مات على ذلك.\nأمَّا بعد محمدٍ ﷺ: فليس من أهل الجنة إلا مَن تابع محمدًا صلى الله عليه وسلم، فجميع أهل الأرض بعد بعث محمدٍ ﷺ ليس لهم نجاةٌ إلَّا باتباع محمدٍ عليه الصلاة والسلام، قال النبيُّ ﷺ: كل أمَّتي يدخلون الجنة إلَّا مَن أبى، قيل: يا رسول الله، مَن يأبى؟ قال: مَن أطاعني دخل الجنَّةَ، ومَن عصاني دخل النار، فأتباع محمدٍ ﷺ هم الذين يدخلون الجنة دون غيرهم، ويقول ﷺ: والذي نفسي بيده، لا يسمع بي أحدٌ من هذه الأمة: يهودي ولا نصراني، ثم يموت ولم يُؤمن بالذي أُرْسِلْتُ به إلَّا كان من أهل النار.\nفلا يكون من أهل الجنة بعد بعث محمدٍ ﷺ إلَّا مَن تابعه، هذا هو الذي يكون من أهل الجنَّة، أما مَن بلغه خبرُه وكفر به ولم يُؤمن فهو من أهل النار.\nأما مَن لم يبلغه خبرُ النبي ﷺ من أهل الفترات، الذين لم يسمعوا بالرسول ولا بالقرآن، فهؤلاء يُقال لهم: أهل الفترة، وهؤلاء أمرهم إلى الله يوم القيامة، يمتحنهم جلَّ وعلا، فمَن نجح في الامتحان دخل الجنة، ومَن لم ينجح دخل النار -نسأل الله السلامة.\nوأما مَن بلغته رسالتُه ﷺ، وبلغه القرآن، ولم يؤمن به، فهو من أهل النار -نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/3045/حكم-من-بلغته-رسالة-الاسلام-ولم-يدخل-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0054.mp3","categories":["الجنايات والحدود","ضوابط التكفير"]},{"id":137,"question":"كما تعلمون ما نُقابله من مشاكل من بعض المُنحرفين والمُجرمين، وفي بعض الأحيان يضطر الأمر أثناء التَّحقيق مع أي فئةٍ من هؤلاء إلى أن أمد يدي على المتهم وأضربه، خاصةً بعد أن يتأكد لدي بجميع الأدلة أن المُتهم مدانٌ، وما أُلاحظه عليه من مُراوغة ومحاولة لتضليل العدالة، فهل أنا محاسَبٌ أمام الله ؟","title":"ما حكم استخدام القوة للضغط على المتهمين؟","answer":"الجواب: تقدم أنه ليس لك أن تعمل إلا بما لديك من التعليمات، وليس لك أن تفتئت وتزيد، عليك أن تعمل ما لديك من التعليمات مع المتهم وغير المتهم، وليس لك أن تزيد ضربًا ولا غيره، ولكن يرى الحاضرُ ما لا يرى الغائب، فإذا أراد التَّملص منك والهرب فلك أن تُقيده، ولك أن تستعين بمَن يُعينك عليه، وإذا مدَّ يده هو فلك أن تُقابله بالقصاص فقط، لا زيادة.\nوأما أن تعمل ما تريد من ضربٍ أو لعنٍ أو شتمٍ فلا، ليس لك أن تلعن، ولا تشتم، ولا تمد يدك إلا بحقِّ الدفاع فقط، مثلما قال النبيُّ ﷺ: المُسْتَبَّان ما قالا فعلى البادئ، ما لم يعتدِ المظلوم، وليس لك أن تزيد على القصاص، إنما عليك أن تُنفذ التَّعليمات التي لديك، والتي ليس فيها ما يُخالف الشرع مطلقًا.","link":"https://binbaz.org.sa/fatwas/3673/ما-حكم-استخدام-القوة-للضغط-على-المتهمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0129.mp3","categories":["الجنايات والحدود"]},{"id":140,"question":"إذا أُلقي القبض على رجلٍ اشتبه أنه سكران، هل من الأفضل التَّنبيه عليه وستره ونصحه، أم تركه والتخويف منه؟","title":"هل يجوز ستر من يرتكب حدًّا؟","answer":"الجواب: أما من عامَّة الناس فيستر عليه وينصحه، ومن الشرطة والولاية فلا، ما يسترون عليه إذا أمسكوه، فهم نُوَّاب السلطان، يُمسكونه ويحفظونه حتى يأخذ جزاءه، أمَّا واحدٌ من المسلمين شافه عند الباب أو في الطريق سكران، وأخذه ونصحه ورده إلى بيته فجزاه الله خيرًا، ما فيه شيء، يقول النبيُّ عليه الصلاة والسلام: مَن ستر مسلمًا ستره الله في الدنيا والآخرة. لكن إذا بَلَغَت المسؤولين فلا، يقول النبيُّ ﷺ: إذا بلغت الحدودُ السلطان فلعن الله الشَّافع والمُشفع، والشرطة من السّلطان، فهم نوَّاب السلطان، والقضاة نواب السلطان، والهيئة نواب السلطان، فإذا بلغهم الأمر يُمسكون ولا يسترون، بل يأخذونه ويُمسكونه ويعملون فيه ما وكّل إليهم من التَّعليمات.","link":"https://binbaz.org.sa/fatwas/3676/هل-يجوز-ستر-من-يرتكب-حدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0132.mp3","categories":["الجنايات والحدود"]},{"id":200,"question":"صدم رجلًا وهو قاطع الشارع، ثم نقله إلى المُستشفى وهو حيٌّ، ولا يزال حيًّا، وفي المُستشفى أُجريت له عملية في رأسه، وبعد إجراء العملية توفي، هل تلزمه الكفَّارة أم لا؟ علمًا بأن سرعة السيارة كانت ثمانين كيلو.","title":"ماذا على من تسبَّب بموت شخص بحادث؟","answer":"الجواب: تلزمه الدية والكفَّارة؛ لأنَّه هو الذي قتله، فتلزمه الدية، وتلزمه الكفَّارة، والكفَّارة عتق رقبةٍ، فإن عجز صام شهرين متتابعين، والدية لأهله، فإذا سمحوا فلا بأس.","link":"https://binbaz.org.sa/fatwas/3801/ماذا-على-من-تسبب-بموت-شخص-بحادث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0207.mp3","categories":["الجنايات والحدود"]},{"id":242,"question":"كنت أقود سيارتي خارج مدينة الرياض، ومعي شخصان، وشاءت إرادةُ الله أن يقع حادثٌ، مات على إثره أحدُ الراكبين،  هل يجب عليَّ صيام مدة الشَّهرين، مع العلم أنَّ نتائج التحقيق لأجهزة المرور حتى الآن لم تنتهِ، ولم تتم جلسة الحكم الشَّرعي بسبب إجراءات حصر الإرث، ومع العلم أنَّ سائق السيارة الأخرى غير مسلم؟","title":"حكم من تسبّب في حادث مات فيه أشخاص","answer":"الجواب: الشيخ: الحادث يختلف: فإذا كان الحادثُ يُدين صاحبَ السيارة ويجعله هو المُتسبب فعليه الدِّية والكفَّارة، وإن كان يُدينهما جميعًا –المُتصادمين- فعليهما جميعًا الدية، وعلى كل واحدٍ الكفَّارة، فالكفَّارة لا تتبعَّض، فإذا كان على واحدٍ 50% فالدِّية بينهما، وعلى كل واحدٍ كفَّارة مُستقلة، وهي عتق رقبةٍ مؤمنة، فإن لم يجد صام شهرين متتابعين، كل واحدٍ منهما، فأما إن كان ما له تسبب بل السبب من غيره 100%، من أحدهما، فالدية على مَن تسبب، والكفَّارة عليه.\nفإذا تصادما وقرر المرورُ أن التَّعدي من أحدهما فالإثم عليه، والكفَّارة والدية عليه، دون الآخر الذي ليس منه تسبب، أو كان في غاية الحرص، ما فعل شيئًا هو؛ لأنه مثلًا يمشي المشي المعتاد، ولم يتعدّ الطرق التي رُسمت له، ولم يفعل ما يُوجب هذا الحادث، ولكن أراد الله عليه أمرًا آخر، بأن ضرب عليه كفر، أو انكسر عليه شيء، أو ما أشبه ذلك من الأمور التي ليست في طوقه واختياره، فهذا لا يلزمه شيء، ليس عليه شيءٌ إذا ثبت هذا الشيء، مثل: الذي يمشي على الدابة المشي المعتاد، وعثرت الدابة وسقط، أو سقط هو ومَن معه، ليس عليهم شيء؛ لأنَّهم ما فعلوا شيئًا يُوجب ذلك.\nكتكميلٍ لهذا السؤال: وليس عليك شيءٌ حتى تنتهي المُحاكمة، حتى يبت في الحكم، حتى تعلم هل عليك شيء أم لا؟ تنتظر حتى يتمَّ الأمر.","link":"https://binbaz.org.sa/fatwas/4122/حكم-من-تسبب-في-حادث-مات-فيه-اشخاص","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0282.mp3","categories":["الجنايات والحدود"]},{"id":330,"question":"ما الحكم الشرعي فيمَن تعدد منه إدمان المُخدرات؟","title":"ما حكم من تكرر منه تعاطي المخدرات؟","answer":"الجواب: الواجب هو إقامة الحدّ عليه، إذا تكرر ذلك تُقام الحدود، ولا مانع من تعزيره زيادة بالسجن وغيره مما يردعه عن تعاطيها.\nوذهب بعضُ أهل العلم إلى أنه يُقتل إذا لم تنفع فيه التَّأديبات والتَّعزيرات الشرعية والحدود الشرعية؛ أنه عضو فاسد يجب أن يُقتل حتى يُراح منه المجتمع والجمهور، على أنه تُعاد عليه إقامة الحدود مرةً بعد مرةٍ؛ حتى يهديه الله ويُقلع أو يموت.","link":"https://binbaz.org.sa/fatwas/4418/ما-حكم-من-تكرر-منه-تعاطي-المخدرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0383.mp3","categories":["الجنايات والحدود"]},{"id":348,"question":"هل يعذر الإنسان بجهله لأصول الاعتقاد؟","title":"هل يعذر الإنسان بجهله لأصول الاعتقاد؟","answer":"الجواب: ليس هذا محلّ عذرٍ، أصول الدين محلّ إجماعٍ، ليس محل عذرٍ بالجهل إذا كان بين المسلمين، الله قال: وَأُوحِيَ إِلَيَّ هَذَا الْقُرْآنُ لِأُنْذِرَكُمْ بِهِ وَمَنْ بَلَغَ [الأنعام:19]، وقال: هَذَا بَلَاغٌ لِلنَّاسِ [إبراهيم:52].\nفإذا بلغه القرآن، وبلغته السنة، وهو بين المسلمين؛ ما هو معذورٌ بالجهل إذا وقع في الشرك والإلحاد والشيوعية أو الوثنية أو سبّ الدين، ليس بمعذورٍ، يقول الرسول ﷺ في الحديث الصَّحيح الذي رواه مسلم: والذي نفسي بيده لا يسمع بي أحدٌ من هذه الأمة: يهودي ولا نصراني، ثم يموت ولم يؤمن بالذي أُرسلتُ به إلا كان من أهل النار، قال: لا يسمع، وما قال: \"ما يفهم\"، فإذا سمع الخبر وبلغه خبر رسول الله ﷺ وبلغه القرآن؛ كفى، إلا إذا كان في بلادٍ بعيدةٍ ما يعلم ولا يدري، ولا بلغه القرآن، ولا بلغته السنة، فهذا حكمه حكم أهل الفترة، والصحيح فيهم أنهم يُمتحنون يوم القيامة، ويُؤمرون وينهون، فإن أطاعوا نجوا، وإن عصوا هلكوا، كما قال تعالى: وَمَا كُنَّا مُعَذِّبِينَ حَتَّى نَبْعَثَ رَسُولًا [الإسراء:15].","link":"https://binbaz.org.sa/fatwas/4437/هل-يعذر-الانسان-بجهله-لاصول-الاعتقاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0401.mp3","categories":["الجنايات والحدود","ضوابط التكفير"]},{"id":354,"question":"لي أخٌ قدَّر الله عليه بحادث سيارةٍ، فصدم سيارةً أخرى، فتوفي فيها معه ثمانية أشخاص، أريد من سماحتكم أن تُبَيِّنوا لي ما هي كفَّارة ذلك، وأخي الآن سجين؟","title":"حكم من تسبب بموت عدة أشخاص في حادث","answer":"الجواب: الواجب على مَن ابتُلي بمثل هذا الحادث أن يُكفِّر عن كلِّ نفسٍ كفَّارةً مُستقلةً، إن ثبت لدى المحكمة أنه هو المُخطئ والمتعدي وجبت عليه الدية والكفَّارة.\nالدية: ينظر الحاكم فيما يتعلق بالعاقلة، فإذا كانت له عاقلة -وهم العصبة- أغنياء؛ أدُّوا عنه، تعاونوا في ذلك، وإن لم تكن له عاقلة أدَّاها هو، أو أدَّاها بيتُ المال.\nأما الكفَّارة: فعليه عن كل نفسٍ ماتت بأسبابه رقبة مؤمنة، فإن عجز صام عن كل واحدٍ شهرين، فإن عجز ليس هناك إلا الصيام والعتق في القتل، إن استطاع العتق أعتق عن كل نفسٍ رقبةً، فإذا كان قتل ثمانية أعتق ثماني رقابٍ، فإن لم يستطع صام ستة عشر شهرًا، عن كل رقبةٍ شهران، ولا يلزم أن تكون متواليةً، يُؤدِّيها حسب طاقته، إذا صام في السنة شهرين أو أربعة أو ستة على حسب طاقته، والباقي في السنة التي بعدها، وهكذا.\nس: يجوز للإنسان أن يصوم متفرقة.....؟\nالشيخ: كل شهرين متتابعين.\nس: وبعدين؟\nالشيخ: لا بأس أن يستريح بينهما بعض الشيء، ثم يصوم الشهرين الآخرين، وهكذا.\nس: يعني: إذا صام شهرين وجلس شهرين ما عليه شيء؟\nالشيخ: ما يضرُّ إذا كانت هذه طاقته.","link":"https://binbaz.org.sa/fatwas/4546/حكم-من-تسبب-بموت-عدة-اشخاص-في-حادث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0407.mp3","categories":["الجنايات والحدود"]},{"id":463,"question":"في الاعتداء على الأعراض هل يجوز أن يتصالحوا على شيء من المال..... مثلًا إذا اعتدى على صبي بلواط أو شيء من هذا.. وعند التحاكم إلى القاضي سامح على أن يُعطى شيئًا من المال، هذا يجوز؟","title":"هل يجوز التصالح على مال لإسقاط الحد؟","answer":"الجواب: لا، ما يصلح، إذا وقع في الحدود لا يجوز، إذا ثبت الحد لابدّ أن يُقام الحد الشرعي، ولا يجوز المصالحة في الحدود، لا بدّ أن تقوم الحدود الشرعية، إلا إذا أحد ستر عليه بدون عِوَض، ستر عليه..... وتوبته، وإماتة الأمر من باب الستر من ستر مسلمًا ستره الله في الدنيا والآخرة وعدم الفضيحة؛ فلا بأس، ولكن بدون عِوَض.\n(دروس شرح بلوغ المرام، كتاب البيوع)","link":"https://binbaz.org.sa/fatwas/6188/هل-يجوز-التصالح-على-مال-لاسقاط-الحد","audio":"https://files.zadapps.info/binbaz.org.sa/3erd023.mp3","categories":["الجنايات والحدود"]},{"id":576,"question":"قوله ﷺ: من بَدَّل دينه فاقتلوه وقصة معاذ مع اليهودي ما فيها استتابة؟","title":"ما صحة الاستتابة في قصة معاذ واليهودي؟","answer":"الجواب: روى أبو داود أنه استتيب.\n(دروس شرح بلوغ المرام، كتاب الجنايات)","link":"https://binbaz.org.sa/fatwas/6407/ما-صحة-الاستتابة-في-قصة-معاذ-واليهودي","audio":"https://files.zadapps.info/binbaz.org.sa/maram142 - 01 -  Start.mp3","categories":["الجنايات والحدود"]},{"id":577,"question":"وهل الصحابة سواء في السب؟","title":"ما حكم سب الصحابة؟","answer":"الجواب: المعروف عند العلماء أن من سبهم يُقتل؛ مرتد عن الإسلام، ما يسبهم إلا وهو قادح في دينهم وهم النَّقَلة الذين نقلوا لنا الدين كله.\n(دروس شرح بلوغ المرام، كتاب الجنايات)","link":"https://binbaz.org.sa/fatwas/6408/ما-حكم-سب-الصحابة","audio":"undefined","categories":["الجنايات والحدود","نواقض الإسلام"]},{"id":578,"question":"بعض الناس يقول إن سب الدين إذا صدر عن اعتقاد يكون كفرًا أكبر وإذا كان عملي فصار كفر أصغر.","title":"ما حكم من يسب الدين؟","answer":"الجواب: هذا كلام باطل، تفريق باطل، سب الدين مطلقًا ردة عن الإسلام، سواء قال الإنسان إني أعتقد أو ما أعتقد، ما دام سب؛ وجب قتله وحُكم بكفره.\n(دروس شرح بلوغ المرام، كتاب الجنايات)","link":"https://binbaz.org.sa/fatwas/6409/ما-حكم-من-يسب-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/maram143 - 01 -  Start.mp3","categories":["الجنايات والحدود","نواقض الإسلام"]},{"id":579,"question":"إذا سب العلماء كافة هل يعزر؟","title":"ما حكم من يسب أهل العلم؟ وما عقوبته؟","answer":"الجواب: يستحق التعزير.\n(دروس شرح بلوغ المرام، كتاب الجنايات)","link":"https://binbaz.org.sa/fatwas/6410/ما-حكم-من-يسب-اهل-العلم-وما-عقوبته","audio":"https://files.zadapps.info/binbaz.org.sa/maram145 - 01 -  Start.mp3","categories":["الجنايات والحدود"]},{"id":581,"question":"الدليل على أن دية الكافر على نصف دية المسلم؟","title":"ما دليل أن دية الكافر نصف دية المسلم؟","answer":"الجواب: جاء بحديث جيد لا بأس به.\n(دروس شرح بلوغ المرام، كتاب الجنايات)","link":"https://binbaz.org.sa/fatwas/6413/ما-دليل-ان-دية-الكافر-نصف-دية-المسلم","audio":"https://files.zadapps.info/binbaz.org.sa/maram148 - 02 - .mp3","categories":["الجنايات والحدود"]},{"id":582,"question":"إذا اشترك مسلمان في قتل ذمي؟","title":"ما الحكم إذا اشترك مسلمان في قتل ذِمِّي؟","answer":"الجواب: عليهم الدية بينهما.\n(دروس شرح بلوغ المرام، كتاب الجنايات)","link":"https://binbaz.org.sa/fatwas/6414/ما-الحكم-اذا-اشترك-مسلمان-في-قتل-ذمي","audio":"https://files.zadapps.info/binbaz.org.sa/maram149 - 03 - .mp3","categories":["الجنايات والحدود"]},{"id":583,"question":"من قتل بالسُّم؟","title":"ما حكم من قتل بالسُّم؟","answer":"الجواب: يُقتل بالسم وإلا بالسيف، كله واحد.\n(دروس شرح بلوغ المرام، كتاب الجنايات)","link":"https://binbaz.org.sa/fatwas/6417/ما-حكم-من-قتل-بالسم","audio":"https://files.zadapps.info/binbaz.org.sa/maram151 - 03 - .mp3","categories":["الجنايات والحدود"]},{"id":584,"question":"ما صحة حديث: \"لأن يقام حد من حدود الله خير من أن تمطروا أربعين خريفًا\"؟","title":"درجة حديث \"حد من حدود الله خير من..\"","answer":"الجواب: حديث مشهور، ولكن لا أعرف سنده.\n(دروس شرح بلوغ المرام، كتاب الجنايات)","link":"https://binbaz.org.sa/fatwas/6418/درجة-حديث-حد-من-حدود-الله-خير-من","audio":"https://files.zadapps.info/binbaz.org.sa/maram152 - 03 - .mp3","categories":["الحكم على الأحاديث","الجنايات والحدود"]},{"id":585,"question":"بعض الوجهاء وأهل الإصلاح يذهبون إلى أهل القتيل لكي يتنازلون عن القصاص؟","title":"ما حكم الشفاعة في العفو عن القاتل؟","answer":"الجواب: الشفاعة لا بأس بها، مثل ما في قصة الرُّبَيِّع.\n(دروس شرح بلوغ المرام، كتاب الجنايات)","link":"https://binbaz.org.sa/fatwas/6419/ما-حكم-الشفاعة-في-العفو-عن-القاتل","audio":"https://files.zadapps.info/binbaz.org.sa/maram153 - 03 - .mp3","categories":["الجنايات والحدود"]},{"id":586,"question":"قتل الجماعة بالواحد هل هو مشروط أن كل واحد منهم قصده القتل؟","title":"ما حكم قتل الجماعة بالواحد؟","answer":"الجواب: إذا حصل الاشتراك في القتل حتى يُنسب إلى كل واحد أنه شارك في القتل، مثل: هذا قطع يده، وهذا قطع رجله، وهذا ذبحه بالسكين، يعني كل واحد فعل شيئًا يمكن أن يكون قتلاً، بخلاف الإمساك الذي تقدم فإن الممسك يُحبس حتى يموت.\n(دروس شرح بلوغ المرام، كتاب الجنايات)","link":"https://binbaz.org.sa/fatwas/6420/ما-حكم-قتل-الجماعة-بالواحد","audio":"https://files.zadapps.info/binbaz.org.sa/maram154 - 03 - .mp3","categories":["الجنايات والحدود"]},{"id":587,"question":"القتل العمد فيه العفو؟","title":"ما حكم العفو في قتل العمد؟","answer":"الجواب: نعم؛ إذا عفا لا بأس.\n(دروس شرح بلوغ المرام، كتاب الجنايات)","link":"https://binbaz.org.sa/fatwas/6421/ما-حكم-العفو-في-قتل-العمد","audio":"https://files.zadapps.info/binbaz.org.sa/maram155 - 03 - .mp3","categories":["الجنايات والحدود"]},{"id":588,"question":"شِبْه العمد فيه القصاص؟","title":"هل في شِبْه العمد قصاص؟","answer":"الجواب: لا، فيه الدية، الخطأ وشبه العمد فيه الدية، والعمد المحض هو الذي فيه القصاص.\n(دروس شرح بلوغ المرام، كتاب الجنايات)","link":"https://binbaz.org.sa/fatwas/6422/هل-في-شبه-العمد-قصاص","audio":"https://files.zadapps.info/binbaz.org.sa/maram156 - 03 - .mp3","categories":["الجنايات والحدود"]},{"id":589,"question":"إذا عفا أهل القتيل هل لولي الأمر أن يعزّره بالحبس أو الجلد؟","title":"هل لولي الأمر تعزير القاتل بعد عفو الأولياء؟","answer":"الجواب: الظاهر ما له شيء، الحق لهم.\n(دروس شرح بلوغ المرام، كتاب الجنايات)","link":"https://binbaz.org.sa/fatwas/6423/هل-لولي-الامر-تعزير-القاتل-بعد-عفو-الاولياء","audio":"https://files.zadapps.info/binbaz.org.sa/maram157 - 03 - .mp3","categories":["الجنايات والحدود"]},{"id":590,"question":"إذا قُتل شخص وهو يؤدي عمله: هل يعتبر شهيدًا؟ مثل عسكري في مكافحة المخدرات وقُتل؟","title":"هل يُعتبر شهيدًا كل مسلم قُتل ظلماًا؟","answer":"الجواب: كل مظلوم شهيد.\n(دروس شرح بلوغ المرام، كتاب الجنايات)","link":"https://binbaz.org.sa/fatwas/6424/هل-يعتبر-شهيدا-كل-مسلم-قتل-ظلماا","audio":"https://files.zadapps.info/binbaz.org.sa/maram158 - 04 - .mp3","categories":["الجنايات والحدود"]},{"id":591,"question":"دية المرأة مثل دية الرجل؟","title":"هل دية المرأة مثل دية الرجل؟","answer":"الجواب: نصف الدية، المرأة نصف الدية.\n(دروس شرح بلوغ المرام، كتاب الجنايات)","link":"https://binbaz.org.sa/fatwas/6425/هل-دية-المراة-مثل-دية-الرجل","audio":"https://files.zadapps.info/binbaz.org.sa/maram159 - 03 - .mp3","categories":["الجنايات والحدود"]},{"id":592,"question":"إذا قتل مسلم كافرًا عن طريق الخطأ؟","title":"ما الحكم لو قتل مسلمٌ كافرًا بالخطأ؟","answer":"الجواب: المسلم لا يُقاد بالكافر، فيه الدية ولو عمد، لكن لو كان عمدًا يعزَّر مع الدية، أما إذا كان خطأ فما فيه إلا الدية، يقول ﷺ: لا يُقتل مسلم بكافر.\n(دروس شرح بلوغ المرام، كتاب الجنايات)","link":"https://binbaz.org.sa/fatwas/6426/ما-الحكم-لو-قتل-مسلم-كافرا-بالخطا","audio":"https://files.zadapps.info/binbaz.org.sa/maram160 - 03 - .mp3","categories":["الجنايات والحدود"]},{"id":593,"question":"إذا كان الطبيب عارفًا بالطب وأخطأ في تشخيص المريض فهل يضمن؟","title":"هل يضمن الطبيب عن الخطأ في التشخيص؟","answer":"الجواب: إذا كان عارفًا بالطب واجتهد فما يضمن.\n(دروس شرح بلوغ المرام، كتاب الجنايات)","link":"https://binbaz.org.sa/fatwas/6432/هل-يضمن-الطبيب-عن-الخطا-في-التشخيص","audio":"https://files.zadapps.info/binbaz.org.sa/maram161 - 01 -  Start.mp3","categories":["الجنايات والحدود","الطب والتداوي"]},{"id":594,"question":"دية الأنملة؟","title":"ما دية الأنملة من الأصبع؟","answer":"الجواب: على حسب الأصبع، إن كان ثلاث فثلث الأصبع، والإبهام فيه مفصلان فنصف الأصبع.\n(دروس شرح بلوغ المرام، كتاب الجنايات)","link":"https://binbaz.org.sa/fatwas/6433/ما-دية-الانملة-من-الاصبع","audio":"https://files.zadapps.info/binbaz.org.sa/maram162 - 01 -  Start.mp3","categories":["الجنايات والحدود"]},{"id":595,"question":"س: المقتول غيلة إذا عفا أولياؤه؟","title":"هل يجوز عفو الأولياء عن القاتل غيلة؟","answer":"الجواب: ليس لهم، لا بدّ من قتله؛ سدًّا لباب الشر وحماية المسلمين من الفساد.\n(دروس شرح بلوغ المرام، كتاب الجنايات)","link":"https://binbaz.org.sa/fatwas/6434/هل-يجوز-عفو-الاولياء-عن-القاتل-غيلة","audio":"https://files.zadapps.info/binbaz.org.sa/maram163 - 02 - .mp3","categories":["الجنايات والحدود"]},{"id":596,"question":"إذا كان السكران يقود سيارة فقتل اثنين أو ثلاثة فهل يسمحون عن هذا السكران؟","title":"هل يجوز مسامحة السائق المتهاون في القتل؟","answer":"الجواب: الأفضل عدم السماح؛ لأن السماح تشجيع له على الشر، الأوْلى عدم السماح، والدية يأخذونها، وإذا كانوا في غنى عنها يصرفوها في وجوه الخير.\n(دروس شرح بلوغ المرام، كتاب الجنايات)","link":"https://binbaz.org.sa/fatwas/6435/هل-يجوز-مسامحة-الساىق-المتهاون-في-القتل","audio":"https://files.zadapps.info/binbaz.org.sa/maram164 - 03 - .mp3","categories":["الجنايات والحدود"]},{"id":597,"question":"\"العاقلة\" ما المقصود بها؟","title":"ما معنى \"العاقلة\" التي تجب عليها الدية؟","answer":"الجواب: العصبة؛ الأقرب فالأقرب. س: إذا كانوا قبيلة يا شيخ؟ ج: إذا كانوا أغنياء، يُبدأ بالأغنياء، الأقرب فالأقرب.","link":"https://binbaz.org.sa/fatwas/6436/ما-معنى-العاقلة-التي-تجب-عليها-الدية","audio":"https://files.zadapps.info/binbaz.org.sa/maram165 - 03 - .mp3","categories":["الجنايات والحدود"]},{"id":598,"question":"ما المقصود بمن خرج عن الطاعة؟","title":"ما المقصود بـ \"من خرج عن الطاعة\"؟","answer":"الجواب: طاعة ولي أمر البلد.\n(دروس شرح بلوغ المرام، كتاب الجنايات)","link":"https://binbaz.org.sa/fatwas/6437/ما-المقصود-بـ-من-خرج-عن-الطاعة","audio":"https://files.zadapps.info/binbaz.org.sa/maram166 - 01 -  Start.mp3","categories":["الجنايات والحدود"]},{"id":599,"question":"الأمر في قوله تعالى: فَقَاتِلُوا الَّتِي تَبْغِي حَتَّى تَفِيءَ[الحجرات:9] للوجوب؟","title":"هل الأمر للوجوب في: {فَقَاتِلُوا الَّتِي تَبْغِي..}؟","answer":"الجواب: نعم؛ للوجوب.\n(دروس شرح بلوغ المرام، كتاب الجنايات)","link":"https://binbaz.org.sa/fatwas/6438/هل-الامر-للوجوب-في فقاتلوا-التي-تبغي","audio":"https://files.zadapps.info/binbaz.org.sa/maram260 - 01 -  Start.mp3","categories":["الجنايات والحدود"]},{"id":601,"question":"البُغاة هل تقام عليهم الحدود إن سرقوا أو قطعوا الطريق؟","title":"هل يُعامَل البُغاة معاملة قطاع الطريق؟","answer":"الجواب: نعم يُعاملون معاملة قطاع الطريق إنْ قطعوا الطريق.\n(دروس شرح بلوغ المرام، كتاب الجنايات)","link":"https://binbaz.org.sa/fatwas/6440/هل-يعامل-البغاة-معاملة-قطاع-الطريق","audio":"https://files.zadapps.info/binbaz.org.sa/maram168 - 01 -  Start.mp3","categories":["الجنايات والحدود"]},{"id":602,"question":"معنى: يريد أن يَفَرِّق جماعتكم؟","title":"ما معنى \"يريد أن يَفَرِّق جماعتكم\" بالحديث؟","answer":"الجواب: يعني يشق العصا حتى الناس يختلفوا[1].","link":"https://binbaz.org.sa/fatwas/6441/ما-معنى-يريد-ان-يفرق-جماعتكم-بالحديث","audio":"https://files.zadapps.info/binbaz.org.sa/maram169 - 01 -  Start.mp3","categories":["الجنايات والحدود"]},{"id":603,"question":"في قوله تعالى:إِنَّمَا جَزَاءُ الَّذِينَ يُحَارِبُونَ اللَّهَ وَرَسُولَهُ وَيَسْعَوْنَ فِي الْأَرْضِ فَسَادًا أَنْ يُقَتَّلُوا أَوْ يُصَلَّبُوا[المائدة:33] للتنويع أو للتخيير؟","title":"هل جزاء المحاربين لله للتنويع أو للتخيير؟","answer":"الجواب: الصواب أنها للتخيير، وقال بعضهم: للتنويع، ولكن الصواب: للتخيير.\n(دروس شرح بلوغ المرام، كتاب الجنايات)","link":"https://binbaz.org.sa/fatwas/6442/هل-جزاء-المحاربين-لله-للتنويع-او-للتخيير","audio":"https://files.zadapps.info/binbaz.org.sa/maram170 - 03 - .mp3","categories":["الجنايات والحدود"]},{"id":604,"question":"المحارب إذا قَتل وشَوَّه هل يُفعل به مثل ما فعل؟","title":"حكم تمثيل وتشويه المحاربين","answer":"الجواب: هذا لولي الأمر: إن شاء قتله، وإن شاء قطع يده ورجله، وإن شاء صلبه، والتمثيل من جنس العمل يُمثَّل به كما مثل، الجروح قصاص، فإن رأى ولي الأمر التمثيل مثل به، وإن رأى قتله قتله، وإن رأى صلبه صلبه، وإن رأى قطع يده ورجل فعل، الرسول ﷺ  لما جاء أن اليهودي رض رأس الجارية رض رأسه؛ لأنه قصاص.\n(دروس شرح بلوغ المرام، كتاب الجنايات)","link":"https://binbaz.org.sa/fatwas/6443/حكم-تمثيل-وتشويه-المحاربين","audio":"https://files.zadapps.info/binbaz.org.sa/maram171 - 03 - .mp3","categories":["الجنايات والحدود"]},{"id":605,"question":"الزاني إذا كان غير مُحْصَن ثم زنا مرة أخرى هل يعتبر حده حد الرجم؟","title":"بِم يكون الزاني \"مُحْصَنَا\"؟","answer":"الجواب: لا، لا يكون مُحْصَنًا إلا بالزوجة الشرعية إذا وطئها.\n(دروس شرح بلوغ المرام، كتاب الجنايات)","link":"https://binbaz.org.sa/fatwas/6444/بم-يكون-الزاني-محصنا","audio":"https://files.zadapps.info/binbaz.org.sa/maram172 - 03 - .mp3","categories":["الجنايات والحدود"]},{"id":606,"question":"الحكمة في قتل المرتدين؟","title":"ما الحكمة من قتل المرتدين؟","answer":"الجواب: في أمرين: جزاء له على ما صنع، وعدم توبته. وردعًا لغيره.\n(دروس شرح بلوغ المرام، كتاب الجنايات)","link":"https://binbaz.org.sa/fatwas/6445/ما-الحكمة-من-قتل-المرتدين","audio":"https://files.zadapps.info/binbaz.org.sa/maram173 - 03 - .mp3","categories":["الجنايات والحدود"]},{"id":708,"question":"من المعلوم أنَّ الحدود إذا رُفعت إلى القاضي لا يجوز إسقاطها ولا الشَّفاعة فيها، فهل تصح الشفاعة فيها أو التنازل عنها عندما تكون عند جهة التَّحقيق –الشرطة- وقبل أن تُرفع إلى القاضي؟","title":"حكم الشفاعة في الحدود بعد رفعها للشرطة","answer":"الجواب: هذا محلُّ نظرٍ؛ لأنَّ جهة الشرطة جهة حكومية ومُبلّغة بتنفيذ الأوامر، فهي جزءٌ من السلطان، فالواجب بعد رفعه إلى السلطان التَّنفيذ، فالذي يظهر -والله أعلم- أنه بعد وصول الجناية إلى الشرطة أو إلى المحكمة أو إلى الإمارة لا يجوز تركها، بل يجب أن تُقام الحدود. أما ما دامت فيما بين الجيران وبين الناس ولم تصل إلى مركزٍ حكوميٍّ فلا مانع أن يستروها وينصحوه ويُوبِّخوه ولا يُفشوها عليه، ومَن ستر مسلمًا ستره الله في الدنيا والآخرة.","link":"https://binbaz.org.sa/fatwas/20579/حكم-الشفاعة-في-الحدود-بعد-رفعها-للشرطة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0532فتاوى المحاضرات للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["الجنايات والحدود"]},{"id":711,"question":"رجلٌ عقد على امرأةٍ ولم يدخل بها، ثم زنا بأمِّها -والعياذ بالله- هل يجوز الدُّخول بالبنت؟ مع العلم أنه بعد ذلك دخل بالبنت وأنجب منها، فما حكم الزَّواج؟","title":"هل يجوز لرجلٍ الزواج ببنتٍ زنا بأمها؟","answer":"الجواب: الصحيح أنه يدخل بالبنت، وأن الزنا لا يُحرِّمها عليه؛ لأن الزنا محرَّم، ولا تجوز إشاعته، ولا يُحَرِّم الحلالَ، وهو عاصٍ في زناه، وعليه التوبة إلى الله، والرجوع إليه، والإنابة إليه، وزوجته تبقى معه، ولا تحرم عليه في أصح قولي العلماء ولو زنا بأمِّها -نسأل الله العافية- كما لو زنا ببنتها.\nالمقصود أنها لا تَحْرُم عليه، وتبقى زوجته في عصمته على الصحيح، وعليه التوبة إلى الله، ومتى عُلم ذلك يُقام عليه الحدّ الشرعي، وإذا كان بينه وبين الله فعليه التوبة، وألا يُفشي ذلك، وألا يُبينه لأحدٍ، وألا يقوله لأحدٍ، فليكن بينه وبين الله .\nوذهب بعضُ أهل العلم إلى أنها تحرم عليه البنت، وأن عليه فراقها؛ لأنه استحلَّ أمَّها، ولكنه قول مرجوح، والصواب أنها لا تحرم عليه، وأن نكاحه باقٍ، وعليه التوبة إلى الله، ويُقام عليه الحدُّ إذا عُرف ذلك وثبتت البينة، أما إن كان بينه وبين الله فعليه أن يستتر بستر الله، ولا يُبينه لأحدٍ، ويتوب إلى الله توبةً صادقةً، فمَن تاب تاب الله عليه.","link":"https://binbaz.org.sa/fatwas/20574/هل-يجوز-لرجل-الزواج-ببنت-زنا-بامها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0528فتاوى المحاضرات للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["شروط وأركان الزواج","الجنايات والحدود"]},{"id":763,"question":"شخصٌ يسأل: أنه قبل ثلاث عشرة سنة، وفي ليلةٍ مظلمةٍ، ومعه زميله، شعرا بارتطامٍ في السيارة، وبعد مسافةٍ عادا فوجدا شخصًا يحتضر، فهربا، وقد توفي هذا الشخص، والآن وبعد ثلاث عشرة سنة يُريدان أن يعملا شيئًا يُكفِّرا به عن عملهما هذا، فما هو جزاكم الله عنا خيرًا؟","title":"ما حكم من قَتَل بالخطأ وهرب لسنوات؟","answer":"الجواب: عليهم ثلاثة أمور، على الداعس الذي تولى السيارة -صاحب السيارة الذي يتولاها- ثلاثة أمور:\nالأمر الأول: التوبة إلى الله مما حصل منه، ومن الهروب وعدم أداء الواجب.\nوالأمر الثاني: التَّكفير بعتق رقبةٍ مؤمنةٍ، فإن عجز صام شهرين مُتتابعين.\nوالأمر الثالث: أداء الدِّية لأهل الميت إن عرفهم، فإن لم يعرفهم تصدَّق بها عنهم، الدية المعروفة ذاك الوقت يُؤديها للفقراء والمساكين صدقةً عن أهل الميت إذا كان لا يعرفهم.\nهذه أمور ثلاثة:\nأولًا: التوبة إلى الله، والإنابة إليه، واستغفاره، والندم على ما مضى منه من التَّساهل والهروب.\nوالأمر الثاني: أنَّ عليه كفَّارةً، وهي عتق رقبةٍ مؤمنةٍ إذا تيسر له ذلك، ويوجد رقاب في بعض إفريقيا تُباع بما يُقارب عشرة آلاف، وقد اشترينا منها رقابًا كثيرةً بواسطة مندوبنا هناك، فإن عجز يصوم شهرين متتابعين -ستين يومًا- لأنَّ الله أوجب هذا  في كتابه العظيم، قال سبحانه: وَمَنْ قَتَلَ مُؤْمِنًا خَطَأً فَتَحْرِيرُ رَقَبَةٍ مُؤْمِنَةٍ وَدِيَةٌ مُسَلَّمَةٌ إِلَى أَهْلِهِ إِلَّا أَنْ يَصَّدَّقُوا إلى أن قال: وَإِنْ كَانَ مِنْ قَوْمٍ بَيْنَكُمْ وَبَيْنَهُمْ مِيثَاقٌ فَدِيَةٌ مُسَلَّمَةٌ إِلَى أَهْلِهِ وَتَحْرِيرُ رَقَبَةٍ مُؤْمِنَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ تَوْبَةً مِنَ اللَّهِ [النساء:92].\nفالمقصود أنه إن كان مسلمًا فعليه أن يُؤدي الدية إلى ورثته، وإن كان من أهل الكفر المستأمنين والذين بيننا وبينهم ميثاقٌ أو جاؤوا إلى بلادنا مُستأمنين ثم قُتلوا خطأً فعليك أيضًا الكفَّارة مع الدية؛ لأن الله أوجب هذا فقال: وَإِنْ كَانَ مِنْ قَوْمٍ بَيْنَكُمْ وَبَيْنَهُمْ مِيثَاقٌ فَدِيَةٌ مُسَلَّمَةٌ إِلَى أَهْلِهِ وَتَحْرِيرُ رَقَبَةٍ مُؤْمِنَةٍ [النساء:92]، فأوجب الدية والتَّحرير جميعًا، وقوله: بَيْنَكُمْ وَبَيْنَهُمْ مِيثَاقٌ يعمُّ مَن له عهدٌ عندنا، ومَن هو مُستأمَنٌ عندنا، ومَن له ذمَّة عندنا، كلهم يُودون وتجب الكفَّارة في قتلهم خطأً.\nفإذا كان لا يعرف أهلَ القتيل تصدَّق بها في وجوه البر والإحسان بالنية عنهم.","link":"https://binbaz.org.sa/fatwas/20676/ما-حكم-من-قتل-بالخطا-وهرب-لسنوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0581ما حكم الشرع في شخص دعس شخصاً آخر بالخطأ ومات ثم هرب؟ ابن باز فتاوى المحاضرات.mp3","categories":["الجنايات والحدود"]},{"id":932,"question":"أحد الإخوان يقول: إنَّ له قريبًا سافر على الطريق البري، فوقع له حادثٌ، أدَّى هذا الحادثُ إلى وفاة الزوجة، فهل يلزمه الصوم أم لا؟","title":"حكم من توفيت زوجته في حادث بسيارته","answer":"الجواب: هذا فيه تفصيلٌ، الحوادث فيها تفصيلٌ: إذا كان له تسبّب لزمه الكفَّارة؛ لأنه بسبب عجلته وعدم سيره السير المعتاد، أو نوم، أو أسباب أخرى، يلزمه الضَّمان، وعليه الكفَّارة. أما إذا كان على وجهٍ ليس فيه تفريطٌ أو تعدَّى غيرُه عليه، ما تعدَّى هو، تعدَّى غيرُه عليه، فالمتعدِّي هو الضَّامن، أو هو يمشي المشي المعتاد، ولكن انطلق الكَفَر، والكَفَر سليم، ما يعلم فيه، مضبوط الكَفَر، وانطلق عليه وهو يمشي المشي المعتاد، فهذا ليس عليه فيه شيءٌ، مثل: لو كان على مطيةٍ هو ورديفه وخمعت المطية وهم يمشون المشي المعتاد، أو جفلت، ليس عليه شيء.\nوهذا يُرجع فيه إلى المرور وضبط الأحداث: كيف صار الحادثُ؟ ثم إلى المحاكم، هذه يُرجع فيها إلى ما ضبطه الموكَّلون بالمرور، واعتنوا به، ثم ما يتعلق بالمحكمة.\nفالحاصل أنَّ الإنسان يجب عليه الحذر، والبُعد عن أسباب الخطر، وعدم العجلة، ويتحرّى ويحذر ولا يتساهل في هذه الأمور، يجب عليه أن يكون في غايةٍ من الحذر، ويحذر العجلة، أكثر ما يُصيب الناس العجلة، وعدم التَّأني، وعدم الركود، وقد يُؤتى من جهة النّعاس، يكون قد أطال السَّهر فيُصيبه النعاس، ويضرُّ نفسه، ويضرُّ مَن معه، وقد يكون بتعاطي بعض المخدرات والمسكرات، وهذا أيضًا ضامنٌ ومُجرمٌ، المقصود: يجب عليه الحذر من أسباب الحوادث.","link":"https://binbaz.org.sa/fatwas/20981/حكم-من-توفيت-زوجته-في-حادث-بسيارته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0777شخص سافر على الطريق البري فوقع له حادث وأدى إلى وفاة الزوجة فهل يلزمهُ الصوم أم لا؟ابن باز.mp3","categories":["الجنايات والحدود"]},{"id":948,"question":"مَن قتل جنينًا في بطن أمه عن طريق الخطأ، ولم يستطع دفع الدية، فهل عليه صيام؟","title":"حكم مَن قتل جنينًا بالخطأ ولا يستطيع الدية","answer":"الجواب: قيمتها عُشر قيمة أمه، خمس من الإبل من الدية، الدية مئة من الإبل، فالمرأة نصفها: خمسون، وقيمة الغُرَّة خمسٌ من الإبل، يلزمه أداؤها، وإذا كان مُعسرًا يُمهل، وهي في ذمَّته دَينٌ. وعليه الكفَّارة إذا كان الولدُ قد نُفخت فيه الروح، وقتله بعد الأربعة أشهر، فعليه كفَّارة وعليه الدية. أما إن كان لم تُنفخ فيه الروح، ولكنه قد بان فيه خلق الإنسان؛ فعليه الغُرَّة فقط، دون الكفَّارة.","link":"https://binbaz.org.sa/fatwas/20989/حكم-من-قتل-جنينا-بالخطا-ولا-يستطيع-الدية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0785من قتل جنيناً في بطن أمه عن طريق الخطأ ولم يستطع دفع الدية فهل عليه صيام؟ ابن باز.mp3","categories":["الجنايات والحدود"]},{"id":953,"question":"إذا كان المُتسبب في الحادث نسبة الخطأ عليه 25%، فهل عليه كفَّارة صيام شهرين؟","title":"هل تتجزَّأ الكفارة للمُشترِك في قتل شبه خطأ؟","answer":"الجواب: الكفَّارة لا تُبَعَّض، إذا اشتركوا في الحادث عليهم الكفَّارة جميعًا، كل واحدٍ عليه كفَّارة، فلو كانوا أربعةً كل واحدٍ عليه 25%، عليهم أربع كفَّارات، كل واحدٍ عليه كفَّارة، ما تُبعض الكفَّارة.\nأما الدية: فكل واحدٍ عليه الربع، لكن الكفَّارة ما تُبعض، ولو كان واحدٌ عليه 20%، وواحد عليه 30%، وواحد 50%، عليهم ثلاث كفَّارات، كل واحدٍ عليه كفَّارة؛ لأنَّ الكفَّارة لا تتبعض، هذا الذي عليه عامَّة أهل العلم، كلٌّ عليه كفَّارة مُستقلة لما وقع فيه من الخطأ.","link":"https://binbaz.org.sa/fatwas/20991/هل-تتجزا-الكفارة-للمشترك-في-قتل-شبه-خطا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0788إذا كان المتسبب في الحادث شبة الخطأ عليه خمسة وعشرين بالمئة فهل عليه كفارة؟ ابن باز.mp3","categories":["الجنايات والحدود"]},{"id":966,"question":"لقد زنيتُ بامرأةٍ متزوجةٍ عقيم زوجها، وأنجبتُ منها ولدًا، وتبتُ إلى الله، وبقي ضميري يُؤنِّبني، فهل أُخبر زوجَها وقد ضمَّ إليه مَن ليس بابنه؟","title":"حكم مَن زنى بامرأة زوجها عقيم وأنجبت","answer":"الجواب: لا تُخبر زوجها، وعليك التوبة إلى الله، والولد للفراش، والعاهر له الحَجَر، لك الحَجَر أنت، وإذا تبتَ تاب الله عليك، ولا تُخبر أحدًا بذلك، وعليك بستر الله .","link":"https://binbaz.org.sa/fatwas/21016/حكم-من-زنى-بامراة-زوجها-عقيم-وانجبت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0813يقول السائل لقد زنيت بامرأة متزوجة عقيم زوجها وانجبت منها ولداً وتبت إلى الله فهل أخبر زوجها؟.mp3","categories":["الجنايات والحدود"]},{"id":1049,"question":"الطفل الذي يُولد من امرأةٍ زُرع في رحمها البويضة المُلقحة خارج الرحم من امرأةٍ غيرها ورجلٍ غريب؟","title":"حكم البويضة المُلقّحة من غير الزوج","answer":"الجواب: إذا زُرعت فيها النُّطفة ليست من زوجها فهو في حكم الزنا، فالولد يُنسب إليها، الولد لها هي فقط، ولا يُنسب إلى أبيه الذي هو بحكم الزاني، ولا إلى أمه التي لا أساسَ لها إلا أنها زُرعت منها البُويضة، يكون للتي ولدته: إِنْ أُمَّهَاتُهُمْ إِلَّا اللَّائِي وَلَدْنَهُمْ [المجادلة:2]، يُنسب إلى أمه التي ولدته، والنُّطفة التي نُزعت من الشخص الأجنبي والمرأة الأجنبية ليس لهما فيها نصيبٌ. ولا يجوز هذا العمل، هذا ما يجوز، وقد درس هذا مجمعُ الفقه أيضًا وقرر تحريم هذا، أنه لا يجوز إلا إذا كان من زوجٍ فقط، أما من شخصٍ أجنبيٍّ أو امرأةٍ أجنبيةٍ فهذا لا يجوز، لا بدّ أن يكون من مائه ومائها فقط: من ماء الزوج، وماء المرأة فقط.","link":"https://binbaz.org.sa/fatwas/21106/حكم-البويضة-الملقحة-من-غير-الزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0902الطفل الذي يولد من أمراءة زُرِعً في رحمها البويضة الملقحة من أمراءة غيرها ورجل غير زوجها.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":1058,"question":"هل إيقاف العلاج عن المريض الذي يُقرّ الأطباء عدم إمكانية شفائه جائز شرعًا أم لا؟","title":"ما حكم إيقاف العلاج عمن لا يُرجى شفاؤه؟","answer":"الجواب:\nهذا فيه تفصيل، قد درسه المجمع الفقهي بمكة برئاستي، درسه الإخوان العلماء وبيَّنوا أنه يجب العلاج والعناية حسب الطاقة على المسؤولين، وإذا علموا أنه لا فائدة في الطب، وأن الدواء لا ينفع ولا يفيد؛ فلا بأس أن يتركوه ويدعوه؛ لأن المقصود من الدواء الفائدة، فإذا عُلم من الأطباء المباشرين أن هذا الدواء لا يُفيد ولا ينفع، بل قد يضرّ فلا..... ويُترك لأمر الله، إلا إذا وجدوا شيئًا يُعين على الحياة، أو ينفع بنفسه، فليفعلوا: من شرابٍ، من إبرٍ، أو من تبريدٍ، أو غير هذا مما يُعرف، أما إذا كان حسب علمهم لا يفيد؛ فلا بأس بتركه.","link":"https://binbaz.org.sa/fatwas/21095/ما-حكم-ايقاف-العلاج-عمن-لا-يرجى-شفاوه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0891هل إيقاف العلاج عن المريض الذي يقرُّ الأطباء عدم أمكانية شفاءه جائز شرعاً؟ ابن باز.mp3","categories":["الجنايات والحدود"]},{"id":1221,"question":"يقول أنَّ امرأته احتاجت إلى ضرب إبرٍ لها وهي حامل، فضربها بنفسه، ثم تُوفي الجنين وخرج ميتًا مُشوَّهًا، وهو يتوجَّس بهذا العمل، فهل عليه من شيءٍ؟","title":"حكم الدية في قتل الجنين بالخطأ","answer":"الجواب:\nإذا عرف بأقوال أهل الخبرة أنه سقط بأسباب الإبرة يكون قتل خطأ، عليه الدية والكفَّارة هو والطبيبة والمرأة.  أما إذا لم يعرف فليس عليه شيءٌ، إذا لم يدرِ عن أسباب سقوطه ليس عليه.  أما إذا عرف أن سقوطه وإجهاضها له بأسباب الإبرة فعلى مَن ضربها بالإبرة الضَّمان والكفَّارة، إلا أن يسمحوا عنه فتكون عليه الكفَّارة فقط.  أما إذا كان غرَّه وقال: الإبرة ما تُخالف، وضربها، وكان قرر الأطباء -اثنان من الأطباء فأكثر من أهل الخبرة والأمانة- أن السقوط بأسباب الإبرة؛ يكون قتلًا خطأ.","link":"https://binbaz.org.sa/fatwas/21277/حكم-الدية-في-قتل-الجنين-بالخطا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1117أمراءة أحتاجت إلى أبر وهي حامل فتوفي الجنين خرج مشوهاً فهل عليها شيء؟.mp3","categories":["الجنايات والحدود"]},{"id":1268,"question":"ما حكم الشرع في خطأ الطبيب حديث التَّخرج وقليل الخبرة، وهو غير متعمدٍ؟","title":"ما حكم خطأ الطبيب حديث التَّخرج دون عمد؟","answer":"الجواب:\nإذا كان ما بعد حَذِقَ الطبَّ يضمن، أما إن كان حَذِق ومعه الشَّهادة التي تُؤهله لذلك؛ فلا يضمن إذا اجتهد، يقول النبيُّ ﷺ: مَن تطبّب ولم يكن بالطبِّ معروفًا، فأصاب نفسًا وما دونها فهو ضامنٌ. أما إن كان معروفًا بالطب: قد تخرج، وقد عرف هذه الأشياء، وشُهد له بالحذق فيها، وأتاها على بصيرةٍ، ثم غلط؛ فإنه ما يضمن.","link":"https://binbaz.org.sa/fatwas/21337/ما-حكم-خطا-الطبيب-حديث-التخرج-دون-عمد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1080ما حكم الشرع في خطأ الطبيب حديث التخرج وقليل الخبرة وغير متعمد؟ ابن باز.mp3","categories":["الجنايات والحدود"]},{"id":1353,"question":"معاقبة الرجل بأخذ ماله، بأخذ غرامة عليه، جائز هذا؟","title":"ما حكم العقاب بالتغريم بالمال؟","answer":"الجواب:\nهذا فيه تفصيل:  إذا رآه ولاة الأمور لجريمته؛ تجوز المعاقبة بالمال، النبي ﷺ قال لمن منع الزكاة: إنا آخذوها وشَطَرَ ماله والذي يأخذ من الثمر، يسرق من الثمر، أمر النبي ﷺ بمعاقبته بمِثْلَي ما أخذ وجَلَدات أيضاً. وإذا رأى ولي الأمر على حسب قواعد الشرع، ما هو بالهوى، على حسب القواعد الشرعية.","link":"https://binbaz.org.sa/fatwas/21446/ما-حكم-العقاب-بالتغريم-بالمال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم العقاب بالتغريم.mp3","categories":["الجنايات والحدود"]},{"id":1435,"question":"إذا كان المقتولُ قتله القاتلُ على خطإٍ، هل القاتل يدخل في الحكم؟","title":"هل على القاتل خطأ شيء غير الكفارة والدية؟","answer":"الجواب:\nلا، القاتل ما عليه شيء، إنما عليه الدية والكفَّارة، فالله جل وعلا بيَّن: وَمَا كَانَ لِمُؤْمِنٍ أَنْ يَقْتُلَ مُؤْمِنًا إِلَّا خَطَأً وَمَنْ قَتَلَ مُؤْمِنًا خَطَأً فَتَحْرِيرُ رَقَبَةٍ مُؤْمِنَةٍ وَدِيَةٌ مُسَلَّمَةٌ إِلَى أَهْلِهِ [النساء:92]، عليه الدية، وعليه الكفارة، فتعظيمًا لشأن القتل جاءت فيه الكفارة مع أنه خطأ.","link":"https://binbaz.org.sa/fatwas/21530/هل-على-القاتل-خطا-شيء-غير-الكفارة-والدية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من قتل خطأ فما الحكم.mp3","categories":["الجنايات والحدود"]},{"id":1458,"question":"الأشهر الحرم تُقام فيها الحدود؟","title":"هل يجوز إقامة الحدود في الأشهر الحرم؟","answer":"الجواب:\nنعم تُقام فيها الحدود، والجهاد في سبيل الله مشروعٌ عند الجمهور، وتحريمه منسوخ.","link":"https://binbaz.org.sa/fatwas/21555/هل-يجوز-اقامة-الحدود-في-الاشهر-الحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تقام الحدود في الأشهر الحرم.mp3","categories":["الجنايات والحدود"]},{"id":1467,"question":"في سفك الدماء: إذا زنى الزاني بالبِكْر فهل يكون داخلًا في سفك الدماء؟","title":"هل يدخل فض البكارة بالزنى في سفك الدماء؟","answer":"الجواب:\nسفك الدماء غير هذا، سفك الدماء ظلم الناس، فهو ليس زنًا، هذا حكمه حكم الزنا: وَلَا تَقْرَبُوا الزِّنَا إِنَّهُ كَانَ فَاحِشَةً وَسَاءَ سَبِيلًا [الإسراء:32]، فالزنا شرُّه عظيمٌ، ومن أقبح الظلم، ومن أقبح الفساد في الأرض، وعليه الحدُّ الشرعي مع التوبة إلى الله جلَّ وعلا.\nس: إذهاب البكارة ما يكون منه؟\nج: هذا شيء آخر، المقصود أن الزنا غير هذا الأمر.","link":"https://binbaz.org.sa/fatwas/21564/هل-يدخل-فض-البكارة-بالزنى-في-سفك-الدماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يدخل إذهاب البكارة بالزنى في سفك الدماء.mp3","categories":["الجنايات والحدود"]},{"id":1493,"question":"حدّ الزنا للأمة خمسون جلدة؟","title":"ما حدّ الزنا للأمَة؟","answer":"الجواب:\nنعم، حدُّها نصف حدِّ الحرة، خمسون جلدة: فَعَلَيْهِنَّ نِصْفُ مَا عَلَى الْمُحْصَنَاتِ مِنَ الْعَذَابِ [النساء:25].","link":"https://binbaz.org.sa/fatwas/21591/ما-حد-الزنا-للامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حدّ الزنا للأمة.mp3","categories":["الجنايات والحدود"]},{"id":1584,"question":"أحيانًا قد يوجد في بعض التحقيقات من قبل الشرطة أنَّه يُعذَّب بعض مَن اتُّهم بالجناية ونحو ذلك، هل عملهم هذا جائز؟","title":"ما حكم تعذيب المُجْرِم المتهم؟","answer":"الجواب:\nتعذيب المتهم لا بأس به إذا صار متهمًا، فالنبي ﷺ أمر بعمِّ حُيي بن أخطب أن يُعَذَّب حتى يقرَّ بالكنز الذي خلفه حُيي من الذهب، لما قال: \"أكلته النفقة يا رسول الله!\" قال: لا، المدة قصيرة والمال كثير، وأمر الزبير أن يمسه بعذابٍ حتى يُقِرَّ.","link":"https://binbaz.org.sa/fatwas/21687/ما-حكم-تعذيب-المجرم-المتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تعذيب المتهم.mp3","categories":["الجنايات والحدود"]},{"id":1782,"question":"في دية الجنين \"غُرَّة عبدٍ\" ما المقصود بها؟","title":"ما معنى \"غُرَّة عَبْد\" في دية الجنين؟","answer":"الجواب:\nعَبْدٌ أو أمَة.\nس: الغُرَّة هنا ما المقصود بها؟\nج: هي العبد أو الأمة، تفسيرها: غُرَّةٌ: عَبْدٌ أو أمَة.\nس: لا بد أن تكون بيضاء؟\nج: لا، ما هو بلازم.","link":"https://binbaz.org.sa/fatwas/21889/ما-معنى-غرة-عبد-في-دية-الجنين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بغرة عبد في دية الجنين.mp3","categories":["الجنايات والحدود"]},{"id":1784,"question":"مَن قتل إنسانًا بالنار يُعَزَّر؟","title":"ما حكم من قتل إنسانًا بحرقه بالنار؟","answer":"الجواب:\nالظاهر أنَّه قصاص....؛ لأنَّ الله قال: وَلَكُمْ فِي الْقِصَاصِ حَيَاةٌ [البقرة:179]، كُتِبَ عَلَيْكُمُ الْقِصَاصُ [البقرة:178].","link":"https://binbaz.org.sa/fatwas/21891/ما-حكم-من-قتل-انسانا-بحرقه-بالنار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من قتل إنسانا بالنار.mp3","categories":["الجنايات والحدود"]},{"id":1785,"question":"تحريق العدو بالنار، للكفار؟","title":"حكم إحراق العدو الكافر بالنار والتمثيل به","answer":"الجواب:\nلا، ما يُحَرَّقون إلا إذا حرَّقوا.\nس: يعني من باب المقابلة؟\nج: نعم.\nس: كذلك المُثْلَة؟\nج: من باب القِصاص كذلك، لكن ترك المُثْلة أولى؛ لقوله ﷺ: ولا تُمَثِّلوا.\nس: حتى ولو مثَّلوا؟\nج: تركها أوْلى، ولو مثَّلوا.\nس: علي بن أبي طالب  أحرق شيعته؟\nج: أنكر عليه الصحابةُ ، وهو من شدة غضبه عليهم خدَّ لهم أخاديد في النار وعذَّبهم؛ لأنهم قالوا: أنت الله -نسأل الله العافية- فمن شدة غضبه عليهم حرَّقهم، لكن مثلما قال ابن عباس: \"لو أنَّه قتلهم بالسيف لكان أوْلى\"، وهذا هو الواجب؛ لأنَّ كلام النبي ﷺ لا يُقدَّم عليه أحدٌ، لا كلام علي، ولا غير علي، كلام النبي مُقدَّمٌ على الجميع، عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/21892/حكم-احراق-العدو-الكافر-بالنار-والتمثيل-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إحراق العدو بالنار وحكم المُثْلَة به.mp3","categories":["الجنايات والحدود"]},{"id":1786,"question":"في بعض الأماكن كالسّجون ونحوها يُعَذَّب بعضُ الناس بآلات الكهرباء؛ لكونهم مُذنبين؟","title":"حكم تعذيب الجُناة في السجون ونحوها","answer":"الجواب:\nلا ما يجوز هذا، إذا كان يستحق الأدب يُؤَدَّب، مثل: إقامة حد القذف، وحد التعزير، أما التعزير بالنار أو الآلات الكهربائية فلا يجوز.\nس: أو قتله مثلًا بالصعق؟\nج: لا يجوز قتله بتقطيع الأعضاء: إذا قتلتم فأحسنوا القتلة.","link":"https://binbaz.org.sa/fatwas/21893/حكم-تعذيب-الجناة-في-السجون-ونحوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تعذيب الجناة.mp3","categories":["الجنايات والحدود"]},{"id":1902,"question":"بعض الناس يقتلون أنفسَهم بسبب فلان أو فلان أو فلان، هل على فلانٍ هذا حسابٌ يوم القيامة؟","title":"ما جزاء مَن يقتل نفسه؟","answer":"الجواب:\nيقول النبيُّ ﷺ: مَن قتل نفسَه بشيءٍ عُذِّبَ به يوم القيامة، فلا يجوز أن يقتل نفسَه من أجل فلان أو فلان، أو الدفاع عن فلان، لا، يُدافع عنه لكن لا يقتل نفسَه.\nس: هل على فلانٍ حساب؟\nج: الحساب إلى الله، هو الذي يُحاسبه، إن شاء عفا وغفر ، فالأمر إليه ، يُعذِّب مَن يشاء، ويرحم مَن يشاء، فيما دون الشرك، يعني: في المعاصي.","link":"https://binbaz.org.sa/fatwas/22014/ما-جزاء-من-يقتل-نفسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/جزاء من قتل نفسه.mp3","categories":["الجنايات والحدود"]},{"id":1918,"question":"عمل الغلام صاحب الأخدود الذي قال للملك: خُذْ سهمًا من كنانتي .. فإن فعلتَ ذلك قتلتني، هل هذا نوعٌ من التَّهلكة أو من الجهاد في سبيل الله؟","title":"حكم تفجير النفس في الجهاد للإضرار بالعدو","answer":"الجواب:\nهذا شرع مَن قبلنا، جعله الله لهم، ما هو بشرعٍ لنا، شرعنا تحريم القتل، فالإنسان لا يقتل نفسه ولا يأذن في قتل نفسه إلا في الجهاد.\nس: قصدي مَن يأخذه في التفجيرات؟\nج: ما يجوز، التفجيرات لا تجوز، كونه يُفجِّر نفسه ما يجوز.\nس: هناك مَن يستدل بهذا على جواز التفجير؟\nج: لا ما يجوز، الرسول نهى عنه، الله يقول: وَلَا تَقْتُلُوا أَنْفُسَكُمْ إِنَّ اللَّهَ كَانَ بِكُمْ رَحِيمًا [النساء:29]، والرسول يقول: مَن قتل نفسَه بشيءٍ عُذِّبَ به يوم القيامة.","link":"https://binbaz.org.sa/fatwas/22031/حكم-تفجير-النفس-في-الجهاد-للاضرار-بالعدو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/عمل الغلام صاحب الأخدود حكم مَن يأخذه في التفجيرات ويستدل به.mp3","categories":["الجنايات والحدود"]},{"id":1952,"question":"امرأة أسقطت جنينها متعمدةً بعدما اكتمل؟","title":"حكم من أسقطت جنينها متعمدة بعد اكتماله","answer":"الجواب:\nعليها التوبة إلى الله، وعليها الدية، وعليها التعزير، ينبغي أن تُعزر وتُؤَدَّب.\nس: ما عليها كفارة؟\nج: لا، إن كان عمدًا ما فيه كفَّارة، الكفَّارة في الخطأ وشبه العمد.","link":"https://binbaz.org.sa/fatwas/22066/حكم-من-اسقطت-جنينها-متعمدة-بعد-اكتماله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من أسقطت جنينها متعمدة بعد اكتماله.mp3","categories":["الجنايات والحدود"]},{"id":1994,"question":"إذا انتشر الخبر في منكر معين يُقام عليه الحَدُّ؟","title":"هل يقام الحَدُّ بمجرد انتشار الخبر؟","answer":"الجواب:\nلا، لا بدّ من بينة، شاهدين عدلين في جميع الحدود، إلا الزنا لا بدّ من أربعة شهود.\nس: أقصد مع البينة ومع الشهود هل يجوز أن يتغاضوا عنه أم يلزمهم..؟\nالشيخ: يجب إقامة الحد، إذا ثبت وجب إقامته.\nس: ولو لم يبلغ القاضي؟\nالشيخ: يُرفع إلى القاضي.\nس: ولو لم يُرفع؟\nالشيخ: إذا لم يرفع ما عليه شيء، لكن هذا إذا رُفع، إذا ستروا عليه وتاب إلى الله فيما بينه وبين الله؛ ما هو بلزوم.","link":"https://binbaz.org.sa/fatwas/22110/هل-يقام-الحد-بمجرد-انتشار-الخبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يقام الحد بمجرد انتشار الخبر.mp3","categories":["الجنايات والحدود"]},{"id":2103,"question":"ولد لي صار عليه حادث مع رفيقه وتُوفي الراكب....؟","title":"ما كفارة القتل الخطأ المشترك؟","answer":"الجواب:\nإذا كان بأسبابه يصوم شهرين متتابعين.\nس: وإذا كان الخطأ على الاثنين؟\nج: كل واحدٍ منهما عليه شهران.\nس: لكن ولدي هذا حالته الصحية ما يتحمّل الصيام؟\nج: إذا قَدِر..، يبقى في ذمته حتى يتيسر، فليس هناك إلا العتق، والعتق غير متيسر.","link":"https://binbaz.org.sa/fatwas/22221/ما-كفارة-القتل-الخطا-المشترك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كفارة القتل الخطأ المشترك.mp3","categories":["الجنايات والحدود"]},{"id":2181,"question":"يقول السائل: رجل تشاجر مع آخر فأطلق عليه النار، فمات، وهو في السجن الآن، فهل عليه صيام شهرين متتابعين أم لا، علمًا بأنَّه لم يُرد قتله؟","title":"حكم مَن قتل شخصًا في مشاجرة دون قصد","answer":"الجواب:\nإذا كان قد أطلق شيئًا لا يقتل مثله فعليه الكفَّارة؛ لأنه يكون قتل خطأ، أمَّا إذا كان قد رماه بالسيف أو بالبندقية أو بالفرد فهذا يُريد قتله، فيصير قتل عمدٍ، وليس فيه كفَّارة.\nس: هو رماه ببندقية، لكن ما أراد قتله، أراد مثلًا كسر قدمه أو جرحه؟\nج: إذا لم يكن رماه في محل قتلٍ، أو بشيءٍ لا يقتل مثله، كالعصا وشبهها؛ يكون خطأ وعليه الكفَّارة.\nس: أراد أن يرميه بالبندقية مثلًا أو بالسيف ولكن في رِجْلِه لكي يُخوّفه؟\nج: إذا مات بذلك فهو خطأ، وعليه الكفَّارة، مثل المرأة التي قتلت صاحبتها بالعمود، فعليه الكفَّارة والدية –الدية على العصبة.","link":"https://binbaz.org.sa/fatwas/22302/حكم-من-قتل-شخصا-في-مشاجرة-دون-قصد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تشاجر مع آخر فأطلق عليه النار فمات ولم يرد قتله.mp3","categories":["الجنايات والحدود"]},{"id":2264,"question":"إذا رأى الملكُ أن لا يُقام الحدُّ؟","title":"هل يجوز للمَلِك أو الرئيس أن لا يُقيم الحدُّ؟","answer":"الجواب:\nلا، ما يجوز، لا الملك ولا غيره، المصالح في إقامة الحدود، فلا يجوز للملك ولا لرئيس الجمهورية ولا للمسؤولين ترك الحدود إذا كانوا مسلمين، فالحدود تُقام إذا كان الحدُّ لله.","link":"https://binbaz.org.sa/fatwas/22387/هل-يجوز-للملك-او-الرىيس-ان-لا-يقيم-الحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا رأى الملكُ أن لا يُقام الحدُّ.mp3","categories":["الجنايات والحدود"]},{"id":2327,"question":"حديث عائشة في حكم المُرتد في البخاري ومسلم، يقول عليه الصلاة والسلام: يُنْفَى من الأرض ما معنى ذلك؟","title":"ما حكم المرتد في الإسلام؟","answer":"الجواب: مَن بدَّل دينَه فاقتلوه.\nس: يعني: يقتلوه؟\nج: مَن بدَّل دينَه يُسْتَتاب، فإن تابَ وإلا قُتِلَ.","link":"https://binbaz.org.sa/fatwas/22451/ما-حكم-المرتد-في-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم المرتد في الإسلام.mp3","categories":["الجنايات والحدود"]},{"id":2357,"question":"وقع لي حادثٌ وتُوفيت معي ابنتي؟","title":"حكم من عليه صيام كفارة قتل ولا يقدر لمرضه","answer":"الجواب:\nوأيش قال المرورُ عنك؟\nس: عندي سُكَّر، وصار عندي نوع من الغيبوبة، وصار عليَّ حادثٌ، وانقلبتُ، وتُوفِّيت معي ابنتي، والصيام يكلّف عليَّ بسبب السكر، وعندي ضغطٌ، فيقولون: هناك دولة يعتقون فيها الرِّقاب؟\nج: قد يُبطئ، اكتب لنا لعله يتيسر شيءٌ، فهناك ناسٌ ينتظرون كثيرًا، فالرقيق قليل، لكن إن تيسر لك الصيام فصم ستين يومًا -شهرين.\nس: هل عليَّ فداءٌ غير هذا؟\nج: لا، إمَّا عتق أو صيام فقط.\nس: إذا كان عنده السُّكر، ولا يقدر على الصيام؟\nج: يبقى في ذمَّته حتى يتيسَّر.\nس: والدي أفطر في رمضان خمسة أيام؟\nج: يبقى في ذمَّته حتى يتيسَّر.","link":"https://binbaz.org.sa/fatwas/22482/حكم-من-عليه-صيام-كفارة-قتل-ولا-يقدر-لمرضه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وقع عليه حادث وتوفت ابنته ولا يستطيع الصيام.mp3","categories":["الجنايات والحدود"]},{"id":2784,"question":"يسرع سرعة فوق المعتادة ثم تنقلب به السيارة أو يصطدم بأحد يدخل؟","title":"حكم ما يقع للمُسْرِع بالسيارة وحكم المصدوم","answer":"الجواب: يُخشى عليه المساعدة على قتل نفسه، يُخشى عليه من الإثم، هو آثم بلا شك لتعدي الحدود، يكون قد شارك في قتل نفس، نسأل الله العافية.\nس: والمصدوم يدخل ضمن الشهداء؟\nالشيخ: نعم إن شاء الله، المصدوم من جنس صاحب الهدم أو أشد.","link":"https://binbaz.org.sa/fatwas/22932/حكم-ما-يقع-للمسرع-بالسيارة-وحكم-المصدوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أسرع سرعة فوق المعتادة فما حكمه وما حكم المصدوم.mp3","categories":["الجنايات والحدود"]},{"id":2785,"question":"الذي يقتل نفسه متعمدا ما حكمه؟","title":"ما حكم قاتل نفسه متعمدًا؟","answer":"الجواب: عاصٍ ويُغسَّل ويُصلّى عليه إذا كان ما استحلَّ ذلك.\nس: وإذا استحلَّه؟\nالشيخ: إذا استحلَّه يكفر، إذا استحل قتل المسلمين بغير حق كفر.","link":"https://binbaz.org.sa/fatwas/22933/ما-حكم-قاتل-نفسه-متعمدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم قاتل نفسه متعمدًا.mp3","categories":["الجنايات والحدود"]},{"id":2786,"question":"لو رأى شخص أحدًا يعتدي على عِرْض امرأة مسلمة ودافع عنها ثم قُتل؟","title":"حكم مَنْ قُتل وهو يدافع عن عِرْض امرأة","answer":"الجواب: شهيد ما في شك؛ لأنه مظلوم، س: ولو قتله؟ الشيخ: المقتول ظالم، المقتول في النار، الظالم يتعدى على حرم المسلمين هو ظالم، نسأل الله العافية، يعني مُتَوَعَّد بالنار وتحت مشيئة الله .\nس: لو قتله دفاعًا عن المرأة؟\nالشيخ: القاتل مجتهد مأجور، والمقتول الذي قُتل على إقدامه على الفاحشة مستحق للنار، كما جاء في الحديث؛ لظلمه، نسأل الله العافية.\nس: لو كان الصائل يندفع بغير القتل؟\nالشيخ: يدفعه بالأسهل فالأسهل، بالضرب بالكلام بالوعيد، فإذا لم يندفع إلا بالقتل ساغ له القتل فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16].","link":"https://binbaz.org.sa/fatwas/22934/حكم-من-قتل-وهو-يدافع-عن-عرض-امراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من قتل وهو يدافع عن عرض امرأة.mp3","categories":["الجنايات والحدود"]},{"id":3271,"question":"شارب الخمر إذا كان مُدْمِناً على شرب الخمر هل يُقتل؟","title":"حكم المُدمن على الخمر بعد جلده ثلاث مرات","answer":"الجواب: المعروف عند العلماء: يقام عليه الحد، كل ما ثبت عليه يقام عليه الحد، وذهب بعض أهل العلم إلى أنه يقتل في الرابعة وما بعدها، ولكن الأكثرون على أنه يقام عليه الحد دائمًا حتى يهتدي؛ لقصة الرجل الذي كان يؤتى به إلى النبي ﷺ فكان يقيم عليه الحد فقال رجل: ما أكثر ما يؤتى به أخزاه الله، فأنكر عليه النبي ﷺ.\nس: الحديث الذي ورد فيه أنه يُقتل بعد الرابعة؟\nالشيخ: صححه جماعة من حديث معاوية، من باب التعزير.","link":"https://binbaz.org.sa/fatwas/23435/حكم-المدمن-على-الخمر-بعد-جلده-ثلاث-مرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يقتل من كان مدمن على شرب الخمر.mp3","categories":["الجنايات والحدود"]},{"id":3465,"question":"دهس بنتًا صغيرة، وماتت، فهل عليه صوم أم كفارة؟","title":"ما الحكم فيمن دهس بنتًا صغيرة وماتت؟","answer":"الجواب: هذا يُعتق رقبة، فإن عجز فعليه صوم شهرين متتابعين إذا كان هو السبب في موتها.","link":"https://binbaz.org.sa/fatwas/23642/ما-الحكم-فيمن-دهس-بنتا-صغيرة-وماتت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم فيمن دهس بنتا صغيرة، وماتت.mp3","categories":["الجنايات والحدود"]},{"id":3829,"question":"كم حد الخمر، إذا شرب أول مرة؟","title":"كم حد شارب الخمر؟","answer":"الجواب: كان يجلد في عهد النبي أربعين جلدة، فلما رأى عمر الناس تمادوا في هذا الشيء جعله ثمانين، كما استقرَّ الصحابةُ على جلده ثمانين جلدة.\nوفي قصة عمر دلالة على غيرته ، وعدم محاباته، فإن ولده لما تحقق أنه شرب هذا المسكر أقام عليه الحدَّ هو وأصحابه، كانوا قد تأوَّلوا، قالوا: إنه لا يُسكر، لكن لما سأل وعرف أنه يُسكر أقام عليهم الحدّ؛ على عبيدالله بن عمر وعلى أصحابه الذين معه، وهذا من عنايته  في حماية المسلمين من الشر، وسدّ ذرائع الشر، والحرص على سلامة المجتمع من أسباب الفساد.","link":"https://binbaz.org.sa/fatwas/24031/كم-حد-شارب-الخمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحد في الخمر.mp3","categories":["الجنايات والحدود"]},{"id":3853,"question":"إذا كان الدكتور ماهرًا ومات في العملية؟","title":"هل يضمن الطبيب موت مريض في العملية؟","answer":"الجواب: ما يضرُّ، ما عليه شيء، ما يضمن إذا كان من أهل الطبِّ، معروف، ما يضمن.","link":"https://binbaz.org.sa/fatwas/24064/هل-يضمن-الطبيب-موت-مريض-في-العملية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يضمن الطبيب إذا مات المريض أثناء العملية.mp3","categories":["الجنايات والحدود"]},{"id":3858,"question":"هل يؤدب الساحر أو يقتل؟","title":"ما عقوبة الساحر المسلم وغير المسلم؟","answer":"الجواب: المعروف عن النبي ﷺ أنه تركه ولم يقتله، ولعلَّ هذا من باب التأليف والدَّعوة إلى الله ﷺ؛ ولأنه يهودي مشهور.  وأما إذا فعله المسلم يُقتل، فإنَّ السحر ردَّة عن الإسلام، لا يقع إلا باستعانة الشياطين، فالساحر يُقتل كما فعل عمر.","link":"https://binbaz.org.sa/fatwas/24069/ما-عقوبة-الساحر-المسلم-وغير-المسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يؤدب الساحر أو يقتل.mp3","categories":["الجنايات والحدود"]},{"id":3964,"question":"في القِسَامة الذين يُقْسِمون يُقْسِمون على غَلَبة الظن أن هذا هو القاتل؟","title":"هل يكون القَسَمُ في القِسَامة على غَلَبة الظن؟","answer":"الجواب: نعم على غَلَبة الظن حسب القرائن والعداوة والشحناء ونحوها، شرطها أن يكون هناك غلبة ظن، غالب الظن على أن القاتل هؤلاء.","link":"https://binbaz.org.sa/fatwas/24192/هل-يكون-القسم-في-القسامة-على-غلبة-الظن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/في القسامة هل يقسم الذين يقسمون يقسمون على غلبة الظن.mp3","categories":["الجنايات والحدود"]},{"id":3965,"question":"إذا أقسم أولياء المقتول، أقسموا على أن هذا هو القاتل، هل يُقاد؟","title":"هل يُقاد القاتل بسبب القِسَامة؟","answer":"الجواب: نعم في الحديث الصحيح: يدفع إليكم صاحبكم، وفي اللفظ الآخر: وتستحقون دم صاحبكم.","link":"https://binbaz.org.sa/fatwas/24193/هل-يقاد-القاتل-بسبب-القسامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يقاد القاتل بسبب القسامة.mp3","categories":["الجنايات والحدود"]},{"id":3967,"question":"ما يحصل القصاص بدون قسامة إلا بشهود؟","title":"حكم الشهود في القصاص","answer":"الجواب: نعم لا بدّ من شاهدين عدل اثنين، لا يقام القصاص إلا بشاهدي عدل اثنين، إلا في القسامة.","link":"https://binbaz.org.sa/fatwas/24195/حكم-الشهود-في-القصاص","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما يحصل القصاص بدون قسامة إلا بشهود.mp3","categories":["الجنايات والحدود"]},{"id":4154,"question":"إذا تاب الزاني أو الزانية من دون إقامة حدٍّ؟","title":"هل تكفي توبة الزاني دون إقامة حدٍّ؟","answer":"الجواب: يكفي، ما يُلام، التوبة تكفي.","link":"https://binbaz.org.sa/fatwas/24404/هل-تكفي-توبة-الزاني-دون-اقامة-حد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تكفي توبة الزاني من دون إقامة حدٍّ.mp3","categories":["الجنايات والحدود"]},{"id":4155,"question":"التوبة مقبولة سواء كان محصنًا أو غير محصن؟","title":"هل يقام الحد على من تاب من الزنا؟","answer":"الجواب: إذا تاب فيما بينه وبين الله كفى، أما في جهة الحدِّ: يُقام عليه الحد إذا ثبت عليه، ولو تاب وستر نفسه ولم يأتِ الحكام ولم يقل شيئًا كفى، ولا ينبغي أن يفضح نفسه، إذا عرف خطأه وزللـه فالواجب أن يتوب إلى الله فيما بينه وبينه، ولا حاجةَ إلى أن يأتي إلى أحدٍ، بل يستر نفسه، ويسأل ربَّه العفو والمسامحة ويكفي.","link":"https://binbaz.org.sa/fatwas/24405/هل-يقام-الحد-على-من-تاب-من-الزنا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يقام الحد عند التوبة من الذنب.mp3","categories":["الجنايات والحدود"]},{"id":4283,"question":"هل الساحر إذا تاب؟","title":"هل يُقتل الساحر وإنْ تاب؟","answer":"الجواب: فيما بينه وبين الله يصح توبته، ولكن يُقتل.","link":"https://binbaz.org.sa/fatwas/24554/هل-يقتل-الساحر-وان-تاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحد على الساحر إذا تاب.mp3","categories":["الجنايات والحدود","السحر والكهانة"]},{"id":4804,"question":"امرأة تسأل وتقول: كان ابني معي في استراحةٍ لنا، وكان بابُ المسبح مغلقًا، فما دريت إلا سقط في المسبح، وعمره سنة، فهل عليها شيء؟","title":"حكم امرأة سقط وليدها في مسبح ومات دون علمها","answer":"لا، ما دام بعيدًا عنها، ولم تتسبَّب فيه، ما عليها شيء، أما إذا جعلته عندها...\nس: هي عنده، والمسبح قريب، ولكن تعلم أنَّ باب المسبح مغلق، ولكن إخوان الطفل ربما ذهبوا وفتحوا المسبح؟\nج: إن شاء الله ما عليها شيء ما دام ما فرَّطت.","link":"https://binbaz.org.sa/fatwas/25196/حكم-امراة-سقط-وليدها-في-مسبح-ومات-دون-علمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الواجب على امرأة يقط وليدها في مسبح ومات دون علمها.mp3","categories":["الجنايات والحدود"]},{"id":5301,"question":"هل الصورة تقيم الحجة على الزاني؟","title":"هل يجوز إقامة حد الزنا بدلالة التصوير؟","answer":"الجواب: لا ما يجوز التصوير، التصوير محرّم، ولا يبرر التجسس على الشخص، ولكن إن صاروا أربعة شهدوا عليه فلا يحتاج صورة؛ لأن التصوير شر عظيم. السؤال: إذا هو مثلًا أتى بالصورة وشاهده الناس؟ الشيخ: محل نظر، الله جل وعلا يقول: ثُمَّ لَمْ يَأْتُوا بِأَرْبَعَةِ شُهَدَاءَ [النور:4] فهذا محل نظر، كونه صورهم فكثير من الناس قد يصور صورة.... قد يكذب المصوّر من غير أن يشاهد المُصَوَّر، يصوِّر صورته.. ثم يصوّره، ونص القرآن أربعة شهداء.[1]","link":"https://binbaz.org.sa/fatwas/30951/هل-يجوز-اقامة-حد-الزنا-بدلالة-التصوير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 021.mp3","categories":["الجنايات والحدود"]},{"id":5467,"question":"امرأة أسقطت جنينًا يبلغ من العمر شهرين منذ أكثر من اثنين وعشرين عامًا، واليوم هي لا تستطيع الصيام، ولذلك أنا أريد استبداله بإخراج مبلغ من المال فما نوع الصدقة؟ وهل يجوز إخراج ثمنها لفرد واحد أو عائلة محتاجة يصرف لها ضمان اجتماعي، أو إعطاؤها لإحدى الجمعيات الخيرية، أو إخراجها خارج البلد وذلك بسبب عجزي عن تفريقها على المحتاجين؟","title":"ما حكم مَنْ أسقطت جنينًا عمره شهران؟","answer":"الجواب: الجنين الذي دون الأربعة ما يسمى جنينًا، ولا فيه شيء، إذا سقط لأقل من أربعة، شهر، وشهرين وثلاثة، هذا ما فيه شيء، يدفن في محل طيب، والحمد لله ما فيه شيء. أما إذا أسقطت قد نفخ فيه الروح؛ فهذا فيه تفصيل: إن كانت متعمدة فهي تأثم وعليها التوبة إلى الله، وعليها الكفارة، وعليها ديته عُشر دية أمه. أما إن كان خطأ، سقط خطأ منها؛ فهذا فيه الكفارة فقط والدية، وليس فيه إثم إذا كان ما تعمّدت، بل للأسباب الأخرى. أما ما دون ذلك قبل أن تنفخ فيه الروح، ما دام علقة أو مضغة هذا ما فيه شيء، ما فيه كفارة، ولا يُصلى عليه، ولا يسمّى، ليس بولد حتى تنفخ فيه الروح، حتى يكمل أربعًا ويدخل في الخامس.[1]","link":"https://binbaz.org.sa/fatwas/31330/ما-حكم-من-اسقطت-جنينا-عمره-شهران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/reyath_alsalhin 002.mp3","categories":["الجنايات والحدود"]},{"id":5695,"question":"إن والدي دهس طفلًا عمره يقارب السنتين، وسبب الحادث أن لدى والدي السيارة، وكانت واقفة قبل أن يركب سيارته نظر تحتها من جميع الوجوه، ولم ير أحدًا، وركب السيارة، وفي هذه الأثناء قام أحد إخوة الطفل، ووضعه تحت إطار السيارة الأمامي، دون علم والدي، وعندما مشى دهس الطفل، فهل يلزمه صيام شهرين، أم لا؟","title":"حكم من قتل طفلاً بسيارته خطأ","answer":"الجواب: مثل ما جاء في الكفارة، يلزمه صيام شهرين، لو قدر على العتق يعتق بنفسه صاحب السيارة الذي دهس؛ لأنه هو الذي باشر القتل، فعليه الدية، وعليه الكفارة. والكفارة عتق رقبة مؤمنة إن تيسرت، فإن لم يتيسر فعليه صيام شهرين متتابعين، كما بين الله في كتابه العزيز في سورة النساء، وهو الداعس، وهو القاتل؛ لأن ذلك الذي وضعه ما عنده قصد أن يقتل.  أما لو كان مثل ما قال الشيخ، لو كان إنسانًا جاء بآدمي، وطرحه أمام السيارة ليدعسه صاحب السيارة على غفلة يكون هو القاتل، الذي طرحه بين يدي السيارة، لكن هذا طرحه إما لأجل الظل يبغيه في الظل، أو لأسباب أخرى، فنقول: قدر الله موته على هذه السيارة، فالداعس هو الذي عليه الدية والكفارة جميعًا.","link":"https://binbaz.org.sa/fatwas/990/حكم-من-قتل-طفلا-بسيارته-خطا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_19.mp3","categories":["الجنايات والحدود","اليوم الآخر"]},{"id":5727,"question":"أحد الإخوة يسأل: إذا كانت عليه ديون كثيرة، فما هو معنى الدين؟ وأردت أن أكفر عما عليه كله، هل يجوز أن أدفع عن كل دين صاع من الأرز على مسكين واحد، يعني عن كل دين صاع واحد على مسكين واحد؟ وهل يدفع عن السائلين إذا لم يوجد غيرهم؟ وهل يدفع على الرجل وأولاد كل واحد منهم له صاع؟","title":"أنواع الكفارات ومستحقيها","answer":"الجواب:  هذا كلام مجمل، كيف الدين؟ الدين ما يؤدى عنه الأصواع الدين يؤدى لأهله، هذا السؤال ما أوضحه صاحبه، الدين إذا كان نقودًا يعطى أهله النقود من الذهب والفضة والأوراق، إذا كان الدين طعامًا يؤدى الطعام أهله، إذا كان الدين قهوة سكر يؤدى لأهله. هذا السؤال إنما الأصواع هذه للزكوات، والكفارات، إذا كان في ذمته كفارة ظهار، وكفارة الوطء في رمضان، وعدل عن الصيام، لا يستطيع الصيام شهرين يؤدي الكفارة لكل مسكين نصف صاع، ما هو صاع، نصف صاع يكفي، كل واحد له نصف الصاع من قوت البلد عن الكفارة التي في ذمته من ظهار عن زوجته، وتحريم لها، أو وطء في رمضان فإنه يعتق رقبة، وإن عجز صام شهرين متتابعين، فإن عجز أطعم ستين مسكينًا، ثلاثين صاعًا من قوت البلد، كل صاع بين اثنين، هذا محل الأصواع.  وهكذا لو أخر صيام رمضان من غير علة، ولم يقضه حتى جاء رمضان، آخر يقضي ما ضيع من صيام رمضان، ويطعم عن كل يوم مسكينًا زيادة مع القضاء نصف صاع عن كل يوم يجمعها، ويعطيها مسكينًا واحدًا.  والسائلون يعطون من الزكاة؛ لأنهم فقراء، السائلون إذا كانوا ... ويزعمون أنهم فقراء يعطون من الزكاة والكفارات؛ لأنهم أهلها داخلون في قوله: إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاء وَالْمَسَاكِينِ [التوبة:60] إلا إذا علمت أن هذا السائل كذاب، وأنه غني تنكر عليه، وتقول له: اتق الله، ليس لك السؤال وأنت غني، يقول النبي ﷺ في الحديث الصحيح: من سأل الناس أموالهم تكثرًا، فإنما يسأل جمرًا، فليستقل، أو ليستكثر إنما يسأل نارًا -نعوذ بالله- رواه مسلم في الصحيح.  ويقول -عليه الصلاة والسلام-: لا يزال الرجل يسأل الناس حتى يأتي يوم القيامة، وليس في وجهه مزعة لحم متفق عليه، فإذا كان يسأل وأنت تعلم أنه كذاب، وأنه غني فلا تعطه من الزكاة، ولا تصدق عليه، بل أنكر عليه، وقل له: هذا حرام عليك، لا يجوز لك، وقوله تعالى: وَفِي أَمْوَالِهِمْ حَقٌّ لِّلسَّائِلِ وَالْمَحْرُومِ [الذاريات: 19] يعني السائل المجهود، أو المعروف الذي يعرف أنه فقير.  والسائلون ثلاثة أقسام: قسم يعرف أنه فقير فيعطى، وقسم لا يعرف فيعطى، والقسم الثالث معروف بأنه غني لا يعطى؛ لأنه ظالم لنفسه، فلا يستحق الزكاة، ولا يجوز له السؤال. أما السائل الفقير، والسائل المجهول الذي لا تعرف حاله، فإنك تعطيه من الزكاة، ومن غيرها؛ لأن الظاهر أنه فقير، والله قال: وَفِي أَمْوَالِهِمْ حَقٌّ لِّلسَّائِلِ وَالْمَحْرُومِ [الذاريات: 19] .  قال بعض أهل العلم: أن الحق المعلوم هو الزكاة، وقال آخرون: إنه أمر غير الزكاة زائد، تفضلًا منهم، وإحسانًا منهم إلى الفقراء والمحاويج والسائلين، والمحروم هو الفقير الذي حرم المال.","link":"https://binbaz.org.sa/fatwas/1037/انواع-الكفارات-ومستحقيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_59.mp3","categories":["الجماع في نهار رمضان","الأيمان والنذور","الجنايات والحدود"]},{"id":5791,"question":"أحد الإخوة يقول: قرأت في مجلة المجتمع، نداء من نساء مسلمات مسجونات في إحدى الدول الإسلامية طلبنا من المسلمين تفجير السجون، والمعتقلات التي فيها حيث انتهكت أعراضهن، وحيث الآن هم حبالى من زنا حيث أجبرن على ذلك داخل السجون، فما هو حكم قتل النفس في تلك الحال، وتلك النسوة اللاتي ابتلين بذلك؟","title":"حكم قتل المسلم نفسه خوفاً من التعذيب","answer":"الجواب: قتل النفس بين الله  النهي عنه، وهكذا رسوله -عليه الصلاة والسلام- والله يقول: وَلَا تَقْتُلُوا أَنْفُسَكُمْ إِنَّ اللَّهَ كَانَ بِكُمْ رَحِيمًا [النساء:29]. والنبي ﷺ حذر من قتل النفس، وأخبر عن رجل اشتد به الجرح، فقتل نفسه، فقال: قال الله -جل وعلا-: بادرني عبدي بنفسه حرمت عليه الجنة. فقتل النفس لا يجوز، ولا يحل للإنسان إذا ابتلي أن يقتل نفسه، كما إذا ابتلي بالفاحشة، أو بشيء آخر لا يحل له قتل نفسه، أو بالسجن، ولكن عليها أن تدافع ما استطاعت. وهكذا الرجل قد يبتلى باللواط، أو غيره، فيدافع عن نفسه ما استطاع، ولو أفضى إلى أن يقتل، لكن لا يقتل نفسه هو يدافع، ولا يمكن من نفسه، لا من اللواط، ولا من الفاحشة، فإن قتله صاحب الجريمة؛ فهو شهيد، النبي ﷺ قال: من قتل دون ماله فهو شهيد، من قتل دون دينه فهو شهيد، من قتل دون دمه فهو شهيد وجاءه رجل قال: يا رسول الله، الرجل يأتيني يريد مالي؟ -مال ما هو بنفس- قال: لا تعطه مالك قال: فإن قاتلني قال: قاتله قال: فإن قتلته قال: فهو في النار قال: فإن قتلني، قال: فأنت في الجنة. فدل ذلك على أن المظلوم يقاتل، ويدافع، فإن نجح فالمجرم في النار -نعوذ بالله- وإن لم ينجح المدافع، بل قتل لحكمة من الله بالغة، ولحكمة عظيمة، ولأسرار لا نعلمها فهو شهيد، فقد قتل عمر؛ وهو أفضل الناس بعد الصديق، وبعد الأنبياء، قتل في المحراب وهو يصلي بالناس لحكمة بالغة، سلط عليه رجل كافر يقال له: أبو لؤلؤة من المجوس، لأسباب حُكْمٍ حَكَمَ به عليه عمر، رضي الله عنه وأرضاه.  فالقتل قد يقع للأخيار، وقد يقع لغير الأخيار، قد يقتل الإنسان، ويبتلى كما قتل بعض الرسل، بعض الأنبياء قتل، وهو أشرف الناس، كما أخبر الله في كتابه العظيم عن اليهود أنهم يقتلون الأنبياء بغير حق، وهكذا بعض الأخيار، كعمر، وعثمان، وعلي الثلاثة قتلوا بغير حق، الزبير، وطلحة بن عبيدالله.  المقصود: أن قتل المظلوم أمر معلوم، وصاحبه شهيد، والمجرم إذا قتل فإلى النار، فمن ابتلي في نفسه؛ فعليه الدفاع، وعليه الصبر، والمدافعة بقوة، وإذا أمكن أن يقتل المجرم فليقتل المجرم، إذا لم يندفع إلا بالقتل قتله، وإن اندفع بالكلام كالتحذير من مغبة أهل الجريمة؛ فالحمد لله، وإن لم يندفع إلا بالقتل كخنقة، أو طعنة بالسكين، أو بغير هذا فعل ذلك، وهو برئ منه، وهو إلى النار -نعوذ بالله- أما من غلبه المجرم، وقتله المجرم؛ فهو شهيد، وإلى الجنة.","link":"https://binbaz.org.sa/fatwas/1112/حكم-قتل-المسلم-نفسه-خوفا-من-التعذيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_118.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":5817,"question":"أطفال الكفار، يموتون مسلمين، أو كفارًا؟","title":"حكم أطفال المشركين","answer":"الجواب: أطفال الكفار مثل ما قال الرسول ﷺ: الله أعلم بما كانوا عاملين حكمهم حكم أهلهم، لا يغسل، ولا يصلى عليه مع أهله، إذا مات بين أهله يدفن مثل أهله، لا يغسل، ولا يصلى عليه؛ لأنه كافر، ولكن يوم القيامة الله أعلم بما كانوا عاملين.  والصحيح: أنهم يمتحنون يوم القيامة، الله يمتحنهم يوم القيامة، ويأمرهم، فإذا أطاعوا؛ دخلوا الجنة، وإن عصوا؛ دخلوا النار مع أهليهم، وكذلك أهل الفترة الذين ماتوا في الفترة، ما جاءتهم رسل في الدنيا، ما جاءهم رسول يوم القيامة، يمتحنون، ويؤمرون، وينهون، فإن أجابوا؛ دخلوا الجنة، وإن عصوا؛ دخلوا النار، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/1138/حكم-اطفال-المشركين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_144.mp3","categories":["الجنايات والحدود","اليوم الآخر"]},{"id":6113,"question":"أخيرًا نفذ حكم الإعدام في ثلاثة أشخاص في الكويت بطريقة الشنق، هل هذا موافق للشرع؟","title":"حكم الإعدام بالشنق","answer":"الجواب: الذي يظهر أن الذي ينبغي في الإعدام ما هو الأسهل، النبي ﷺ قال: إذا قتلتم؛ فأحسنوا القتلة والذي بلغنا أن الشنق غير طيب، وأن فيه تعذيب، فلا ينبغي الشنق، هذا تأسي بأعداء الله، بل ينبغي أن يقتلوا بالسيف؛ لأن قتلة السيف بيد الرجل العارف، والسيف الجيد يريح أكثر، وينهي الموضوع بسرعة، فلا ينبغي أن يقتل بالشنق.","link":"https://binbaz.org.sa/fatwas/1528/حكم-الاعدام-بالشنق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_458.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":6142,"question":"إنني سائق سيارة أجرة هي مصدر رزقي، وقد قضى الله بحكمه، وقدره، وقلبت بها، وتوفي معي أربعة أشخاص منهم: اثنان سامحوني في الدية، واثنان آمنت الدية لدى الدولة حيث إنهما لم يعرفا، هل علي صوم، أو صدقة؟","title":"حكم الكفارة على سائق انقلبت سيارته ومات من معه","answer":"الجواب:  إذا كنت السبب في موتهم؛ فعليك عتق رقبة، في كل واحد مؤمنة، فإن لم تجد؛ صمت عن كل واحد شهرين، عن الأربعة ثمانية أشهر، لكل واحد شهرين متتابعين، إذا كنت السبب مثل إذا كنت أسرعت حتى انقلبت، أسرعت في الطريق حتى صدمت، وانقلبت، أو ما أشبه ذلك، إذا كنت أنت السبب في هذا الانقلاب، أو كنت سكرانًا، أو ناعسًا، أو نائمًا، أو تأكل الحبوب الذي تغير شعور الإنسان، فانقلبت بسبب ذلك؛ فعليك الدية، والكفارة جميعًا. أما إذا كان ما لك تسبب، أمر غلبك من غير تسبب، وأنت تمشي في السير المعتاد، ولم تخالف الطريق، ولم تخالف النظم، بل تمشي وشعورك معك، ولكن قدر أن اختلت بهم السيارة من ذراع، أو غيره، أو بنشر، فحصل انقلاب بسبب ذلك من دون أسباب منك؛ فلا شيء عليك.","link":"https://binbaz.org.sa/fatwas/1610/حكم-الكفارة-على-ساىق-انقلبت-سيارته-ومات-من-معه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_504.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":6226,"question":"حكم اللوطي يا شيخ؟","title":"حد اللواط","answer":"الجواب: اللوطي نسيته نعم، أما اللوطي فقد ذكر الشيخ إبراهيم، وأفتى العلماء:  اللوطي كما سمعتم، والعياذ بالله، اللوطي الذي يأتي الرجل، إتيان الرجل هذه اللواطة، والله أنكر ذلك، وبين أمر اللوطية في قصة قوم لوط، والله أهلكهم جميعًا، وخسف ببلادهم، وجعل عاليها سافلها -نعوذ بالله- ثم أمطرهم بحجارة من سجيل، نسأل الله العافية. قال الوليد بن عبدالملك أمير المؤمنين: لولا أن الله ذكر قصة اللوطية في القرآن ما كنت أظن أن رجلًا يركب رجلًا! فهي فاحشة شنيعة، أفحش من الزنا -نعوذ بالله- وأقبح، فلهذا جاء أن حكمه القتل الذي عليه أصحاب الرسول ﷺ وقد أجمعوا جميعًا  على قتل اللوطي مطلقًا، سواء كان بكرًا، أو ثيبًا، بعض الفقهاء قالوا: إنه كالزاني يرجم المحصن، ويجلد البكر مائة جلدة، ويغرب عامًا، ولكنه قول ضعيف.  والصواب: أن اللوطي يقتل، هذا هو أحد الأقوال، وهو الصواب، يقتل قتلًا بالسيف، أو بالرجم بالحجارة كالزاني المحصن، وقد أجمع الصحابة -رضي الله عنهم وأرضاهم- على قتله، لكن بعضهم قال: يرجم كما يرجم الزاني المحصن وبعضهم قال: بل يلقى من شاهق، وبعضهم يقال: يحرق بالنار.  والصواب في هذا أنه يقتل قتلًا بالسيف، كما جاء في الحديث عن النبي ﷺ أنه قال: من وجدتموه يعمل عمل قوم لوط؛ فاقتلوا الفاعل والمفعول به نسأل الله العافية، وهذا الحديث لا بأس بإسناده، جيد، وإن كان فيه بعض الاختلاف، لكن يعضده، ويؤيده إجماع الصحابة، وقد أجمع أصحاب الرسول ﷺ على قتله، وأن اللوطي يقتل مطلقًا، سواء كان بكرًا، أو ثيبًا، وإنما اختلفوا في صفة القتل، فهل يقتل بالتحريق بالنار، أو بالرجم، أو بالسيف؟ والصواب: أنه يقتل بالسيف؛ لأن النار لا يعذب بها إلا الله -جل وعلا- والرجم إنما جاء في الزاني المحصن؛ فلا يقاس عليه اللوطي، فاللوطي له شأن آخر، ولكن يقتل بالسيف الفاعل والمفعول به إذا كانا مكلفين لخبث معصيتهما، ولشناعتها العظيمة؛ ولأن الواجب التنفير منها، والتحذير منها، وكان القتل مناسبًا في هذا المقام؛ للتحذير من هذه الفاحشة الشنيعة القبيحة. نسأل الله للجميع العافية، والسلامة.","link":"https://binbaz.org.sa/fatwas/1727/حد-اللواط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_574.mp3","categories":["الجنايات والحدود","الأخلاق المذمومة"]},{"id":6227,"question":"حكم من يأتي البهيمة؟","title":"حكم إتيان البهيمة","answer":"الجواب: البهيمة جاء فيها حديث في سنده اختلاف أنه يقتل، وجاء عن ابن عباس أنه يعزر تعزيرًا؛ لأن السند وحده لا  يكفي؛ لأن فيه اختلاف عن ابن عباس في قتل البهيمة، وهو الذي عليه أهل العلم، المحققون من أهل العلم أنه يعزر إذا أتى البهيمة، كان حمارًا، أو بقرة، أو عنزًا، أو غير ذلك؛ يعزر، وبعض أهل العلم قال: يقتل للحديث.  ولكن ذهب جملة من أهل العلم إلى أنه يعزر، لأن الحديث ليس في قوته، وسنده ما يشجع على قتل الشخص؛ لأن فيه بعض الاختلاف، والأصل عصمة المؤمن، فوجب أن يعزر بما يراه ولي الأمر من جلدات، أو جلد، وسجن، أو غير ذلك مما يراه ولي الأمر رادعًا عن هذه الفاحشة، نسأل الله السلامة والعافية.","link":"https://binbaz.org.sa/fatwas/1728/حكم-اتيان-البهيمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_575.mp3","categories":["الجنايات والحدود","الأخلاق المذمومة"]},{"id":6241,"question":"قرأت في صحيفة عربية مقالًا من ضمنه: إذا كانت الحكمة من الزنا عدم تضييع الأنساب، وعدم إفشاء العداوة، والبغضاء، وما إلى ذلك، فإذا كان هناك حبوبًا لمنع الحمل، ورضا من الطرفين، ولم يكن هناك أية مشكلة، فما المانع من الزنا؟! هذه مقالة قرأتها فما الرد عليها أثابكم الله؟","title":"هل يجوز الزنا إذا انتفت الحكمة من تحريمه؟","answer":"الجواب: الأصل فيما حرم الله أنه يجب اجتنابه، وما أوجب الله يجب التزامه، أما كونه يعلم الحكمة هذا نور على نور، وخير إلى خير، فما حرم الله؛ وجب تركه مطلقًا، ولو لم يعلم الحكمة، ولو علم أن الحكمة التي يعلمها منتفية في ذلك فإنه يجب أن يلتزم بما حرم الله عليه، كما يلتزم بما أوجب الله عليه، فالله حرم الزنا وقال: وَلَا تَقْرَبُوا الزِّنَا إِنَّهُ كَانَ فَاحِشَةً وَسَاءَ سَبِيلًا [الإسراء:32] ولم يقل: إلا إذا كان ما تحمل، أو إذا كان كذا، أو كان كذا، بل حرمه، وقال: إِنَّهُ كَانَ فَاحِشَةً وَسَاءَ سَبِيلًا [الإسراء:32].  فالزنا حرمه الله، ورتب عليه العذاب الأليم، ومضاعفة العذاب، والخلود في النار لما يترتب عليه من الشر الكثير، ووجود بعض النوادي التي يظن صاحبها أنه لا يترتب عليها ما هو معروف من عواقب الزنا، لا قيمة لها. فالاعتبار بتحريم ما حرم الله، سواء جاءت الأشياء المترتبة عليها، أو لم تحصل، فيجب الالتزام بما حرم الله، والبعد عما حرم الله، والحذر من ذلك، ولو فرضنا أن تلك الحكم التي نص عليها أهل العلم لا تأتي، ولا تقع لو فعل ما حرم الله عليه، نسأل الله العافية. فالواجب: الالتزام بترك ما حرم الله، وفعل ما أوجب الله مطلقًا، ولو ظن أنها لا تحمل، ولو ظن أنها تعاطت الحبوب، ولو ظن أنه ليس هناك أحد يكون بينه، وبينه شحناء، كل هذه ظنون لا وجه لها، والحكم لا يتعلق بها، الحكم يتعلق بالإيلاج بالتحريم، ووسائله، فيجب الحذر من الزنا، ووسائله مطلقًا، هذا هو الواجب بإجماع المسلمين، وبنص القرآن، ونص السنة.","link":"https://binbaz.org.sa/fatwas/1735/هل-يجوز-الزنا-اذا-انتفت-الحكمة-من-تحريمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_578.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":6243,"question":"هل يلزم جلد الزاني المتزوج مع الرجم؟ وما هو موقفكم من الأسباب التي تؤدي إلى الزنا مثل آلات اللهو، والغناء، والموسيقى التي تأتي في الإذاعات المسلمة؟","title":"الموقف من الأسباب المؤدية إلى الزنا وحد الزاني","answer":"الجواب: ليس في هذا عذر له، وعليه أن يتجنبها، ويحذرها من الإذاعة، ومن التلفاز، وليس وجود الغناء في التلفاز، أو آلات الملاهي، أو تكشف بعض النساء، ليس عذرًا في الزنا، وإنما هي من أسباب الزنا، وليس عذرًا، بل يجب أن يحذر هذا، ولا يستعمل هذا الشيء، ولا ينظر إليه، بل يجاهد نفسه، وإذا زنا، وثبت عليه الزنا بإقرار، أو بالبينة ؛رجم إذا كان محصنًا. ولو قال: إن هذا من أسباب رؤيتي للتلفاز، أو من أسباب سماعي للإذاعة! من قال لك تسمع؟! ومن قال لك تنظر؟! أنت الذي جنيت على نفسك. المقصود: أن هذا ليس بعذر متى أقر بالفاحشة، بالزنا، أو ثبت بالبينة الشرعية، أربعة شهود؛ وجب أن يقام عليه حدها، إن كان بكرًا؛ جلد مائة جلدة، وغرب عامًا، وإن كان ثيبًا يرجم بالحجارة حتى يموت، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/1745/الموقف-من-الاسباب-المودية-الى-الزنا-وحد-الزاني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_584.mp3","categories":["الجنايات والحدود","الأخلاق المذمومة"]},{"id":6277,"question":"لي أخ صار عليه حادث، وهو يقود سيارته، وكان الخطأ منه حيث كان نعسانًا (نائم) وقد ذهب ضحية هذا الحادث أربعة أنفس، فهل عليه كفارة غير كفارة الدية، وما هي؟","title":"كفارة من قتل بسيارته وهو نعسان","answer":"الجواب: الذي أصاب الناس بسيارته ناعسٌ ولا صاحٍ عليه الدية، والكفارة، الذي صدم الناس حتى قتلهم، سواء بسرعته، أو بنعاسه، أو بقلة بصيرته، أو غير ذلك؛ فهو على كل حال ظالم، ويستحق أن يسوق الدية، وعليه كفارة عن كل نفس كفارة عتق رقبة، فإن عجز؛ صام شهرين متتابعين عن كل نفس، نسأل الله الهداية.","link":"https://binbaz.org.sa/fatwas/1797/كفارة-من-قتل-بسيارته-وهو-نعسان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_636.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":6338,"question":"النفاق يقام على صاحبه الحد، أم لا؟","title":"حكم إقامة الحد على المنافق","answer":"الجواب: إذا ثبت أنه زنديق؛ يستتاب، فإن تاب وإلا قتل، وبعض أهل العلم يرى أنه يقتل مطلقًا، ولا يستتاب إذا ظهر أنه في الباطن مكذب جاحد للحق، ويتظاهر بالإسلام، فكثير من أهل العلم يرى أنه يقتل حدًا، كافرًا، وبعض أهل العلم يستتيبه، فإن تاب، واستقام على دين الله، ولم يظهر منه بعد ذلك ما يدل على النفاق؛ فلا بأس، وإلا قتل. لكن أعمال المنافقين الظاهرة هذه تسمى نفاقًا عمليًا، فإن النفاق نفاقان: اعتقادي، وهو المكذب لله، ورسوله في الباطن، فهذا كفره أكبر -نعوذ بالله- وهذا الذي قال الله فيه : إِنَّ الْمُنَافِقِينَ فِي الدَّرْكِ الأَسْفَلِ مِنَ النَّارِ [النساء:145] يعني هم في الدرك الأسفل من الكفار، تحت الكفار، نعوذ بالله.  أما النفاق الثاني: النفاق العملي، كونه يتكاسل في الصلاة، أو يكذب في بعض الأحيان، أو يخون الأمانة، هذا نفاق عملي -نعوذ بالله- وهو قد يكون وسيلة إلى النفاق الأكبر، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/1942/حكم-اقامة-الحد-على-المنافق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_729.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":6352,"question":"هل الخلائق يرون الله في القيامة؟","title":"حكم رؤية الخلائق لله تعالى يوم القيامة","answer":"الجواب: يراه المؤمنون فقط، لا يراه إلا المؤمنون. السؤال: يقول: يكلمهم، وليس بينه وبينهم ترجمان؟ الجواب: كَلَّا إِنَّهُمْ عَن رَّبِّهِمْ يَوْمَئِذٍ لَّمَحْجُوبُونَ [المطففين:15] يكلمهم، ولكن لا يرونه كَلَّا إِنَّهُمْ عَن رَّبِّهِمْ يَوْمَئِذٍ لَّمَحْجُوبُونَ  ۝  ثُمَّ إِنَّهُمْ لَصَالُوا الْجَحِيمِ [المطففين:15-16] نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/1945/حكم-روية-الخلاىق-لله-تعالى-يوم-القيامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_732.mp3","categories":["الجنايات والحدود","اليوم الآخر"]},{"id":6367,"question":"النفاق يقام على صاحبه الحد، أم لا؟","title":"حكم إقامة الحد على المنافق","answer":"الجواب: إذا ثبت أنه زنديق؛ يستتاب، فإن تاب وإلا قتل، وبعض أهل العلم يرى أنه يقتل مطلقًا، ولا يستتاب إذا ظهر أنه في الباطن مكذب جاحد للحق، ويتظاهر بالإسلام، فكثير من أهل العلم يرى أنه يقتل حدًا، كافرًا، وبعض أهل العلم يستتيبه، فإن تاب، واستقام على دين الله، ولم يظهر منه بعد ذلك ما يدل على النفاق؛ فلا بأس، وإلا قتل. لكن أعمال المنافقين الظاهرة هذه تسمى نفاقًا عمليًا، فإن النفاق نفاقان: اعتقادي، وهو المكذب لله، ورسوله في الباطن، فهذا كفره أكبر -نعوذ بالله- وهذا الذي قال الله فيه : إِنَّ الْمُنَافِقِينَ فِي الدَّرْكِ الأَسْفَلِ مِنَ النَّارِ [النساء:145] يعني هم في الدرك الأسفل من الكفار، تحت الكفار، نعوذ بالله.  أما النفاق الثاني: النفاق العملي، كونه يتكاسل في الصلاة، أو يكذب في بعض الأحيان، أو يخون الأمانة، هذا نفاق عملي -نعوذ بالله- وهو قد يكون وسيلة إلى النفاق الأكبر، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/1942/حكم-اقامة-الحد-على-المنافق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_729.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":6401,"question":"وسؤال آخر مضمونه أن رجلًا زنا بامرأة، وحملت منه، ما الحكم في المولود إذا كان ولدًا، أو بنتًا، ثم عقد عليها بعد ذلك؟ وهل المولود ينادى بأبيه، وهل يرثه، أفيدونا جزاكم الله؟","title":"حكم انتساب ولد الزنا إلى الزاني بعد زواجه بالزانية","answer":"الجواب: نسأل الله العافية، إذا زنا بها فالولد ليس له، ولكن لها، ينسب إليها، ويقال: ابن فلانة، ولد فلانة، وينسب إلى عبدالله، أو عبدالرحمن ولا ينسب إلى الزاني؛ لأنه ليس بزوج، إنما هو تيس مستعار، خبيث، فعل المنكر؛ فلا ينسب إليه، بل ينسب إلى المرأة، أو تنسبه إلى عبدالله؛ لأن الناس كلهم عبيد الله، ولا يسمى إلى هذا الزاني أبداً، ونكاحه باطل إذا تزوجها وهي حامل، يكون نكاحه باطل. السؤال: الحمل منه هو؟ الجواب: لا ينسب إليه؛ لأن الحمل باطل، ليس منسوبًا إليه، ولكنه منسوب إلى المرأة، ماء فاسد لا ينسب إليه، بل ينسب إلى المرأة، فإذا وضعت الحمل، وتزوجها بعد ذلك بعد توبة منهما ينبغي أن يتوبا إلى الله  فلا بأس. السؤال: .......؟ الجواب: لا بدّ من الولي إذا كان ما لها ولي، فالسلطان يعني ولي الأمر في بلدها، أمير بلدها، أو قاضي بلدها إذا وجد، إذا كان ما لها ولي؛ يكون قاض البلد، أو أمير البلد يزوجها. السؤال: ........؟ الجواب: إذا كان ما لها ولي، لا أب، ولا أخ، ولا عم، ولا ابن عم.","link":"https://binbaz.org.sa/fatwas/1977/حكم-انتساب-ولد-الزنا-الى-الزاني-بعد-زواجه-بالزانية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_764.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":6500,"question":"بعض زملائي في العمل يجاهرن بجريمة الزنا أثناء السفر إلى الخارج، فما هو الذي يجب علينا إزاء ذلك إذا لم تفد معهم النصيحة؟","title":"حكم المجاهرة بالزنا","answer":"الجواب:  إذا سمعت هذا؛ تنكر عليه، تقول له: اتق الله، لا تفضح نفسك ولا تجاهر بمعصيتك، هذا حرام عليك، والرسول -عليه الصلاة والسلام- يقول: كل أمتي معافى إلا المجاهرين نعوذ بالله، فالإنسان إذا فعل المعصية لا يجوز له أن يجاهر بها، ويقول: فعلت، وفعلت، بل يطلب من ربه الستر، فيسأل ربه العافية، ويبادر بالتوبة، فإذا سمعت من زميلك في المكتب، أو في غيره، هذا الأمر تنكره عليه، وتقول: اتق الله، لا تقل هذا الكلام، ولا تنطق بهذا الكلام، وسل ربك التوبة، تب إلى الله، هذه فضيحة، هذا منكر، تتكلم عليه، وتبين له أن هذا منكر، وأن هذا ما يجوز، ولا يحل له أن يبوح به عند زملائه، ولا عند غيرهم، بل عليه أن يستتر بستر الله، وأن يتوب إلى الله  ولا تسأم من الإنكار عليه، لا تسأم إذا قال لك مرتين، قل له مرتين ثلاث أربع، تشدد عليه، وقل له والذين معك تنكرون عليه، تعاونوا عليه، أعينوه على حرب الشيطان، هذا يزين له الشيطان، وأنتم أعينوه على حرب الشيطان بالإنكار عليه، والتغليظ عليه؛ لعله ينتهي، وإذا لم ينته؛ فاستعينوا بالله على فصله، جاهدوا في إبعاده عنكم مع المسؤولين. السؤال: إقراره منه على نفسه ألا يقام عليه الحد..؟ الجواب: نعم. السؤال: إقراره منه على نفسه بأنه فعل جريمة الزنا؟ الجواب: بلى، إذا شهدوا عند الحاكم؛ يقام عليه، يخوفونه بهذا، يقولون: إما أن تتوب، وإلا سنشهد عند الحاكم؛ حتى يقام عليك الحد، تقدم، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/2271/حكم-المجاهرة-بالزنا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_894.mp3","categories":["الجنايات والحدود","الأخلاق المذمومة"]},{"id":6513,"question":"هل إقامة الحدود تكفر الذنوب مثل: القتل والرجم، والجلد وهكذا؟","title":"الحدود كفارة للذنوب","answer":"الجواب: نعم ثبت عنه ﷺ أنه لما ذكر المعاصي قال: ومن أدركه الله بالدنيا كان كفارة له إذا كان جلد، ولم يعد إلى الزنا؛ صار كفارة له، وإذا زنا، ورجم؛ لأنه محصن، قد تزوج فرجم؛ صار توبة له، والله يمحو به السيئة عنه، فلا يؤخذ بها يوم القيامة، ولا يجمع الله عليه عذابين، عذاب في الدنيا، وعذاب في الآخرة، لكن الزاني الذي جلد، وقام عليه الحد، ثم عاد إلى الزنا يؤخذ بالثاني، لا بالأول، وهكذا كلما عاد عليه ذنب الإعادة، أما الذنب الأول الذي تاب منه، أو أقيم عليه الحد منه هذا لا يؤخذ به. لكن إذا عاد بعد التوبة إلى زنا ثانٍ، أخذ بالثاني، وإذا تاب من الثاني، ثم عاد إلى الثالث؛ أخذ بالثالث، وهكذا الرابع، وهكذا الخامس، كل ذنب يتوب منه؛ لا يؤخذ به، لكن إذا عاد إلى شيء آخر من جديد؛ أخذ بالجديد حتى يتوب، ولا يسمى ناقضًا للأول للتوبة لا، إذا كانت التوبة صادقة، مشتملة على الشروط، ثم وقع في المعصية بعد ذلك، وهو قد تاب توبة صادقة، وفي نيته العزم ألا يعود، ولكن بُلي بالشيطان، وعاد -والعياذ بالله- فهذا يؤخذ بالذنب الأخير؛ حتى يتوب إلى الله منه، وهكذا كلما عاد بعد توبة صادقة؛ أخذ بالأخير، لا بما مضى، نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/2247/الحدود-كفارة-للذنوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_868.mp3","categories":["الجنايات والحدود","اليوم الآخر"]},{"id":6514,"question":"هل تسقط التوبة الحد، أم لا؟","title":"هل تسقط الحدود بالتوبة","answer":"الجواب: التوبة فيها تفصيل، أما من جهة الله، فالله يمحو بها الذنب  التوبة من جهة الله -بفضله وإحسانه- يمحو بها الذنب، كما قال -جل وعلا - لما ذكر الشرك، والقتل، والزنا، قال: إِلَّا مَنْ تَابَ وَآمَنَ وَعَمِلَ عَمَلًا صَالِحًا فَأُولَئِكَ يُبَدِّلُ اللَّهُ سَيِّئَاتِهِمْ حَسَنَاتٍ [الفرقان:70] والنبي ﷺ قال: التائب من الذنب كمن لا ذنب له فمن تاب؛ تاب الله عليه، إذا استوفى شروط التوبة، إذا أقلع من الذنوب، وندم على ما مضى منها، وعزم ألا يعود فيها، ورد الحقوق، والمظالم إلى أهلها، أو استحلهم، فالتوبة تجب ما قبلها، ويعفو الله بها عما مضى. لكن من جهة إقامة الحد فهذا فيه تفصيل: أما من أمسك على الذنب، ووضع عليه قلبه على الذنب؛ فتوبته لا تنفع في درء الحد، بل يجب أن يقام عليه الحد ولا تنفعه توبته التي اضطر إليها بسب أخذه، فمتى أخذ؛ فإنه يقام عليه الحد، ولو تاب؛ فتوبته بعد القبض -بعدما قبض عليه- لأنه فيما يظهر من حاله إنما تاب تعوذًا، ولئلا يجلد، ولئلا يسجن، ولئلا يقام عليه حد الله، فلا تنفعه هذه التوبة من جهة الحكم الشرعي، بل يقام عليه الحد، ولهذا الأسارى إذا أسلموا بعد أسرهم لا ينفعهم إسلامهم من جهة إطلاق أسرهم، ومن جهة إعفائهم مما يجب عليهم من جهة الأسر في أيدي المسلمين، وإنما تحقن دماؤهم لإسلامهم، ولكن تبقى الحقوق الأخرى. وهكذا من ألقي عليه القبض على الزنا، أو على شرب المسكر؛ يقام عليه الحد، وهكذا من تاب بعد قتل النفس بغير حق؛ يقام عليه القصاص، ولا تمنع التوبة القصاص عليه، لكن من تاب قبل أن يقدر عليه، فعل الذنب، ثم تاب الله عليه قبل أن نقدر عليه، قبل أن نعلم حاله، وجاءنا تائبًا نادمًا؛ فهذا هو الذي تنفعه التوبة، ولا يقام عليه الحد بعدما جاء تائبًا نادمًا قبل أن يعلم حاله، وقبل أن يقبض عليه، كما قال الله في قطاع الطريق: إِلَّا الَّذِينَ تَابُوا مِنْ قَبْلِ أَنْ تَقْدِرُوا عَلَيْهِمْ [المائدة:34] هذا يدل على أن التوبة قبل القدرة لها شأن غير التوبة بعد القدرة.","link":"https://binbaz.org.sa/fatwas/2263/هل-تسقط-الحدود-بالتوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_886.mp3","categories":["الرقائق","الجنايات والحدود"]},{"id":6516,"question":"بعض زملائي في العمل يجاهرن بجريمة الزنا أثناء السفر إلى الخارج، فما هو الذي يجب علينا إزاء ذلك إذا لم تفد معهم النصيحة؟","title":"حكم المجاهرة بالزنا","answer":"الجواب:  إذا سمعت هذا؛ تنكر عليه، تقول له: اتق الله، لا تفضح نفسك ولا تجاهر بمعصيتك، هذا حرام عليك، والرسول -عليه الصلاة والسلام- يقول: كل أمتي معافى إلا المجاهرين نعوذ بالله، فالإنسان إذا فعل المعصية لا يجوز له أن يجاهر بها، ويقول: فعلت، وفعلت، بل يطلب من ربه الستر، فيسأل ربه العافية، ويبادر بالتوبة، فإذا سمعت من زميلك في المكتب، أو في غيره، هذا الأمر تنكره عليه، وتقول: اتق الله، لا تقل هذا الكلام، ولا تنطق بهذا الكلام، وسل ربك التوبة، تب إلى الله، هذه فضيحة، هذا منكر، تتكلم عليه، وتبين له أن هذا منكر، وأن هذا ما يجوز، ولا يحل له أن يبوح به عند زملائه، ولا عند غيرهم، بل عليه أن يستتر بستر الله، وأن يتوب إلى الله  ولا تسأم من الإنكار عليه، لا تسأم إذا قال لك مرتين، قل له مرتين ثلاث أربع، تشدد عليه، وقل له والذين معك تنكرون عليه، تعاونوا عليه، أعينوه على حرب الشيطان، هذا يزين له الشيطان، وأنتم أعينوه على حرب الشيطان بالإنكار عليه، والتغليظ عليه؛ لعله ينتهي، وإذا لم ينته؛ فاستعينوا بالله على فصله، جاهدوا في إبعاده عنكم مع المسؤولين. السؤال: إقراره منه على نفسه ألا يقام عليه الحد..؟ الجواب: نعم. السؤال: إقراره منه على نفسه بأنه فعل جريمة الزنا؟ الجواب: بلى، إذا شهدوا عند الحاكم؛ يقام عليه، يخوفونه بهذا، يقولون: إما أن تتوب، وإلا سنشهد عند الحاكم؛ حتى يقام عليك الحد، تقدم، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/2271/حكم-المجاهرة-بالزنا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_894.mp3","categories":["الجنايات والحدود","الأخلاق المذمومة"]},{"id":6541,"question":"وآخر يسأل إذا سافرت في خط، ووجدت فيه العدو قاطعين الخط، وينهبون أموال الناس، هل أعطيهم مالي، أم أقاتلهم، وإذا قَتَلت، أو قُتِلت ما حكم الإسلام؟","title":"حكم مقاتلة قطاع الطرق","answer":"الجواب: ثبت عن رسول الله -عليه الصلاة والسلام- أنه قال له رجل: يا رسول الله، يأتيني الرجل يريد مالي؟ قال: لا تعطه مالك، قال: فإن قاتلني؟ قال: قاتله. قال: فإن قتلته؟ قال: فهو في النار. قال: فإن قتلني؟ قال: فأنت شهيد هكذا أمره النبي ﷺ رواه مسلم في الصحيح.  فأنت بالخيار إن قاتلته إذا أبى إلا القتال؛ فلك أن تقاتله، ولا تعطه مالك، وإذا أردت أن تفدي نفسك بمالك، وأن تعطيه ما يكفيك قتاله؛ فلا بأس عليك، النفس أغلى من المال، لكن إن قاتلت؛ فلا بأس عليك، وإن قتلته؛ فهو في النار -نعوذ بالله - ودمه هدر، وإن قتلك فأنت شهيد؛ لأنك مظلوم، وإن عرفت أن تسكته بشيء من مالك، ثم ترفع أمره إلى ولاة الأمور بعد ذلك، هذا لا بأس به، ولا حرج فيه.  المعنى ليس بلازم لك أن تقاتل، فإن قاتلت؛ فلا حرج، وإن تركته وشره، وأعطيته بعض ما يرضيه؛ حتى تحفظ نفسك، ودمك؛ فلا بأس بذلك، ثم ترفع بأمره بعد ذلك.","link":"https://binbaz.org.sa/fatwas/2383/حكم-مقاتلة-قطاع-الطرق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_916.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":6545,"question":"إذا ثبتت سرقة في حق مسلم، فهل يحل لي أن يرد إلي مالي على ألا أبلغ القاضي ليقيم عليه حد السرقة، علمًا بأن المبلغ المسروق حوالي مائة ألف ريال؟","title":"المسامحة في الحدود قبل أن تبلغ السلطان","answer":"الجواب: لا بأس إذا تراضيت أنت وإياه، وأعطاك مالك، وسترت عليه، لا بأس، ولكن إذا كان شره كثيرًا، أو علمت أنه يتعاطى هذا مع الناس، فهذا ينبغي أن يرفع عنه، ويعتدى عليه حتى يكفى شره الناس.  أما إذا كانت مرة واحدة بينك وبينه، أو مرتين، ليس من أهل الشر المعروف؛ فلا بأس بالستر عليه، والمصالحة معه، لأن الرسول ﷺ لما سرق رداء صفوان بن أمية أتى به النبي ﷺ وقال له: إن هذا سرق ردائي، فأمر النبي بقطع يده. فقال يا رسول الله قد عفوت عنه، ردائي هو له. فقال: هلا كان هذا قبل أن تأتني به، إذا بلغت الحدود السلطان؛ فلعن الشافع والمشفع.  المقصود: أنها قبل أن تبلغ السلطان لا بأس أن تعفو عن الذي سرق منك، وتنصحه، وتحذره من العود، أما إذا بلغت السلطان، ورفعت إلى المحكمة، رفعت إلى الأمير، لا ما يعفى عنه، لا بد من إقامة الحدود بعد بلوغها السلطان.","link":"https://binbaz.org.sa/fatwas/2384/المسامحة-في-الحدود-قبل-ان-تبلغ-السلطان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_917.mp3","categories":["الجنايات والحدود","الآداب والأخلاق المحمودة"]},{"id":6547,"question":"إذا ثبتت سرقة في حق مسلم، فهل يحل لي أن يرد إلي مالي على ألا أبلغ القاضي ليقيم عليه حد السرقة، علمًا بأن المبلغ المسروق حوالي مائة ألف ريال؟","title":"المسامحة في الحدود قبل أن تبلغ السلطان","answer":"الجواب: لا بأس إذا تراضيت أنت وإياه، وأعطاك مالك، وسترت عليه، لا بأس، ولكن إذا كان شره كثيرًا، أو علمت أنه يتعاطى هذا مع الناس، فهذا ينبغي أن يرفع عنه، ويعتدى عليه حتى يكفى شره الناس.  أما إذا كانت مرة واحدة بينك وبينه، أو مرتين، ليس من أهل الشر المعروف؛ فلا بأس بالستر عليه، والمصالحة معه، لأن الرسول ﷺ لما سرق رداء صفوان بن أمية أتى به النبي ﷺ وقال له: إن هذا سرق ردائي، فأمر النبي بقطع يده. فقال يا رسول الله قد عفوت عنه، ردائي هو له. فقال: هلا كان هذا قبل أن تأتني به، إذا بلغت الحدود السلطان؛ فلعن الشافع والمشفع.  المقصود: أنها قبل أن تبلغ السلطان لا بأس أن تعفو عن الذي سرق منك، وتنصحه، وتحذره من العود، أما إذا بلغت السلطان، ورفعت إلى المحكمة، رفعت إلى الأمير، لا ما يعفى عنه، لا بد من إقامة الحدود بعد بلوغها السلطان.","link":"https://binbaz.org.sa/fatwas/2384/المسامحة-في-الحدود-قبل-ان-تبلغ-السلطان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_917.mp3","categories":["الجنايات والحدود","الآداب والأخلاق المحمودة"]},{"id":6567,"question":"ما حكم وضع الابن غير الشرعي -أي ابن الزنا- بالمجتمع المسلم؟ ولمن ينسب، ومن يكون وليه؟ وهل يولى القضاء إذا تأهل لذلك؟ وهل يزوج من المسلمة؟ وأين يدفن إذا مات؟ وهل يصلى عليه؟ ففي بعض المجتمعات يقتل الطفل عند الولادة، فما حكم من يفعل ذلك ؟","title":"أحكام ولد الزنا","answer":"الجواب:\n\nولد الزنا إذا كان من أم مسلمة؛ حكمه حكم أولاد المسلمين، يربيه المسلمون، ويحسنون إليه، وليس عليه من ذنب أمه، ولا ذنب من زنا بها شيء: وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى [الأنعام:164] فالوزر عليهما، لا عليه، وإنما هو أمانة بين المسلمين، عليهم أن يربوه تربية إسلامية، وأن يحسنوا إليه حتى يشب، ويكبر، وإذا بلغ الحلم؛ حكمه حكم سائر المسلمين، وعلى الدولة أن تقوم بهذا الأمر، وأن تعنى بهذا الأمر؛ حتى تصون هؤلاء، وتحميهم من القتل، ومن الأذى.\n\nوأما كونه يقتل بعد الولادة، أو تسعى في قتله عند الولادة، هذا منكر عظيم، ولا يجوز، ومن فعل هذا جمع جريمتين، جريمة الزنا، وجريمة القتل بغير حق، نعوذ بالله. \n\nفالواجب: ألا يقتل، بل يحفظ، ويدع في دار الحضانة الإسلامية، أو إلى امرأة مسلمة تقوم بحاله، وتحضنه، وتحسن إليه، وتربيه، ويعلم مع أولاد المسلمين في بلاد المسلمين، ويوجه إلى الخير، ومتى استقام، وبلغ الحلم، وتخلق بأخلاق الأخيار؛ صح أن يكون داعية إلى الله، وأن يكون قاضيًا، وأن يكون أميرًا، وأن يكون زوجًا لبقية من يكافئه من المسلمين، فليس عليه ذنب، الذنب على غيره، إنما عليه الاستقامة إذا بلغ، عليه أن يستقيم على أمر الله، وأن يحذر محارم الله، ومتى صلح في نفسه، واستقام في نفسه؛ فحكمه حكم سائر المسلمين، له ما لهم، وعليه ما عليهم، وإذا مات صغيرًا؛ دفن في مقابر المسلمين، مادام من أم مسلمة، دفن في مقابر المسلمين، غسل، وصلي عليه كسائر أولاد المسلمين، ولا يجوز إهماله ولا إضاعته، ويسمى بالأسماء المناسبة: عبدالله، عبدالرحمن، عبدالملك، الأسماء التي تناسب، محمد، زيد، ما في بأس، محمد، زيد، أي اسم من الأسماء المناسبة، يقال: ابن عبدالله، ينسب إلى عبدالله إلى عبدالملك، كل الناس عبيد الله.\n\nالسؤال: .. يزوج من..؟\n\nالجواب: يزوج من المسلمين، المسلم إذا صلح؛ ما تضره أمه، ولا يضره من زنا بها .\n\nالسؤال: طيب إن كان هذا الشخص بأن الطفل هذا مات، وهو مجهول؟\n\nالجواب:  يدفن مع المسلمين، والحمد لله، والله يتولى حسابه.\n\nالسؤال: يتولى القضاء يا شيخ؟\n\nالجواب:  يتولى القضاء وغيره.","link":"https://binbaz.org.sa/fatwas/2415/احكام-ولد-الزنا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_942.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":6623,"question":"كثيرًا ما نسمع عن الإضراب عن الطعام حتى الموت، ما حكم الإسلام في ذلك؟","title":"حكم الإضراب عن الطعام حتى الموت","answer":"الجواب: هذا الإضراب ما له أصل، هذا إعانة للأعداء على مقاصدهم الخبيثة، هذا النظام ما له أصل، وإذا كان يفضي إلى ضرر عليه، أو قتل نفسه؛ فهو لا يجوز، هذا الذي نعتقده في هذا، هذا أخذوه من أعداء الله، هذا لا نعرف له أصلًا.","link":"https://binbaz.org.sa/fatwas/2470/حكم-الاضراب-عن-الطعام-حتى-الموت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_997.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":6627,"question":"سؤالي: في شخص يأتي من دولة البحرين اسمه: أبو دجانة، لكن اسمه الحقيقي علي الملا يدعى أنه يعالج المرضى، ولكن يوم ذهبت للدمام؛ لأن والدي وعده يوم الخميس أن يعالج الوالدة، فجاء البيت، وعالج الوالدة، ولكن رأيته أنا، وكدت أضربه، لكن خفت من والدي؛ لأنه شخص يشرب الدخان، وحليق اللحية سألته لماذا تشرب؟ قال: يجب أن أكون هادئًا عندما يأتوني، ويعلموني الأمراض أين هي. فقال ما اسمك -للوالدة-؟ فقالت: كذا وكذا. فكتب أعدادًا عنده، وقال إن كذا وكذا من الأمراض، فأجاب بعضها صحيح، وبعضها غلط، وأعطى الوالدة أشياء من الأوراق لا يعرف فيه إلا اسم الله أول شيء، والباقي لا يعرف، وقال: هذه تضعينها في المخدة، وهذه تتبخرين بها، وهذه تشربينها، ولكن -بفضل الله- أنا خوفت والدتي، فقلت لها: إذا استعملت هذا الدواء فسيدخل عليك شيء من النافذة، ولم تستعمله، وقال لوالدي هذا الكاهن: إن زوجتك سوف تشفى يوم الخميس، وبالفعل سرقت بقالة والدي يوم الخميس، وأخذ منها مبلغًا وقدره ستون ألف ريالًا، ولكن أنا لم أسكت على هذا الموضوع، بل أخبرت وأردنا أن نقبض عليه، ولكنه شرد منا، وإنه يأتي كل يوم خميس إلى الدمام، وهو مشترك مع شخص سعودي في العملية؛ لأنه هو الذي يتصل به، هل أخبر عن السعودي هذا، أم أسكت، وبالعلم ماذا عليه الذي يصدق بهذا الرجل ويستعمل الدواء؟","title":"كيفية التعامل مع السحرة","answer":"الجواب: لا شك أن هذا من العرافين، ومن الكهنة، ومن المفسدين في الأرض، مثل هذا لا يقبل، ولا يستعمل في العلاج، بل هذا يجب القبض عليه، وتأديبه بما يلزم، وسجنه بما يستحق؛ حتى يعاد إلى بلاده -إذا كان من غير هذه البلاد- بعد النظر، وبعد تحكيم الشريعة فيه، على المحكمة أن تنظر في أمره، وتحضر الشهود العارفين به حتى تحكم عليه المحكمة بما يستحق من التأديب، والسجن، وغير ذلك. هذا لا يجوز الذي يقول: اسمك كذا، أو اسم أبيها، أو يعطي كلمات لا يعرف معناها ... وخطوط مقطعة، أو حروف مقطعة، أو أشباهه من الشيطان التي لا تعرف، هذا كله من الدلائل على أنه من الكهنة، ومن المنجمين، ومن العرافين، أو من الكذابين اللعابين الذي يشوش على الناس. وقوله: إن مرضها يزول يوم الخميس هذا يدل على جهله، وضلاله، فإن زوال المرض لا يعلم متى يزول إلا الله .  الحاصل: أن مثل هؤلاء كذبة، فجرة، لا يجوز إقرارهم، بل هم من جملة العرافين، الكذابين، المدعين للطب، وهم يكذبون، ويأخذون أشياء من الجن، والشياطين، ويستعينون بها على بعض باطلهم ليأخذوا أموال الناس بالباطل.  وأنت أيها الكاتب لا بد تكتب لنا على اسم السعودي -ولا نبين اسمك إن شاء الله- تكتب اسم السعودي، ولا تبين اسمك ما يخالف إذا كانت خائفًا.","link":"https://binbaz.org.sa/fatwas/2493/كيفية-التعامل-مع-السحرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_1020.mp3","categories":["الجنايات والحدود","السحر والكهانة"]},{"id":6638,"question":"كثيرًا ما نسمع عن الإضراب عن الطعام حتى الموت، ما حكم الإسلام في ذلك؟","title":"حكم الإضراب عن الطعام حتى الموت","answer":"الجواب: هذا الإضراب ما له أصل، هذا إعانة للأعداء على مقاصدهم الخبيثة، هذا النظام ما له أصل، وإذا كان يفضي إلى ضرر عليه، أو قتل نفسه؛ فهو لا يجوز، هذا الذي نعتقده في هذا، هذا أخذوه من أعداء الله، هذا لا نعرف له أصلًا.","link":"https://binbaz.org.sa/fatwas/2470/حكم-الاضراب-عن-الطعام-حتى-الموت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_997.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":6642,"question":"سؤالي: في شخص يأتي من دولة البحرين اسمه: أبو دجانة، لكن اسمه الحقيقي علي الملا يدعى أنه يعالج المرضى، ولكن يوم ذهبت للدمام؛ لأن والدي وعده يوم الخميس أن يعالج الوالدة، فجاء البيت، وعالج الوالدة، ولكن رأيته أنا، وكدت أضربه، لكن خفت من والدي؛ لأنه شخص يشرب الدخان، وحليق اللحية سألته لماذا تشرب؟ قال: يجب أن أكون هادئًا عندما يأتوني، ويعلموني الأمراض أين هي. فقال ما اسمك -للوالدة-؟ فقالت: كذا وكذا. فكتب أعدادًا عنده، وقال إن كذا وكذا من الأمراض، فأجاب بعضها صحيح، وبعضها غلط، وأعطى الوالدة أشياء من الأوراق لا يعرف فيه إلا اسم الله أول شيء، والباقي لا يعرف، وقال: هذه تضعينها في المخدة، وهذه تتبخرين بها، وهذه تشربينها، ولكن -بفضل الله- أنا خوفت والدتي، فقلت لها: إذا استعملت هذا الدواء فسيدخل عليك شيء من النافذة، ولم تستعمله، وقال لوالدي هذا الكاهن: إن زوجتك سوف تشفى يوم الخميس، وبالفعل سرقت بقالة والدي يوم الخميس، وأخذ منها مبلغًا وقدره ستون ألف ريالًا، ولكن أنا لم أسكت على هذا الموضوع، بل أخبرت وأردنا أن نقبض عليه، ولكنه شرد منا، وإنه يأتي كل يوم خميس إلى الدمام، وهو مشترك مع شخص سعودي في العملية؛ لأنه هو الذي يتصل به، هل أخبر عن السعودي هذا، أم أسكت، وبالعلم ماذا عليه الذي يصدق بهذا الرجل ويستعمل الدواء؟","title":"كيفية التعامل مع السحرة","answer":"الجواب: لا شك أن هذا من العرافين، ومن الكهنة، ومن المفسدين في الأرض، مثل هذا لا يقبل، ولا يستعمل في العلاج، بل هذا يجب القبض عليه، وتأديبه بما يلزم، وسجنه بما يستحق؛ حتى يعاد إلى بلاده -إذا كان من غير هذه البلاد- بعد النظر، وبعد تحكيم الشريعة فيه، على المحكمة أن تنظر في أمره، وتحضر الشهود العارفين به حتى تحكم عليه المحكمة بما يستحق من التأديب، والسجن، وغير ذلك. هذا لا يجوز الذي يقول: اسمك كذا، أو اسم أبيها، أو يعطي كلمات لا يعرف معناها ... وخطوط مقطعة، أو حروف مقطعة، أو أشباهه من الشيطان التي لا تعرف، هذا كله من الدلائل على أنه من الكهنة، ومن المنجمين، ومن العرافين، أو من الكذابين اللعابين الذي يشوش على الناس. وقوله: إن مرضها يزول يوم الخميس هذا يدل على جهله، وضلاله، فإن زوال المرض لا يعلم متى يزول إلا الله .  الحاصل: أن مثل هؤلاء كذبة، فجرة، لا يجوز إقرارهم، بل هم من جملة العرافين، الكذابين، المدعين للطب، وهم يكذبون، ويأخذون أشياء من الجن، والشياطين، ويستعينون بها على بعض باطلهم ليأخذوا أموال الناس بالباطل.  وأنت أيها الكاتب لا بد تكتب لنا على اسم السعودي -ولا نبين اسمك إن شاء الله- تكتب اسم السعودي، ولا تبين اسمك ما يخالف إذا كانت خائفًا.","link":"https://binbaz.org.sa/fatwas/2493/كيفية-التعامل-مع-السحرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_1020.mp3","categories":["الجنايات والحدود","السحر والكهانة"]},{"id":6664,"question":"هل يجوز استعمال التنويم المغناطيسي في اكتشاف سرقة مبلغ من المال في بلد لا تحكم بشريعة الله؟ وهل هو نوع من الشعوذة، أم أنه من العلم؟","title":"حكم استعمال التنويم المغناطيسي في اكتشاف السرقات","answer":"الجواب: هذا لا أدري عنه، لكن الذي يظهر لي -والله أعلم- والأقرب عندي: أنه لا يجوز هذا؛ لأن معناه إكراه له على الإقرار بغير حق، فليس من الشرع أن ينوم حتى يقر بغير اختياره، والشريعة جاءت بالستر على المسلمين، فلا ينبغي أن يستعمل هذا، لكن من ظهر منه الحق بإقراره الصريح، ما هو بالإكراه، أو بالبينة؛ نفذ فيه حكم الله، وأما إذا كان فيه إكراه أو .. التنويم المغناطيسي فهذا يشبه الإكراه، الذي يظهر لي -والله أعلم- أنه لا يجوز ..","link":"https://binbaz.org.sa/fatwas/2544/حكم-استعمال-التنويم-المغناطيسي-في-اكتشاف-السرقات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1039.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":6708,"question":"رجل الآن يسكن جنبي، وعنده ثمانية من الأطفال، والآن زوجته حامل، تقول: أريد أسقط هذا الجنين، هل هذا يجوز؟الشيخ: تقول ماذا؟الطالب: يقول: العيال الآن أنا عندي ثمانية مكفينا، والذي في بطنها ذا لازم أسقطه لأجلها؟","title":"حكم إسقاط الجنين","answer":"الجواب:  هذا يختلف، إن كان في الأربعين الأولى، وعليها ضرر؛ فلا بأس في الأربعين الأولى، أما بعد هذا لا يجوز. السؤال: إذا كان يعني يا شيخ شهر، شهرين؟ الجواب: لا شهر بس، الأربعين الأولى فقط.  السؤال: أربعين يومًا؟ الجواب: في حال النطفة، هذا يجوز عند الحاجة إلى ذلك بالطرق المباحة التي ما فيها مضرة، يعرفها الأطباء.","link":"https://binbaz.org.sa/fatwas/2589/حكم-اسقاط-الجنين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1085.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":6719,"question":"رجل الآن يسكن جنبي، وعنده ثمانية من الأطفال، والآن زوجته حامل، تقول: أريد أسقط هذا الجنين، هل هذا يجوز؟الشيخ: تقول ماذا؟الطالب: يقول: العيال الآن أنا عندي ثمانية مكفينا، والذي في بطنها ذا لازم أسقطه لأجلها؟","title":"حكم إسقاط الجنين","answer":"الجواب:  هذا يختلف، إن كان في الأربعين الأولى، وعليها ضرر؛ فلا بأس في الأربعين الأولى، أما بعد هذا لا يجوز. السؤال: إذا كان يعني يا شيخ شهر، شهرين؟ الجواب: لا شهر بس، الأربعين الأولى فقط.  السؤال: أربعين يومًا؟ الجواب: في حال النطفة، هذا يجوز عند الحاجة إلى ذلك بالطرق المباحة التي ما فيها مضرة، يعرفها الأطباء.","link":"https://binbaz.org.sa/fatwas/2589/حكم-اسقاط-الجنين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1085.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":6760,"question":"ما حكم من يعرف حكم الله في جزئية من الإسلام، ولكنه يرتكب الحرام فيها، ويرفض حكم الله؟","title":"حكم من يرتكب ذنباً وهو يعلم حكم الله فيه","answer":"الشيخ: هذا حكمه حكم أهل المعاصي، فالناس يعرفون أن الزنا حرام، ويزنون، ويعرفون أن الخمر حرام، ويقعون في ..، فعلى من وقع في المعصية، وهو يعلم أنها معصية، عليه عقوبتها، وعليه خطرها، لكن إذا استحل إذا قال: الزنا حلال؛ يكون كافرًا -نعوذ بالله- وإذا قال: إن الخمر حلال؛ صار كافرًا، وإذا قال: إن اللواط حلال؛ صار كافرًا -نعوذ بالله- وإذا قال: إن السرقة حلال؛ صار كافرًا.  أما إذا فعل هذه المعاصي، ويعلم أنه عاصٍ، ويعلم أنه مخالف لأمر الله، ويعلم أنه على خطر؛ فله حكم العصاة، تحت مشيئة الله  وعلى الدولة المسلمة أن تقيم فيهم أمر الله، وتقيم عليه حد الله، ولا يكون كافرًا بذلك، إذا زنا لا يكون كافرًا إلا إذا استحل الزنا، وإن شرب الخمر ما يكون كافرًا إلا إذا استحل الخمر، وقال: إنه حلال. وهكذا إذا عق والديه لا يكون كافرًا، لكن إذا قال: يباح لي عقوق والدي؛ يكون كافرًا -نعوذ بالله- وإذا قال: يباح لي أن أفعل الزنا، وأن أشرب الخمر؛ صار كافرًا -نعوذ بالله-. فالحاصل: أن العصاة على قسمين: عصاة استحلوا المعاصي التي حرمها الله، ورأوها مباحة، فهؤلاء كفار إباحيون مع الكفرة، يجب أن يستتابوا، فإن تابوا، وإلا قتلوا من ولاة أمور المسلمين. القسم الثاني: عصاة يعرفون أنهم عصاة، ويعلمون أنهم عصاة، ولكن حملهم الشيطان، والنفس الأمارة بالسوء على تعاطي المعصية، فهؤلاء مثل ما قال الله -جل وعلا- تحت مشيئة الله: وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48] هو تحت مشيئة الله، إن شاء الله غفر له إذا مات على ذلك، وإن شاء عذبه على قدر الجريمة التي مات عليها، ثم بعدما يطهر في النار، ويعذب، بعد ذلك يدخل إلى الجنة بإسلامه الذي مات عليه، وتوحيده الذي مات عليه.","link":"https://binbaz.org.sa/fatwas/2667/حكم-من-يرتكب-ذنبا-وهو-يعلم-حكم-الله-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1164.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":6801,"question":"رجل قذف شخصًا آخر بالفاحشة، وأصر المقذوف على أنه يشكوه إلى القاضي، ولكن هناك من دعوا المقذوف ألا يشكوه، ما الحكم في هذا؟","title":"حكم من قذف بالفاحشة وعفا عمن قذفه ولم يخاصمه","answer":"الجواب: القذف من حق الإنسان، ليس من حق الله في هذا، من حقوق الإنسان، كما لو ضربه أو قتل ولده، وما أشبه ذلك، إن شكاه، وطلب حقه؛ فلا بأس، وإن عفا؛ فله أجر العفو أَنْ تَعْفُوا أَقْرَبُ لِلتَّقْوَى [البقرة:237] هذا هو الصواب في حد القذف. فإذا قذف بفاحشة، أو شتمه، أو ما أشبه ذلك، فإن طلب الحق؛ وجب أخذ الحق له إذا ثبت متعدي عليه، وإن عفا؛ فلا حرج في ذلك، بخلاف إذا كان الحق لله، فإنه إذا بلغ السلطان؛ فلا يقال صاحبه، بل يقام عليه الحد، أما حق المخلوق مال له سرقه منه، فعفا عن المال، أو ظلمه، أو قذفه، أو سبه وعفا، لا بأس.","link":"https://binbaz.org.sa/fatwas/2703/حكم-من-قذف-بالفاحشة-وعفا-عمن-قذفه-ولم-يخاصمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1202.mp3","categories":["الجنايات والحدود","الآداب والأخلاق المحمودة"]},{"id":6819,"question":"رجل قذف شخصًا آخر بالفاحشة، وأصر المقذوف على أنه يشكوه إلى القاضي، ولكن هناك من دعوا المقذوف ألا يشكوه، ما الحكم في هذا؟","title":"حكم من قذف بالفاحشة وعفا عمن قذفه ولم يخاصمه","answer":"الجواب: القذف من حق الإنسان، ليس من حق الله في هذا، من حقوق الإنسان، كما لو ضربه أو قتل ولده، وما أشبه ذلك، إن شكاه، وطلب حقه؛ فلا بأس، وإن عفا؛ فله أجر العفو أَنْ تَعْفُوا أَقْرَبُ لِلتَّقْوَى [البقرة:237] هذا هو الصواب في حد القذف. فإذا قذف بفاحشة، أو شتمه، أو ما أشبه ذلك، فإن طلب الحق؛ وجب أخذ الحق له إذا ثبت متعدي عليه، وإن عفا؛ فلا حرج في ذلك، بخلاف إذا كان الحق لله، فإنه إذا بلغ السلطان؛ فلا يقال صاحبه، بل يقام عليه الحد، أما حق المخلوق مال له سرقه منه، فعفا عن المال، أو ظلمه، أو قذفه، أو سبه وعفا، لا بأس.","link":"https://binbaz.org.sa/fatwas/2703/حكم-من-قذف-بالفاحشة-وعفا-عمن-قذفه-ولم-يخاصمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1202.mp3","categories":["الجنايات والحدود","الآداب والأخلاق المحمودة"]},{"id":6888,"question":"ورد في محاضرة فضيلتكم أن مستحل الزنا يعتبر كافرًا، قد يفهم بعض الحاضرين أن مرتكب الزنا كافر، فيذهب من هنا يكفر العاميين، إذا يُرى من فضيلتكم التوضيح؟","title":"الفرق بين مستحل الزنا ومرتكب الزنا","answer":"الجواب: أنا بينت أن مستحل الزنا غير فاعل الزنا، فالاستحلال معناه: أن يقول: الزنا مباح، حلال، من شاء فعله، وليس بحرام، ما حرمه الله، أو يقول: ولو حرمه الله حلال، ولو حرمه الله لا يبالي بتحريمه، هذا هو الكافر. أما من يفعله، يزني ولكنه يعلم أنه عاصٍ، وأنه حرام، ولكن زنى، غلبه الهوى، والنفس الأمارة بالسوء، والشيطان حتى وقع في الزنا، هذا إن تاب؛ تاب الله عليه، وإن مات على الزنا، ولم يتب؛ فهذا تحت مشيئة الله، إن شاء ربنا غفر له، وإن شاء عذبه على قدر معصيته في النار، ثم بعدما يعذب لا يخلد، بل يخرجه الله من النار إلى الجنة، بتوحيده، وإسلامه، وهكذا من مات على اللواط، أو الخمر، أو العقوق لوالديهـ أو قطيعة الرحم، أو الربا، أو ما أشبه ذلك من المعاصي، فهذا تحت مشيئة الله -كما سبق-. فرق بينهما، فالمستحل هو الذي يقول: إن هذه المعصية حلال، الربا حلال، الزنا حلال، هذا يكون كافرًا، وأما الذي يفعله، ولا يستحله، يزني، ولكن يعلم أنه عاصٍ، أو فعل الربا، ويعلم أنه محرم، ولكن فعله طاعة للهوى، وحبًا للمال، فهذا عاصٍ، وليس بكافر. وكذلك من عق والديه، ضرب أمه، أو ضرب أباه، أو سبهما وهو يعلم أنه عاصٍ، ولكن غلبه هواه، ونفسه الأمارة بالسوء، فهذا يكون عاصيًا، أما لو قال: إنه حلال أني أضرب أمي، حلال أني أضرب أمي، يكون كافرًا، لعله واضح هذا.","link":"https://binbaz.org.sa/fatwas/2781/الفرق-بين-مستحل-الزنا-ومرتكب-الزنا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1273.mp3","categories":["مسائل متفرقة في العقيدة","الجنايات والحدود"]},{"id":6908,"question":"سمعنا من بعض طلبة العلم أن سماحتكم قلتم إن من زاد في سرعة سيارته عن مائة وعشرين كيلو، وحصل له حادث، وتوفي؛ يعتبر منتحرًا، فما مدى صحة هذا القول؟","title":"حكم زيادة سرعة السيارة عن تحديد أنظمة المرور","answer":"الجواب: ما صدر منا شيء في هذا، لكن الناس يكتبون كلمات لم يصدر مني شيء في هذا، ولكني أوصي بعدم السرعة، يتصلون بي، وأحذرهم من السرعة، وأقول السرعة في الحقيقة طريق لهلاك نفسك، وهلاك غيرك، فالواجب عليك أن تأخذ الطريق السوي، والعادة التي يرشد إليها كلام المرور، ويوجه إليها حتى تكون آخذًا بالحيطة لنفسك، ولمن معك. هذا هو الواجب على أصحاب السيارات: أن يسلكوا الطريق السوي، وألا يزيدوا في السرعة التي تضرهم، وتضر غيرهم؛ ثقة بأنهم سالمون، وأنهم معلمون، وهذا كله من الشيطان، من يقول له: إنك سالم، وإنك لا تقع في الخطأ، هذا لا شك أنه من التساهل الذي لا ينبغي.","link":"https://binbaz.org.sa/fatwas/2835/حكم-زيادة-سرعة-السيارة-عن-تحديد-انظمة-المرور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1283.mp3","categories":["الجنايات والحدود","الأخلاق المذمومة"]},{"id":6935,"question":"وضعت امرأة علاجًا مكونًا من حبوب في ثلاجة في بيتها، وتسلطت عليها طفلة، وأكلتها، وكانت سببًا في وفاتها في حينها، فهل على المرأة من شيء، مع أن هذا الأمر حدث منذ خمس سنوات؟","title":"حكم امرأة تناولت طفلتها دواءً فماتت بسببه","answer":"الجواب: الجواب -والله أعلم- إن كان المحل الذي وضعت فيه الحبوب في محل قريب في متناول الأطفال، قريب منهم، بحيث ما احتاطت، ولا أبعدته عنهم في محل رفيع؛ فالأظهر -والله أعلم- عليها الدية، والكفارة؛ لأنها جعلته في محل قريب من الأطفال، والأطفال كالبهائم. أما إذا كان في محل رفيع، وفي محل بعيد عن متناولهم؛ فالظاهر أنه ليس عليها شيء؛ لأن الطفل قد يتعبث، ويطلع على الأشياء، ويتناول أشياء بعيدة؛ فلا عليها شيء -إن شاء الله-. السؤال: ما عليها شيء؟ الجواب: ما عليها شيء إذا كان في محل مرتفع عن متناول الأطفال، وليس حولهم. السؤال: ما في عليها صيام يعني؟ الجواب: لا عليها صيام، ولا غيره.","link":"https://binbaz.org.sa/fatwas/2865/حكم-امراة-تناولت-طفلتها-دواء-فماتت-بسببه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1313.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":6978,"question":"امرأة حامل في شهرها الثالث، أصر زوجها على إخراج ابنها، وإلا يطلقها، وهي معها منه ثمانية أولاد، ففعلت ما أراد منها مكرهة، وأخرجت جنينها خوفًا من الطلاق، وسؤالها يتلخص في الأمر الآتي: هل يلزمها شيء من الكفارة؟ وهل عليها إثم؟ وهل الغرة واجبة في هذه الحالة؟","title":"حكم من أجبر زوجته على إسقاط حملها","answer":"الجواب: عليها التوبة إلى الله، وعليه التوبة هو، كلاهما عليه التوبة، ولا عليهما شيء، عليهما التوبة إلى الله؛ لأن هذا عمد، عليهما التوبة إلى الله  الله يهديهم جميعًا، عليهم التوبة إلى الله. ولا يجوز إخراج الطفل بعدما يتجاوز الأربعين، ما يجوز التعرض له، بل يستعين بالله، ولعل الله يجعل فيه البركة، والخير، ما يدرون لعله يكون أبرك من الذي قبله، أما في الأربعين الأولى إذا دعت الحاجة إلى ذلك؛ فالأمر في هذا واسع عند جمع من أهل العلم، أما إذا جاوز الأربعين، وصار إلى العلقة؛ فلا يجوز التعرض له. السؤال: ولي الأمر هل عليه التعزير على ذلك إذا علم ذلك؟ الجواب: نعم لولي الأمر أن يعزر من فعل ذلك، لولي الأمر إذا عرف ذلك.","link":"https://binbaz.org.sa/fatwas/2899/حكم-من-اجبر-زوجته-على-اسقاط-حملها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1347.mp3","categories":["الجنايات والحدود","الأخلاق المذمومة"]},{"id":7262,"question":"ما هو حد الحرابة؟ ومن تاب قبل أن يقدر عليه في حد الحرابة هل يقام عليه الحد؟","title":"ما هو حد الحرابة وما حكم من تاب قبل أن يقدر عليه؟","answer":"الجواب: \n\nالحرابة من المنكرات العظيمة، وهي قطع الطريق، والخروج على الناس بالسلاح لأخذ أموالهم، هذه يقال لها: حرابة، يقال لهم: قطاع الطريق، ويقال لهم: المفسدون في الأرض. \n\nوهم يخرجون على الناس بالسلاح، بأنواع السلاح، ولو بالعصي في البلد، أو في الطرقات، والفلاوي الصحراء، يتعرضون لهم بالسلاح، أو بالعصي، أو بأيديهم على الصحيح، حتى ولو بأيديهم -إذا كان ما في أيديهم سلاح- ولو بأيديهم بالقوة، فيأخذون أموال الناس بالقوة.\n\nهؤلاء يقال لهم قطاع الطريق، وعلى ولي الأمر أن يعاملهم بما ذكره الله في كتابه في قوله سبحانه: إِنَّمَا جَزَاءُ الَّذِينَ يُحَارِبُونَ اللَّهَ وَرَسُولَهُ وَيَسْعَوْنَ فِي الْأَرْضِ فَسَادًا أَنْ يُقَتَّلُوا أَوْ يُصَلَّبُوا أَوْ تُقَطَّعَ أَيْدِيهِمْ وَأَرْجُلُهُمْ مِنْ خِلَافٍ أَوْ يُنْفَوْا مِنَ الْأَرْضِ ذَلِكَ لَهُمْ خِزْيٌ فِي الدُّنْيَا وَلَهُمْ فِي الْآخِرَةِ عَذَابٌ عَظِيمٌ ۝ إِلَّا الَّذِينَ تَابُوا مِنْ قَبْلِ أَنْ تَقْدِرُوا عَلَيْهِمْ فَاعْلَمُوا أَنَّ اللَّهَ غَفُورٌ رَحِيم  [المائدة:33، 34].\n\nهؤلاء هم قطاع الطريق، وهم أصحاب الحرابة، وعلى ولي الأمر أن يتابعهم بالقوة، وأن يجتهد في تتبع آثارهم، ومطاردتهم حتى يمسكهم، ويقضي عليهم بما شرع الله، حتى لا يفسدوا في الأرض، وحتى لا يخلوا بالأمن.\n\nالسؤال: الربا من الحرابة؟\n\nالجواب: حرب لله ورسوله، لكن ما هي من الحرابة المعروفة، تسمى حربًا لله ورسوله؛ لأنها معصية، وكبيرة، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/3329/ما-هو-حد-الحرابة-وما-حكم-من-تاب-قبل-ان-يقدر-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1650.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":7272,"question":"ما هو حد الحرابة؟ ومن تاب قبل أن يقدر عليه في حد الحرابة هل يقام عليه الحد؟","title":"ما هو حد الحرابة وما حكم من تاب قبل أن يقدر عليه؟","answer":"الجواب: \n\nالحرابة من المنكرات العظيمة، وهي قطع الطريق، والخروج على الناس بالسلاح لأخذ أموالهم، هذه يقال لها: حرابة، يقال لهم: قطاع الطريق، ويقال لهم: المفسدون في الأرض. \n\nوهم يخرجون على الناس بالسلاح، بأنواع السلاح، ولو بالعصي في البلد، أو في الطرقات، والفلاوي الصحراء، يتعرضون لهم بالسلاح، أو بالعصي، أو بأيديهم على الصحيح، حتى ولو بأيديهم -إذا كان ما في أيديهم سلاح- ولو بأيديهم بالقوة، فيأخذون أموال الناس بالقوة.\n\nهؤلاء يقال لهم قطاع الطريق، وعلى ولي الأمر أن يعاملهم بما ذكره الله في كتابه في قوله سبحانه: إِنَّمَا جَزَاءُ الَّذِينَ يُحَارِبُونَ اللَّهَ وَرَسُولَهُ وَيَسْعَوْنَ فِي الْأَرْضِ فَسَادًا أَنْ يُقَتَّلُوا أَوْ يُصَلَّبُوا أَوْ تُقَطَّعَ أَيْدِيهِمْ وَأَرْجُلُهُمْ مِنْ خِلَافٍ أَوْ يُنْفَوْا مِنَ الْأَرْضِ ذَلِكَ لَهُمْ خِزْيٌ فِي الدُّنْيَا وَلَهُمْ فِي الْآخِرَةِ عَذَابٌ عَظِيمٌ ۝ إِلَّا الَّذِينَ تَابُوا مِنْ قَبْلِ أَنْ تَقْدِرُوا عَلَيْهِمْ فَاعْلَمُوا أَنَّ اللَّهَ غَفُورٌ رَحِيم  [المائدة:33، 34].\n\nهؤلاء هم قطاع الطريق، وهم أصحاب الحرابة، وعلى ولي الأمر أن يتابعهم بالقوة، وأن يجتهد في تتبع آثارهم، ومطاردتهم حتى يمسكهم، ويقضي عليهم بما شرع الله، حتى لا يفسدوا في الأرض، وحتى لا يخلوا بالأمن.\n\nالسؤال: الربا من الحرابة؟\n\nالجواب: حرب لله ورسوله، لكن ما هي من الحرابة المعروفة، تسمى حربًا لله ورسوله؛ لأنها معصية، وكبيرة، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/3329/ما-هو-حد-الحرابة-وما-حكم-من-تاب-قبل-ان-يقدر-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1650.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":7283,"question":"لي والدة ولها طفل توفي منذ زمن قديم، وسبب الوفاة هو أنها كانت واضعة عليه الغطاء، أو اللحاف، وأنه من الصوف، ولقد توفيت هذه الطفلة إثر هذا اللحاف، علمًا بأنها لم تقصد هذا الفعل ولكن من جهلها بمثل هذه الأمور، والآن هل عليها كفارة أم لا؟","title":"غطت ولدها بلحاف فمات هل عليها الدية والكفارة؟","answer":"الجواب:\n\nنعم إذا وضعت على الطفل اللحاف الثقيل ومات بسبب ذلك؛ فإن هذا قتل، لكنه قتل خطأ لجهلها، فعليها الدية والكفارة، الدية إذا سمح عنها أبوه والورثة؛ فلا بأس. \n\nوأما الكفارة فعليها عتق رقبة مؤمنة، عبد أو أمة، فإن عجزت؛ تصوم شهرين متتابعين، ستين يومًا عن هذه المصيبة التي وقعت منها، نسأل الله أن يعينها، وأن يغفر لنا ولها وللمسلمين.\n\nالسؤال: الأم ما تحجب الورثة؟\n\nالجواب: على كل حال إذا كان أبوه موجودًا فهو الذي يرث، وإن كان له جدة ترث؛ لأن الأم لا ترث؛ لأنها قاتلة، وإن كان ما له أحد إلا بني عم، أو عصبة هم الورثة.","link":"https://binbaz.org.sa/fatwas/3343/غطت-ولدها-بلحاف-فمات-هل-عليها-الدية-والكفارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1664.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":7309,"question":"ما حكم إسقاط الحمل في الشهر الثاني؟","title":"حكم إسقاط الحمل في الشهر الثاني فأكثر","answer":"الجواب: لا ينبغي اشتراط ذلك إلا من علة شرعية، أما في الأربعين الأولى فكثير من أهل العلم يتسامح في ذلك إذا كان لمصلحة، ما دام في الأربعين الأولى نطفة، أما إذا انتقل إلى الأربعين الثانية، إلى العلقة والمضغة؛ فالصواب أنه لا يجوز إلا من علة شرعية يخشى منها على الأم.","link":"https://binbaz.org.sa/fatwas/3382/حكم-اسقاط-الحمل-في-الشهر-الثاني-فاكثر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1699.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":7315,"question":"ما حكم إسقاط الحمل في الشهر الثاني؟","title":"حكم إسقاط الحمل في الشهر الثاني فأكثر","answer":"الجواب: لا ينبغي اشتراط ذلك إلا من علة شرعية، أما في الأربعين الأولى فكثير من أهل العلم يتسامح في ذلك إذا كان لمصلحة، ما دام في الأربعين الأولى نطفة، أما إذا انتقل إلى الأربعين الثانية، إلى العلقة والمضغة؛ فالصواب أنه لا يجوز إلا من علة شرعية يخشى منها على الأم.","link":"https://binbaz.org.sa/fatwas/3382/حكم-اسقاط-الحمل-في-الشهر-الثاني-فاكثر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1699.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":7342,"question":"لي أخت ذهبت ذات يوم إلى المستشفى، وعند رجوعها من المستشفى رجعت وهي في عجلة من نفسها، فوضعت العلاج في مكان غير آمن، وكان لديها بنت صغيرة، فأكلت ذلك العلاج حتى أدى ذلك إلى وفاة البنت الصغيرة، نرجو من سماحتكم أن تقنعوها بما يرضي نفسها بحيث أنها تقول: قد اقترفت ذنبًا، أفتوني هل يعود عليها أي نوع من أنواع الحدود التي فرضها الله  أو كفارة ذلك الذنب الذي غير قصد منها وإلى آخره؟","title":"حكم الأم إذا كانت سبباً في قتل طفلها دون قصد","answer":"الجواب: نرجو ألا يكون عليها إثم؛ لأنها لم تتعمد قتلها، ولم تتعمد التسبب في ذلك، وإنما غفلت ونسيت الخطر، فجعلته في مكان غير مناسب في متناول الصبية والصبي الصغير، والذي يظهر من هذا أن عليها الدية والكفارة؛ لأنها مفرطة، جعلته في مكان قريب من الصغار الذين لا يعقلون، فالواجب عليها أن يكون في محل مرتفع، في محل بعيد عن متناول الصغار. أما الإثم فنرجو ألا يكون عليها إثم؛ لأنها لم تتعمد الشر، وإنما غفلت، أو نسيت، فجعلته في محل غير مناسب، ولكن عليها الدية والكفارة إلا إذا سمح الورثة عن الدية فلا بأس، أما الكفارة فهي عتق رقبة مؤمنة، فإن لم تجد؛ صامت شهرين متتابعين.","link":"https://binbaz.org.sa/fatwas/3426/حكم-الام-اذا-كانت-سببا-في-قتل-طفلها-دون-قصد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1735.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":7401,"question":"لقد كانت زوجتي حاملًا في شهرها الأخير، وفي إحدى الليالي حصل بيني وبين زوجتي خلاف وجدل في الكلام، ونتيجة ذلك أنها نامت على بطنها، في صباح اليوم التالي، كان لي موعد مع الدكتور، فأخبرني بموت الجنين علمًا بأن قصد زوجتي كان العناد فقط، ولم تكن تقصد موت الجنين، مع عدم علمي هل الجنين مات بسبب هذه الحركة، أم مات قبل ذلك؟","title":"موت الجنين بسبب نوم الأم على بطنها","answer":"الجواب: إذا قرر الطبيب المختص أن موت الجنين بسبب عنادها ونومها على بطنها؛ فعليها الدية، وعليها الكفارة؛ لأنها قاتلة، فعليها الدية وعليها الكفارة بما فعلت؛ لأنها متسببة في موته، أما إذا كان موته بأسباب أخرى؛ فلا حرج عليكما جميعًا، والواجب عليها السمع والطاعة لزوجها في المعروف، وعدم العناد، هذا الواجب على النساء السمع والطاعة في المعروف وعدم العناد، إلا إذا أمرها بمعصية فلا، إذا أمرها بالكشف لإخوانه، بعض الأزواج يقول اكشفي لإخواني ولأعمامي، لا تستري عنهم عنده دياثة، وعدم غيرة - نسأل الله العافية- هذا ليس لها طاعته في ذلك.  وهكذا إذا أمرها بالتبرج في الأسواق، أو عند الأجانب، كل هذا لا طاعة له، لا يجوز أن يطاع في ذلك، أو أمرها بشرب المسكر، أو بالعقوق لوالديها ليس له طاعة في ذلك -نسأل الله السلامة-.","link":"https://binbaz.org.sa/fatwas/3497/موت-الجنين-بسبب-نوم-الام-على-بطنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1801.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":7440,"question":"لقد عرفنا أن مهربي المخدرات يقتل، فنرجو من فضيلة الشيخ الدليل القاطع على هذا؛ ليكون حجة للدعاة إلى الله؟","title":"الدليل على قتل مهربي المخدرات","answer":"الجواب: قد قرر هيئة كبار العلماء حين درسوا أحكام المخدرات، وما حصل بها من الشر العظيم على المسلمين، والفساد الكبير، وضياع الكثير من الشباب وغيرهم بسبب تعاطيهم هذه المخدرات، وإصرارهم عليها، وإدامتهم لها، ونظروا في كلام أهل العلم، وتقرر من ذلك: أن الذي يهربها من هنا إلى هنا؛ يجب أن يقتل؛ لفساده في الأرض؛ لأنه من باب الفساد في الأرض، ولأنه أيضًا أشد من المحاربة، إذا كان المحارب الذي يأخذ أموال الناس في الطرقات يقتل، فهذا الذي يفسد عقول الناس أولى بالقتل.  أما الذي يروجها بالبيع والشراء؛ فهذا يؤدب، ويعزر بما يراه ولي الأمر من سجن وأدب، فإن ارتدع، وإلا وجب قتله؛ لأن قتله فيه حفظ لعقول المسلمين، وحفظ لحياتهم، فكان من رحمة الله للعباد: أن شرع التعزير بالقتل؛ لما لا يردعه الأدب بالجلد، والسجن، ونحو ذلك.  وهذا وجه ما صدر من الحكم في ذلك؛ لأنه من الفساد في الأرض؛ ولأنه أشد من المحاربة التي هي أخذ الأموال بغير حق، في الطرقات، وفي نحوها في البلاد بالقوة، فإذا كان الذي يأخذ أموال الناس، أو يخيف الطرق يقتل أو يصلب أو تقطع يده ورجله، فالذي يفسد عقول الناس، ويهرب ما يضر عقولهم، ويفسد عليهم دينهم ودنياهم أولى بهذه العقوبة -نسأل الله العافية-.","link":"https://binbaz.org.sa/fatwas/3538/الدليل-على-قتل-مهربي-المخدرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1843.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":7570,"question":"هذه الرسالة وردت من المرسلة من الطائف الحوية، تقول: أنا المرسلة (ن. س. المطيري )، السلام عليكم ورحمة الله وبركاته، وبعد: أفيدكم أنني امرأة ربة بيت، وقد رزقت مولود بقي على قيد الحياة قرابة أربعين يوماً، وفي ذات يوم نمت قبيل العصر والمولود بخير واستيقظت من المنام صلاة العصر وإذا بالمولود ميت على الفراش، لذا خشيت أنني انقلبت عليه أثناء النوم، فهل علي شيء في ذلك، أفيدوني جزاكم الله خيراً، علماً أنني لا أعلم له سبب إلا إذا كان لحقه مني شيء وأنا نائمة؟","title":"حكم الأم إذا شكت بكونها سبباً في قتل طفلها","answer":"الجواب: إذا كنت أيها السائلة لا تعلمين أنه جرى منك شيء فليس عليك شيء، والموت قد يأتي بغتة لأسباب يجهلها الإنسان، فإذا كنت لا تعلمين أنك انقلبتي عليه، أو فعلت شيئاً يكون سبباً لموته فليس عليك دية ولا كفارة، والأصل براءة الذمة من الديات والكفارات إلا بأمر واضح يوجب ذلك، والآجال بيد الله ولها أسباب قد تخفى على الناس، فلا يلزمك دية ولا كفارة إلا بعد العلم بأن موته بأسبابك، والله  أعلم، نسأل الله أن يجعله شافعاً مشفعاً. نعم.","link":"https://binbaz.org.sa/fatwas/4576/حكم-الام-اذا-شكت-بكونها-سببا-في-قتل-طفلها ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_016/01606.mp3","categories":["مسائل متفرقة في الجنائز","الجنايات والحدود"]},{"id":7761,"question":"هذه الرسالة وردتنا من السودان يقول: من أخيكم في الدين العبيد محمد السودان مديرية الجزيرة، يقول: أتقدم لإخواني في الدين وإخواني مقدمي برنامج نور على الدرب، وأرجو عرض طلب هذا الحكم على الشيخ الذي يجيب على أسئلة المستمعين، يقول: ما الحكم الشرعي للشخص الذي يرتكب جريمة سب الدين وهو متزوج، فإن كنت حوله أو قريباً منه فما الواجب الذي أقوم به نحو هذا الشخص، وشكري لكم؟","title":"واجب المسلمين تجاه من يسب الدين","answer":"الجواب: سب الدين من أعظم الجرائم في الإسلام، وهو من الجرائم الكفرية ومن نواقض الإسلام ومن أنواع الردة عن الإسلام، فالذي يسب الدين أو يسب الله أو يسب الرسول عليه الصلاة والسلام هذا قد أتى كفراً عظيماً وردة عن الإسلام، والواجب على من سمعه أو كان يعلم ذلك منه أن ينكر عليه وأن يعلمه أن هذا ناقض من نواقض الإسلام وكفر بواح، فعليه أن يبادر بالتوبة لعل الله يتوب عليه.\nوأما حكمه في الدنيا بالنسبة إلى ولاة الأمور فالواجب عليهم استتابته، فإن تاب فالحمد لله وإلا وجب أن يقتل، وقال جمع من أهل العلم: لا يستتاب بل يقتل حداً كافراً، فإن تاب فيما بينه وبين الله تاب الله عليه، ولكن يجب أن يقتل ردعاً له ولأمثاله عن سب الله ورسوله وعن سب دين الله.\nوالقولان معروفان لأهل العلم، وبالنظر إلى حالة الناس اليوم وكثرة الجهل واختلاطهم بالمشركين والكفار وضعفاء البصيرة يتضح له أن هذا الشيء قد يكثر في هذا الزمان؛ لكثرة مخالطة الكفرة، ولكثرة الجهل وغلبته على الناس ولضعف الدين والإيمان في قلوب الكثير من الناس، فلهذا قد يقع منه هذا الشيء كثيراً، فالواجب أن يردع عن هذا الشيء بغاية من التأديب الذي يردع الناس عن هذا ثم يستتاب لعله يندم على ما فعل، ولكن لابد من التعزير.. لابد من الأدب عما أقدم عليه ثم استتابته بعد ذلك، فيستتاب فإن تاب الحمد لله مع التعزير والتأديب حتى لا يعود لمثل هذا، وإن لم يتب قتل كفراً وردة عن الإسلام.\nوالقول الثاني: لا يستتاب بل يقتل فوراً ولا يستتاب؛ لأن هذه جريمة عظيمة فلا يستتاب أهلها كما لا يستتاب الساحر على الصحيح، فهكذا من سب الله ورسوله أو سب دينه من باب أولى؛ لظهور كفره ولأنه هتك أمراً عظيماً وأتى جريمة عظمى في سب الدين وسب الله ورسوله.\nوبكل حال فالواجب أن يستتاب فإن تاب وندم وأقلع وأظهر الخير وأظهر العمل الصالح فالحمد لله وإلا قتل، ولكن التعزير لابد منه، لابد أن يعزر ويؤدب حتى لا يعود إلى مثل هذا ولو تاب، وإن قتل فوراً ولم يستتب فهو قول جيد وقول قوي ولا غبار عليه، ولكن الاستتابة لها وجهها، الله جل وعلا أمر باستتابة الكفار ودعوتهم إلى ذلك فإذا استتيب؛ لأن الجهل يغلب على الناس ويغلب عليهم أيضاً التساهل في هذه الأمور؛ بسبب الجلساء الضالين وبسبب غلبة الجهل وبسبب المخالطة الخبيثة للكفرة والمجرمين فإذا استتيب وتاب توبة صادقة وأظهر الخير فالحمد لله، وإلا أمكن قتله إذا عاد إلى مثل هذا ولم يتأثر بالاستتابة ولا بالتعزير الذي فعل معه من ولاة الأمور. نعم.\nوالله المستعان، لا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/4957/واجب-المسلمين-تجاه-من-يسب-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_044/04404.mp3","categories":["الجنايات والحدود","نواقض الإسلام"]},{"id":7951,"question":"أيضاً يقول: عندنا أو يقول: في بلدنا في اليمن لقد كثر قذف النساء في بلدنا ولم يبق منهن امرأة إلا ما شاء الله إلا قذفت بالزنا، وإن أراد أحد الرجال أن يأتي بالشهود الذين ذكرهم الله في القرآن لم يستطع، ولم استطعنا أن نكف ألسنة الناس وبهذا أصبحت حياة الرجال مع النساء في شكوك وأمراض وتربص، فما الخلاص من ذلك، أفتونا جزاكم الله عنا خير الجزاء ووفقكم وحفظكم الله؟","title":"كيفية الخلاص من ظاهرة قذف المؤمنات بغير حق","answer":"الجواب: الخلاص من ذلك إقامة الحد الشرعي، من قذف امرأة يقام عليه الحد الشرعي وهو أن يجلد ثمانين جلدة كما أمر الله سبحانه وتعالى إلا أن يأتي بأربعة شهداء عدول على ما قال، فإذا قال: (إنها زانية) ولم يأت بأربعة شهداء فإن لها أن تطالب ووليها أن يطالب بإقامة البينة وإلا حد في ظهره؛ لأن الله سبحانه وتعالى قال: وَالَّذِينَ يَرْمُونَ الْمُحْصَنَاتِ ثُمَّ لَمْ يَأْتُوا بِأَرْبَعَةِ شُهَدَاءَ فَاجْلِدُوهُمْ ثَمَانِينَ جَلْدَةً [النور:4].\nفالحاصل: أن الواجب على المرأة ووليها التحرز من ذلك وألا يتساهلوا في هذه الأشياء فمن قذف يطالب بالبينة، فإن أحضر البينة وهي أربعة شهود عدول على ما قال من كونها زانية برئت ساحته وأقيم عليها الحد هي على زناها، أما إذا لم يحضر أربعة شهود فإنه يقام عليه الحد، يجلد ثمانين جلدة لقذفه المحصنة، إذا كانت محصنة عفيفة معروفة بالخير والاستقامة فإنه يجلد ثمانين جلدة، والله المستعان. نعم.\nالمقدم: إذاً: لابد من إقامة الحد، إما أن ترتدع المرأة أو يرتدع القاذف.\nالشيخ: إما أن يثبت الحق عليها فيقام عليها الحد بأربعة شهود، وإما أن لا يحصل الشهود هو، فيقام عليه الحد بثمانين جلدة؛ لقذفه لها إذا كانت محصنة، أما إذا كانت غير محصنة، يعني: تتهم يعزر يضرب تعزيراً؛ لأن القذف لا يجوز إلا ببينة، فإن كانت محصنة معروفة بالاستقامة والعفة ليس فيها مطعن فإنه يقام عليه الحد ثمانين جلدة، أما إذا كانت غير محصنة بل معروفة يعني بالتساهل بالأمور والتهمة، ولا يحكم عليها بأنها محصنة، ما ثبت عند القاضي أنها محصنة فإنها تعزر يعني: تجلد ما يراه القاضي أربعين جلدة ثلاثين جلدة عشرين جلدة ما يرى القاضي تعزيراً لها، يجلد القاذف الغير محصن يجلد ما يراه القاضي تعزيراً له وكفاً للسانه عن التعرض للمسلمين. نعم.","link":"https://binbaz.org.sa/fatwas/5475/كيفية-الخلاص-من-ظاهرة-قذف-المومنات-بغير-حق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_068/06806.mp3","categories":["مسائل متفرقة في الجنائز","الجنايات والحدود"]},{"id":8052,"question":"هذه أولاً: رسالة المستمعة أو المرسلة (ل. ع. م) من مدينة الزلفي، في الحي الجنوبي، ورسالتها حول العوار، تقول في رسالتها: أبلغ من العمر عشرين عاماً، أتاني العوار فسقط الجنين السنة الماضية، وهذه السنة هل علي كفارة أم لا، أفيدونا ولكم جزيل الشكر؟","title":"حكم كفارة من أسقطت جنينها بسبب العوار","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nالسائلة لم توضح المراد بالكفارة، وعن أسباب الكفارة ما هي، هل أنت أيها السائلة لم تصومي في رمضان الماضي، وتسألين عن الكفارة في ترك الصيام، لأجل أنك أخرت القضاء إلى بعد رمضان الثاني، أم أردت شيئاً آخر، وهو أنك لما سقط العوار صمت، ولم تتركي الصوم؛ لأن الدم ليس دم نفاس، ما ندري ماذا أردت، فالذي نرى أن تعيدي السؤال مفصلاً واضحاً، هذا الذي نرى أن تعيدي السؤال موضحاً تبينين فيه مرادك بياناً واضحاً، حتى يكون الجواب على ضوء ذلك.\nالمقدم: يعني: هل هي السبب في إسقاط الجنين أم ... ؟\nالشيخ: تبين مرادها، عليها أن تبين مرادها في هذا السؤال. نعم.","link":"https://binbaz.org.sa/fatwas/5848/حكم-كفارة-من-اسقطت-جنينها-بسبب-العوار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_082/08201.mp3","categories":["الجنايات والحدود"]},{"id":8108,"question":"تحرير الرقبة سماحة الشيخ أصبح مكان إشكال لبعض السادة المستمعين فهم لا يعلمون معناه ربما لأنهم لم يروا ذلك على الطبيعة، أخونا مثلاً يسأل ويقول: أسأل عن تحرير الرقبة حيث أننا نسمع كثيراً من الكفارات تقول: تحرير رقبة ولا ندري ما هي الرقبة، هل هو إنسان محكوم عليه بالقتل ثم يعفى عنه أو أنه من الحيوانات، أفيدونا أفادكم الله؟","title":"معنى تحرير رقبة","answer":"الجواب: تحرير الرقبة يراد به: عتق المملوك من الذكور والإناث، وقد شرع الله سبحانه وتعالى لعباده إذا جاهدوا أعداء الإسلام وغلبوهم أن تكون ذرياتهم ونساؤهم أرقاء مماليك للمسلمين يستخدمونهم وينتفعون بهم ويبيعونهم ويتصرفون فيهم، وكذلك الأسرى إذا أسروا منهم أسرى فولي الأمر بالخيار إن شاء قتل الأسرى، وإن شاء أعتق الأسرى إذا رأى المصلحة في ذلك وأطلقهم، وإن شاء استرقهم وجعلهم غنيمة، وإن شاء قتلهم إذا رأى المصلحة في القتل، وإن شاء فادى بهم إذا كان عند الكفار أسرى للمسلمين يفادي بذلك، فيأخذ من المشركين أسرى من المسلمين ويعطيهم أسرى، أو يأخذ منهم أموالاً لفك أسراهم كما فعل النبي ﷺيوم بدر، فقد كان عند النبي ﷺ أسرى قتل بعضهم وفادى ببعضهم، وكان من جملتهم النضر بن الحارث و عقبة بن أبي معيط فقتلهما بعد انتهاء الوقعة، والبقية فادى بهم وأمر المسلمين أن يفادوا بهم ويأخذوا الفداء من المشركين في مقابل أسراهم.\nومنهم من عفا عنه عليه الصلاة والسلام، فالعفو جائز لولي الأمر إذا رأى المصلحة وجائز له القتل إذا رأى المصلحة، وجائز له الاسترقاق إذا رأى المصلحة، وجائز له أخذ الفداء، كما قال عز وجل: فَإِمَّا مَنًّا بَعْدُ وَإِمَّا فِدَاءً حَتَّى تَضَعَ الْحَرْبُ أَوْزَارَهَا [محمد:4].\nفهذه هي الرقاب: المملوك الذي يملكه المسلمون عند غلبتهم لعدوهم وقهرهم لعدوهم الكافر فيأخذوا منه ذرية، يعني:صبية صغاراً لم يبلغوا يأخذونهم أو نساء، فهؤلاء يكونون أرقاء للمسلمين مماليك للمسلمين يقسمون في الغنيمة يقسمون بين الغانمين كل يأتيه نصيبه من هؤلاء الذرية وهؤلاء النساء، وهكذا الأسرى الكبار المقاتلون إذا استرقهم ولي الأمر وجعلهم غنيمة كذلك. فإذا كان عند المسلم الغانم واحد أو اثنان أو ثلاثة فهو بعد ذلك بالخيار، إن شاء استخدمه في حاجاته، وإن شاء باعه وانتفع بثمنه، وإن شاء أعتقه لله عز وجل تبرعاً وتطوعاً، أو أعتقه في الكفارة مثل كفارة القتل.. كفارة الوطء في رمضان.. كفارة الظهار.. كفارة اليمين، وإن تركه يستعمله صار مملوكاً له يورث بعده إذا مات كسائر أمواله.\nهذا معنى تحرير رقبة، يعني: عتق الرقبة التي ملكتها أيها المسلم ملكتها بالحرب التي جرت بينك وبين عدوك حتى صار أولادهم ونساؤهم لكم غنيمة فتقسمها المسلمون وصارت بينهم وصار لكل مسلم نصيبه من هذه الغنيمة مملوكاً له يتصرف فيه بالبيع وغيره، فإذا أعتقه لله تطوعاً أو عن كفارة فله أجره في ذلك، وبهذا تؤدى الكفارة ويسمى العتق تحرير، يسمى عتقه تحرير رقبة، فإذا قال: أعتقت فلاناً لله، فهذا معناه تحرير رقبة سواء كان عن كفارة أو تطوعاً وتبرعاً، يقول النبي ﷺ: أي امرء مسلم أعتق امرءاً مسلماً أعتق الله بكل عضو منه عضواً من النار فعتق الرقاب له شأن عظيم وفضل كبير في الشرع المطهر، ولعلك -أيها السائل- بهذا عرفت معنى عتق الرقبة وتحريرها.","link":"https://binbaz.org.sa/fatwas/5904/معنى-تحرير-رقبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_102/10203.mp3","categories":["الجماع في نهار رمضان","الأيمان والنذور","الجنايات والحدود"]},{"id":8114,"question":"رسالة وصلت إلينا من المستمعة حنان غالب من العراق بغداد أختنا تقول أسأل عن حادث مررت به قبل سنة ونصف وأكاد أموت من الخوف وعقاب الله سبحانه أرجو إفتائي هل أنا مذنبة حقاً أفيدوني أفادكم الله وبارك سعيكم، الحادث هو:الشيخ: أعد.المقدم: تقول: تسأل عن حادث مر به قبل سنة ونصف وتكاد تموت من الخوف من الله سبحانه وتعالى وتسأل هل هي مذنبة حقاً وترجو الإفادة، ثم تذكر الحادث على النحو التالي: تقول: كنت أحب والدي ولكن أصبح بيني وبينه ظروف عائلية، ورغم الظروف فأنا أحبه ويحبني ولكن الظروف جعلتني ووالدي دائماً على خلاف مستمر يومياً وذات يوم مرض والدي ودخل المستشفى، وبعد خروجه منه أخبر الطبيب أمي بأنه لا يطلع على أي مشكلة، لأنها تؤثر على شعوره ويموت؛ لأنه لا يتحمل أي صدمة، ومرت ثلاثة أشهر على خروجه وأمي لم تخبرنا بذلك، فصادفت مشكلة بيني وبينه جعلته ينزعج مني وحدث له صدمة في نفس اليوم من بعض المشاكل الأخرى ثم أدخل المستشفى وكانت وفاته، والآن أسأل هل أنا المتسببة في ذلك؟ أفيدوني وماذا يلزمني شرعاً جزاكم الله خيرا؟","title":"حكم من حصل بينه وبين والده المريض مشكلة أدت لوفاته","answer":"الجواب: لا يلزمك شيء؛ لأنك لم تتعمدي إيذاءه ولم تعلمي بالمشاكل التي نصح بأن لا يعرض لها فأنت إن شاء الله لا حرج عليك، والمشاكل تقع بين الناس دائماً ولا يمكن التحرز منها، فأنت في هذا مثل غيرك من الناس لا شيء عليك إن شاء الله ولا يكون عليك في هذا لا دية ولا كفارة؛ لأن هذه أمور عادية بين الناس تقع بين الولد ووالده، وبين الأخ وأخيه، وبين الرجل وزوجته فلا يكون في هذا شيء إن شاء الله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/5910/حكم-من-حصل-بينه-وبين-والده-المريض-مشكلة-ادت-لوفاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_102/10206.mp3","categories":["الجنايات والحدود"]},{"id":8181,"question":"الرسالة التالية باعثها أخ من الدمام يقول (ق. ع. م): شاءت مشيئة الله تعالى أن أتعرض لحادثة بسيارتي راح ضحيتها اثنان من الركاب الذين كانوا معي بالسيارة واتضح أن السيارة التي داهمتنا هي التي وقع منها الخطأ سؤالي: هل علي كفارة من صيام أو صدقة؟ لأن المتوفين كانوا معي بالسيارة علماً بأنني كما ذكرت لم يكن الحادث نتيجة خطأ مني وكل ذنبي أن المتوفيين كانوا معي بالسيارة فإذا كانت علي صدقة! أرجو التكرم بتوضيحها من حيث مقدارها وكيفيتها لأنني أحس بتأنيب الضمير وأريد منكم الإجابة حتى أكون على بينة من الأمر ولسماحتكم الشكر بعد الله سبحانه وتعالى وجزاكم الله خير الجزاء عن أمة الإسلام؟","title":"وقع عليه حادث أدى إلى وفاة بعض الركاب، فهل عليه كفارة؟","answer":"الجواب: أولاً: قول السائل شاءت مشيئة الله ليس بسديد والصواب أن يقال: شاء الله سبحانه بعض الناس يقول شاءت الأقدار، شاء القدر، شاءت إرادة الله، كل هذا التعبير ليس بجيد والواجب أن تنسب الأمور في مثل هذا إلى الله سبحانه فيقول: شاء الله جل وعلا أو اقتضت حكمة الله جل وعلا كذا وكذا.\nأو قدر الله علي كذا وكذا أما ما يتعلق بسؤالك فإنه لا شيء عليك ما دام الخطأ من غيرك وأنت مظلوم فالكفارة والدية على الذي أخطأ عليك ما دمت لزمت الطريق المعروف النظامي ولم تسرع وإنما أخطأ عليك من صدمك فالإثم عليه والكفارة عليه والدية عليه أما أنت فليس عليك شيء إذا كنت إذا كان الأمر كما قلت. والله ولي التوفيق.\nالمقدم: جزاكم الله خيراً. تقرير المرور سماحة الشيخ هل يعتبر في مثل هذه المواقف؟\nالشيخ: يعتبر نعم لأنه مسئولون وليس هناك طريق آخر فهم الذين يعتمد عليهم في هذا. نعم.","link":"https://binbaz.org.sa/fatwas/5988/وقع-عليه-حادث-ادى-الى-وفاة-بعض-الركاب-فهل-عليه-كفارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_105/10509.mp3","categories":["الجنايات والحدود"]},{"id":8559,"question":"هذه رسالة وردتنا من السائل (علي . ع. م) من الزلفي، يقول في رسالته: ذهب رجل ذات يوم إلى مزرعته ومعه ابناه، فلما وصلا إلى المزرعة قال لهم: انزلوا من السيارة وابتعدوا، فنزلوا فابتعد أحدهم وأما الآخر فلم يبتعد فظن الأب أنهم قد ابتعدوا عن السيارة فحركها إلى الخلف فدهس واحداً منهم الذي لم يبتعد وهو لم يعلم فمات الولد، وكان عمره ست سنوات تقريباً، فالسؤال هل يلزم أباه وأمه الكفارة جميعاً أم تلزم الأب فقط، وما هي الكفارة بارك الله فيكم؟","title":"ما يلزم من قتل ابنه خطأ","answer":"الجواب: الواجب في هذا الدية والكفارة، تلزم الأب الدية لأمه ولإخوته، أما الأب فلا ... منها إلا أن يسمحوا عنه، إذا سمحت الأم والإخوة فلا بأس، وعليه كفارة أيضاً وهي عتق عبد أو عبدة، يعني: عتق عبد مؤمن أو أمة مؤمنة، وهذا يوجد في بعض أفريقيا كمورتيانيا يوجد عبيد يباعون بثمن مناسب، فإن كان لا يستطيع وجب عليه الصوم شهرين متتابعين، يصوم شهرين متتابعين كما أمر الله به سبحانه وتعالى؛ لأن هذا يسمى قتل الخطأ ما تعمده، وقتل الخطأ فيه الكفارة والدية. نعم.\nالمقدم: الدية تكون للأم وللإخوة؟\nالشيخ: للأم وللإخوة إن كان له إخوة نعم.\nالمقدم: أما الأم في هذه الحال ليس عليها شيء؛ لأنها..؟\nالشيخ: ... السائق هو القاتل، القاتل هو الأب.\nالمقدم: جزاكم الله خير وبارك الله فيكم وبالنسبة للكفارة ليس فيها إطعام لأن كثير من الناس ... ؟\nالشيخ: ما فيها إطعام ليس فيها إلا.. إما العتق مع القدرة، فإن عجز فالصوم. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6632/ما-يلزم-من-قتل-ابنه-خطا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_206/20605.mp3","categories":["الجنايات والحدود"]},{"id":8959,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات من مكة المكرمة تقول: (ن. ض) السبيعي من مكة أختنا تقول: إنني كنت حاملًا في الشهر الرابع ولدي أبناء كبار ولكن لم يكونوا يعلمون بأنني حامل، فقام ابني الكبير بقصد أنه يمزح فوضع يده على بطني وقال لي: أخاف أن يكون في بطنك هذا طفل، علمًا بأنه على وشك زواج ولا يريد أن أمه تكون حاملًا في زواجه على أساس المباشرة بأنها لا تستطيع أن تباشر في زواجه، وعندما وضع يده على بطن أمه آلمها وفوجئ بأن أمه تنومت في المستشفى واتضح أن الجنين قد توفي في بطن أمه، و تسأل عن الحكم؟","title":"حكم التسبب في قتل الجنين بغير قصد","answer":"الجواب: إذا كان وضعه يده على بطن أمه أثر على الجنين؛ لأنه ضربه ضربةً أثرت عليه؛ لأنه ليس بوضع بل ضربه ضربةً أثرت حتى سقط بسبب ذلك فإن عليه عن ذلك الدية، وهي غرة عبد أو أمة، وهي عشر دية أمه، يعني: خمس من الإبل، فإن دية المرأة خمسون من الإبل، نصف دية الرجل مائة من الإبل، والنظر إلى القيمة وهي الآن مائة ألف يكون عليه عشر قيمة الأم؛ خمسة آلاف للورثة إذا لم يسمحوا، لأمه وأبيه إذا لم يسمحا عن القيمة، وعليه كفارة عن سقوط الجنين إذا كان الجنين قد نفخت فيه الروح، لأنه قد نفخت فيه الروح فعليه كفارة عن ذلك أيضًا بعتق رقبة مؤمنة، وإن عجز صام شهرين متتابعين؛ لأنه قتل، هذا يسمى قتل شبه العمد.\nفأما إن كان ما بعد تخلق إنما هو دون الأربعة الأشهر فهذا ليس عليه كفارة وإنما عليه الغرة عبد أو أمة. نعم.\nالمقدم: جزاكم الله خيرًا، هي تقول: إنه في الشهر الرابع؟\nالشيخ: في الشهر الرابع ما بعد نفخت فيه الروح، لا يكون عليه كفارة إنما عليه غرة عبد أو أمة إذا كانا لم يسمحا والداه، إذا كانا والداه لم يسمحا. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7117/حكم-التسبب-في-قتل-الجنين-بغير-قصد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_173/17307.mp3","categories":["الجنايات والحدود"]},{"id":8961,"question":"تقول: كان لي طفل يبلغ أربعين يومًا وكان موجودًا بين يدي على الأرض وله أخ أكبر منه يبلغ سنة واحدة، فبينما هو يمشي وقع على أخيه، وأخذ أخوه الصغير أسبوع ثم وافته منيته، فماذا عليه لو تكرمتم؟","title":"عدم وجوب الكفارة على غير المكلف في قتل الخطأ","answer":"الجواب: ليس عليه شيء؛ لأنه غير مكلف مادام صغير، ليس عليه كفارة ولكن الدية تكون على العاقلة إذا ثبت أنه مات بأسبابه على العاقلة وهم العصبة الأغنياء عليهم على قدر غناهم وسعتهم يوزعها القاضي، تعرض على المحكمة والمحكمة تنظر في الأمر إذا طالب الورثة ذلك، إذا طالب الورثة الدية من العاقلة، وإن سمحوا فلا حاجة إلى شيء.","link":"https://binbaz.org.sa/fatwas/7119/عدم-وجوب-الكفارة-على-غير-المكلف-في-قتل-الخطا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_173/17308.mp3","categories":["الجنايات والحدود"]},{"id":9196,"question":"بسم الله الرحمن الرحيم، سماحة الوالد الشيخ عبدالعزيز بن باز، السلام عليكم ورحمة الله وبركاته، أبعث إليكم بهذه الرسالة بعد أن هداني الله سبحانه وتعالى، وإني أتألم مما جنت يداي قبل أن يهديني الله، فلقد امتدت يدي كثيراً على أشياء لا تخصني، وكانت بطبيعة الحال حرامًا علي، ولقد علمت أن كفارة ذلك أن أتصدق وأن يكون أجر الصدقة لصاحب الحق في حالة إذا لم أجده وأعطيه ما أخذت منه، و كيف تكون الصدقة من ناحية الدفع، هل تكون لمسكين واحد أو هل تجوز أن تكون للمجاهدين الأفغان، وفي حالة معرفتي لمن سرقت منه وأريد أن أرجع له حقه هل يصح أن أرجعها دون أن يعلم بأنني أنا الذي سرقت منه كإرسالها بالبريد مثلًا جزاكم الله خيرًا؟ وأفتوني في أمري فإنني في تأنيب ضمير شديد، أسأل الله أن لا يزيغ قلوبنا بعد إذ هدانا إنه ولي ذلك والقادر عليه ولا حول ولا قوة إلا بالله.","title":"كيفية أداء السارق لحقوق الآدميين بعد توبته","answer":"","link":"https://binbaz.org.sa/fatwas/7358/كيفية-اداء-السارق-لحقوق-الادميين-بعد-توبته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_151/15107.mp3","categories":["الجنايات والحدود"]},{"id":9236,"question":"أيضاً له سؤال ثالث وأخير يقول: هل قتل الشخص الذي تفعل به الفاحشة مني أو من غيري وقتل نفسي آخذ عليه ثواب؟","title":"حكم قتل من يفعل فعل قوم لوط.","answer":"الجواب: بل منكر قتلك إياه وقتلك نفسك منكر آخر، فاللواط والزنا منكر، وإذا قتل اللائط الملوط به أو المزني بها، صار فعل منكراً آخر، جريمةً عظمى أشد من الزنا وأشد من اللواط، القتل أشد نسأل الله العافية، جريمة عظمى، هي دون الشرك وليس بعد الشرك أعظم من القتل نسأل الله العافية، فإذا قتل الملوط به لئلا يخبر عنه أو لأسباب أخرى، أو قتل من زني بها صار قد جمع بين كبيرتين ومنكرين عظيمين، الثاني أعظم من الأول، فالقتل أعظم من الزنا وأعظم من اللواط، فالواجب الحذر من ذلك، وأن لا يجمع بين الشرين نعوذ بالله من ذلك. نعم.\nالمقدم: هو يقول: وقتل نفسي، يظن أنه يريد التطهير؟\nالشيخ: كذلك قتل نفسه لا يجوز، هذا انتحار ومنكر، ولا يكون تطهيراً بل يكون توسيخاً، وزيادةً في النجاسة والنكارة، فليس لك قتل نفسك بسبب المعصية، بل عليك التوبة إلى الله ولا تقتل نفسك، الله يقول جل وعلا: وَلا تَقْتُلُوا أَنفُسَكُمْ [النساء:29]، والنبي ﷺ يقول: من قتل نفسه بشيء عذب به يوم القيامة، لكن إن تقدمت إلى ولي الأمر وطلبت إقامة الحد عليك فلا بأس، ولكن الأفضل لك أن تستتر بستر الله، وأن لا تبوح بهذا العمل، وأن لا تفضح نفسك، وأن تتوب إلى الله توبةً صادقة بينك وبين الله ، والله يتوب على التائبين إذا صدقوا وتابوا توبةً نصوحاً. نعم.\nالمقدم: نفهم من هذا يا سماحة الشيخ أنه ليس من حق الشخص أن يقيم الحد على نفسه ولا على غيره؟\nالشيخ: لا، ليس له أن يقيم الحد على نفسه ولا على غيره، الحد إلى ولاة الأمور. نعم.\nالمقدم: جزاكم الله خير وبارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7399/حكم-قتل-من-يفعل-فعل-قوم-لوط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_234/23409.mp3","categories":["الجنايات والحدود"]},{"id":9324,"question":"وهذه رسالة وردت إلينا أيضا من سائل رمز لاسمه بـ (ف. ص) يماني الجنسية يسكن بالرياض يقول: سرقت ماتوراً من شركة التي كنت أعمل فيها، لكنني الآن نادم على ما فعلت وهذا الأمر قد حصل قبل سنتين، وإرجاع الماتور من بلدي إلى هنا صعب أفيدوني ماذا أعمل جزاكم الله خيراً؟","title":"وجوب رد المسروق إلى أهله","answer":"الجواب: عليك أن ترد الماتور إلى أهله ولو كلفك كثيراً، أو تستسمحهم وتعطيهم قيمته، عليك أن ترد الماتور إلى الشركة أو تعطيها قيمته حسب الإمكان، إذا رضيت بالقيمة تعطيها القيمة، وإلا وجب عليك رده بنفسه، ولو كلفك أكثر من قيمته، فأنت الظالم فعليك أن ترده إلى أهله.\nفإن كان رده يترتب عليه مضار عليك وخطر عليك، فتصدق به، اعرف قيمته وتصدق به عمن هو له، عن صاحبه، أما إذا أمكن أن ترده إليهم بلا خطر عليك -يعني- كبير، فإنك ترده إليهم بالطريقة الممكنة إن استطعت ذلك، ولو لم تسم نفسك ترده وتقول: هذا أحضره إنسان يقول: إنه للشركة، أو ترسله مع أحد، وتقول: أعطه الشركة الفلانية وقل لها: هذا من إنسان يقول: إنه لها، وما أشبهه، بالطرق التي تستطيع إيصاله إليها، فإذا لم تستطع ذلك إلا بخطر عليك فتصدق به عن صاحبه، وتب إلى الله واستغفر الله ولا تعد إلى ذلك.\nالملقي: بارك الله فيكم، لكن الصعوبة لا تمنع، صعوبة رده؟\nالجواب: نعم، ولو تكلف؛ لأنه هو الظالم. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/7495/وجوب-رد-المسروق-الى-اهله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_237/23711.mp3","categories":["الجنايات والحدود"]},{"id":9401,"question":"سماحة الشيخ! ذكرتم أن القصاص كفارة هل هو كفارة في الدنيا والآخرة أيضًا؟","title":"الحدود كفارة لأصحابها","answer":"الجواب: نعم، لكن يبقى حق القتيل هذا لحق الله ولحق الورثة، أما حق القتيل فيبقى، وإذا كان القاتل تاب توبة صادقة فالله سبحانه يرضي عنه القتيل بما يشاء سبحانه.\nالمقدم: أما بقية المعاصي الأخرى، بقية المعاصي الأخرى فهي كفارة في الدنيا والآخرة القصاص؟\nالشيخ: مثل ما قال الرسول ﷺ: من أدركه الله في الدنيا كان كفارة له، ومن مات على ذلك مستورًا فأمره إلى الله إن شاء عفا عنه وإن شاء عاقبه سبحانه وتعالى.\nالمقدم: جزاكم الله خيرا، هذا يقع على كل المعاصي؟\nالشيخ: نعم، كل المعاصي التي أدرك حدها في الدنيا أو تاب منها في الدنيا تغفر له، أما من مات عليها لم يحد ولم يتب هذا أمره إلى الله؛ لقوله : إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48] سبحانه.\nالمقدم: بارك الله فيكم، الواقع هذه بشرى إلى أصحاب المعاصي الذين أدركتهم إقامة الحدود في الدنيا، وإذا علموا أن هذا كفارة لذنوبهم لعل الله سبحانه وتعالى أن يهديهم بعد هذا ولا يقترفوا المعاصي مرة أخرى؟\nالشيخ: نعم، مثل ما قال النبي ﷺ لما بايع الناس أن لا يشركوا ولا يسرقوا ولا يزنوا ولا يقتلوا، قال بعد هذا: فمن أدركه الله في الدنيا -يعني: بالحد ونحوه- كان كفارة له، ومن لم يقم عليه الحد في الدنيا -يعني: من لم يدرك في الدنيا- فأمره إلى الله سبحانه وتعالى إن شاء غفر له وإن شاء عاقبه سبحانه.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7566/الحدود-كفارة-لاصحابها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_188/18807.mp3","categories":["الجنايات والحدود"]},{"id":9452,"question":"وهذه رسالة وردت إلينا من السائل محمد إبراهيم إسماعيل مقيم في تثليث مصري الجنسية يقول: لي ابن عم توفي والده، فقام أبي بتربيته ولكن حصل بيني وبينه مناقشة في موضوع تطورت المناقشة بيني وبينه، كان في جيبي سكين ودون أن أشعر ضربته بها، وبعدها مباشرة توفي، لكنني لم أقصد قتله ولم يكن بيني وبينه بغضاء سابقة، لأننا نعيش في منزل واحد، ووالدي شهد بذلك أمام القاضي فحكم علي سبع سنوات سجن، لكنني أشعر أن هذا لا يكفي، فأنا قد تبت إلى الله وأريد الحكم الشرعي في هذا الموضوع؛ لأنني في أشد القلق بسبب خوفي من الله ، فدلوني على الخير بارك الله فيكم؟","title":"حكم من قتل دون قصد القتل","answer":"الجواب: هذه المسألة تتعلق بالقضاء والمحاكم، فإذا سمح عنك أولياء المقتول وأسقطوا عنك حقهم فلا بأس، وعليك التوبة إلى الله مما صدر منك، أما إذا طلبوا حقهم من القصاص أو الدية فهذا إلى المحاكم، تنظر المحكمة الشرعية في ذلك وفي ما تراه المحكمة على ضوء الأدلة الشرعية البركة والكفاية، وإن كنت تعلم أنك متعمد وأنك قاصد قتله، فقدم نفسك، قدم نفسك ولا يحتاج إلى المحكمة، قل لهم: أنا ظلمت نفسي وأنا أخطأت وأنا الذي فعلت المنكر وأنا قصدت قتله، فإذا سمحوا عنك فلا بأس، وإن قتلوك فلهم الحق في قتلك قصاصاً، وهم أولياء الدم ورثة القتيل، أما إذا كنت تزعم أن هذا جرى منك من غير قصد سقطت منك السكين، أو طعنته بالسكين وأنت في غير شعور، هذا شيء يرجع إلى القضاء، ينظر فيه القاضي وبعد النظر يتبين له إن شاء الله ما يجب عليك، الله المستعان. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7631/حكم-من-قتل-دون-قصد-القتل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_240/24008.mp3","categories":["الجنايات والحدود"]},{"id":9455,"question":"وهذه رسالة وردت إلينا من السائل محمد إبراهيم إسماعيل مقيم في تثليث مصري الجنسية يقول: لي ابن عم توفي والده، فقام أبي بتربيته ولكن حصل بيني وبينه مناقشة في موضوع تطورت المناقشة بيني وبينه، كان في جيبي سكين ودون أن أشعر ضربته بها، وبعدها مباشرة توفي، لكنني لم أقصد قتله ولم يكن بيني وبينه بغضاء سابقة، لأننا نعيش في منزل واحد، ووالدي شهد بذلك أمام القاضي فحكم علي سبع سنوات سجن، لكنني أشعر أن هذا لا يكفي، فأنا قد تبت إلى الله وأريد الحكم الشرعي في هذا الموضوع؛ لأنني في أشد القلق بسبب خوفي من الله ، فدلوني على الخير بارك الله فيكم؟","title":"حكم من قتل دون قصد القتل","answer":"الجواب: هذه المسألة تتعلق بالقضاء والمحاكم، فإذا سمح عنك أولياء المقتول وأسقطوا عنك حقهم فلا بأس، وعليك التوبة إلى الله مما صدر منك، أما إذا طلبوا حقهم من القصاص أو الدية فهذا إلى المحاكم، تنظر المحكمة الشرعية في ذلك وفي ما تراه المحكمة على ضوء الأدلة الشرعية البركة والكفاية، وإن كنت تعلم أنك متعمد وأنك قاصد قتله، فقدم نفسك، قدم نفسك ولا يحتاج إلى المحكمة، قل لهم: أنا ظلمت نفسي وأنا أخطأت وأنا الذي فعلت المنكر وأنا قصدت قتله، فإذا سمحوا عنك فلا بأس، وإن قتلوك فلهم الحق في قتلك قصاصاً، وهم أولياء الدم ورثة القتيل، أما إذا كنت تزعم أن هذا جرى منك من غير قصد سقطت منك السكين، أو طعنته بالسكين وأنت في غير شعور، هذا شيء يرجع إلى القضاء، ينظر فيه القاضي وبعد النظر يتبين له إن شاء الله ما يجب عليك، الله المستعان. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7631/حكم-من-قتل-دون-قصد-القتل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_240/24008.mp3","categories":["الجنايات والحدود"]},{"id":9508,"question":"هذه رسالة وردتنا من سليمان مبارك عمر مخاش من الرياض، يقول: ما حكم الشرع في حالة تعرض أحد من المسلمين للانتهاك في عرضه عندما يكون الشخص في رحلة برية أو بحرية أو جوية وقد يناديك للاستغاثة بك، وفي حالة تلبيتي ذلك بدافع ديني وأخوي وإنساني قد تقوم في أثناء دفاعك عنه بقتل أحد الأفراد المعتدين الغاصبين، علماً أنك لم تبخل بأي وسيلة لعدم التعرض لقتله، ولكن اضطررت إلى ذلك لأجل دفعه عن عرض أخيك المستنجد بك الذي معه نساء، أو يعتدى عليه هو في عرضه أو ماله أو نحو ذلك، أفيدونا ما الحال إذا كان هناك فيه قتل، وهل ينطبق على ذلك قول الرسول صلى الله عليه وسلم: «القاتل والمقتول في النار» أفيدونا أفادكم الله؟","title":"حكم قتل الصائل","answer":"الجواب: الواجب على المسلمين التآمر بالمعروف والتناهي عن المنكر أينما كانوا في الطائرة أو في غيرها، وعلى المسلم أن يعين أخاه في الحق وليس له أن يعينه في الباطل، وعليه أن يذب عن عرضه، فلا ينبغي له أن يجلس مع المغتابين بل ينكر عليهم ويعظهم ويذكرهم حتى لا يغتابوا إخوانهم؛ لأن الله سبحانه يقول: وَلا يَغْتَبْ بَعْضُكُمْ بَعْضًا [الحجرات:12] فالغيبة منكرة ومن الكبائر.\nفإذا جلست مع قوم يغتابون الناس فأنت شريك لهم في الإثم، إلا أن تنكر عليهم أو تفارقهم، فعليك أن تنكر فإن أجابوا فالحمد لله، وإلا فعليك أن تفارقهم ولا تجلس معهم على ما حرم الله عز وجل، وإذا تعدى زيد على أخيك، فالرسول ﷺ قال: انصر أخاك ظالماً أو مظلوماً، قالوا: يا رسول الله! نصرته مظلوماً فكيف أنصره ظالماً؟ قال: تمنعه من الظلم.\nوفي لفظ: تأخذ على يديه أي تحجزه عن الظلم، هذا نصر الظالم منعه من الظلم، فإذا تعدى أحد على أخيك توسط بينهم بالإحسان، في منعه العدوان، تحول بينهم أنت وإخوانك جميعاً، توسطون بينهم، تفكوا مشكلهم، تمنع هذا من هذا، وإذا كان لهم دعوى أو خصومة بعد ذلك يتصلوا بالمحكمة، لكن لا تتركونهم في الطائرة أو في السيارة أو في الباخرة أو في أي مكان يتقاتلان ويظلم أحدهما الآخر لا، بل توسطوا بينهم وحلوا مشكلهم، وامنعوا هذا من هذا، وكونوا جلساء خير وأعواناً في الخير، فانصروا المظلوم وامنعوا الظالم، هذا هو الواجب عليكم بدون قتل، أما القتل لا، لا يقتل هذا ولا هذا، بل عليكم أن تحولوا بينهم من التعدي، وأما القتل فلا يجوز الإقدام على القتل، بل هذا يؤجل إلى أن تنظر المحكمة في أمرهما، ومن كان يستحق قتلاً لأنه فعل ما يوجب القتل هذا له شأن آخر.\nفالحاصل أن عليك أن تساعد أخاك في رد ظلامته وفي منع الظلم عنه بغير قتل، أما القتل فلا؛ لأن القتل يحتاج إلى عناية ويحتاج إلى نظر في أسباب القتل، وإنما تحجز بينهما، تمنع هذا من التعدي على هذا، أنت وإخوانك الحاضرون، تتعاونون على منع هذا من ظلم أخيه، وإذا كانت لهم دعوات تؤجل حتى يصلوا إلى محلهم أو إلى بلد أخرى فيه القضاء، فيتحاكمون إلى القضاة فيما أشكل بينهم.\nلكن موضوع القتل موضوع كبير وعظيم فليس لأحد أن يقتل الآخر بل عليهم أن يتوقفا، وعلى أنصارهما أن يحولا بينهم وبين ذلك حتى لا يقع قتال. نعم.\nالمقدم: بارك الله فيكم، لو كان مع الشخص نساء وهو في البر واعتدي على عرضه واستغاث بأحد الناس، واضطر صاحب النساء والمساعد له في أن يدافعا عن عرضهما ووصل الأمر.. القتل.\nالشيخ: عليه أن يدافع، فإن قتل فهو شهيد، وإن قتل الظالم فلا شيء عليه.\nالمقدم: ربما هذا هو مقصود السائل يا شيخ.\nالشيخ: المقصود أنه إذا اعتدي على عرضه أو أراد قتله أحد فهذا له أن يدافع، من قتل دون ماله فهو شهيد، من قتل دون دمه فهو شهيد، من قتل دون دينه فهو شهيد، من قتل دون أهله فهو شهيد ثبت في الصحيح أن رجلاً قال: يا رسول الله! الرجل يأتيني يريد مالي؟ قال: لا تعطه مالك. قال: أرأيت إن قاتلني؟ قال: قاتله. قال: فإن قتلني؟ قال: فأنت شهيد. قال: فإن قتلته؟ قال: فهو في النار هذا رخص النبي في الدفاع عليه الصلاة والسلام يدافع عن ماله، فالعرض أكبر والدين أكبر، فإذا أراد الظالم أن يتعدى على زوجته أو بنته أو أمه فله أن يمنع ذلك بما استطاع، إن امتنع بالكلام أو بالعصا منعه، فإن لم يمتنع إلا بالقتل كالسيف والسكين ونحو ذلك فله ذلك، فإن صدق من جهة ولاة الأمور فلا قصاص عليه إذا ثبت ما يدل على صدقه، وإن لم يثبت هذا يرجع إلى المحكمة في تحري الحقائق والنظر في الواقعة، فإن ثبت ما يدل على صدقه وإلا فعليه قصاص. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7680/حكم-قتل-الصاىل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_243/24314.mp3","categories":["الجنايات والحدود","الأخلاق المذمومة"]},{"id":9518,"question":"وأول سؤال نطرحه على فضيلته ورد إلينا من المستمع (ن. س. ش) من مكة المكرمة يقول فيه: عندما كنت في السادسة عشر من عمري -أي: قبل سبع سنوات تقريباً- حصل لي حادث بالسيارة التي كنت أقودها أنا ومعي والدي رحمه الله وأخواتي وبعض من أقاربي، وكنت أقود السيارة التي هي للوالد بسرعة متوسطة وفجأة ضرب إطار السيارة الأمامي ولم أدر ما الذي حصل لي فقد أغمي علي ولم أدر بشيء ولم أفق إلا ونحن في الهاوية، وقد أصيب والدي بنزيف داخلي وانتقل إلى رحمة الله، سؤالي هو: هل أعتبر في هذه الحالة قاتلاً عمداً بمعنى هل يلزمني صيام شهرين متتابعين، وماذا أفعل كي يغفر الله لي هذا الذنب العظيم علماً بأنني عاهدت نفسي بأن أكون ملازماً لإخوتي أرعاهم حتى أصغر واحد فيهم، وأستغفر الله العظيم الذي وضعني القدر في هذا الموقف الصعب نعم ؟","title":"حكم من انقلبت سيارته وهو يقودها فمات من كان معه","answer":"الجواب: بسم الله الرحمن الرحيم. الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فالجواب أيها السائل! ينبغي أن تعلم أن الشيء في ذمة أمثالك وأنت أعلم بالواقع، فإن كنت تعلم أن الحادث بأسباب سرعتك أو لأن الكفر رديء وأنت تساهلت في عدم إبداله، أو بأسباب أخرى فعليك الكفارة وعليك الدية أيضاً.\nأما إن كنت لا تعلم شيئاً من ذلك وأنك تمشي بسرعة متوسطة كالناس ليس هناك زائد على الناس المشي المعتاد، والكفر لا تعلم فيه خللاً وليس فيه بأس فإنه ليس عليك شيء، لأنك لم تتسبب في الحادث وأمر الله غالب على الجميع قدر الله وما شاء فعل، مثلما لو كان الإنسان على مطية مع أخيه أو أبيه فعثرت أو جفلت ثم سقط أحدهما أو كلاهما فمات أحدهما لا يكون على قائدها شيء في هذا لعدم التسبب، فالسيارة إذا حصل منها انقلاب بسبب لا تعلق له بالسائق، فإنه لا يكون على السائق شيء؛ لأنه لم يفرط ولم يتعد، فأما إن كنت أسرعت سرعة زائدة خطيرة فعليك الكفارة وعليك الدية إلا أن يسمح ورثة أبيك عن الدية، وعليك كفارة وهي عتق رقبة مؤمنة، فإن لم تستطع فعليك صيام شهرين متتابعين كما هو نص كتاب الله عز وجل، ونسأل الله لك العون والتوفيق وما فيه براءة الذمة .\nوأنت يا أخي عليك أن تحاسب نفسك وتتأمل الواقع، فإن غلب على ظنك أنك مقصر ومفرط في هذا السير أو في الكفر الذي ضرب لأنك تساهلت في عدم إبداله وهو رديء فكفر صم شهرين متتابعين وأد الدية إلا أن يسمح عنك ورثة الوالد، وإن كنت تعلم أنك لم تقصر وأن السير معتدل وأن الكفرات سليمة فليس عليك شيء والحمد لله على قضاء الله. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7682/حكم-من-انقلبت-سيارته-وهو-يقودها-فمات-من-كان-معه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_244/24401.mp3","categories":["الجنايات والحدود"]},{"id":9566,"question":"هذه رسالة من السائل محمد هاشم سعيد مصري الجنسية يعمل بالجمهورية العربية اليمنية، الأخ محمد هاشم يقول في رسالته: لقد كانت زوجتي حامل في شهرها الخامس، وحدث لها ألم بالظهر ووصفت لها إحدى أقاربها أن تشرب الخل ليزيل الألم وبعد شراب الخل نزل الجنين في الحال، فهل على زوجتي إثم؟ وإذا كان عليها إثم فما الكفارة؟ أم أن الإثم والكفارة على من وصفت لها هذه الوصفة؟","title":"حكم من شربت دواءً أدى إلى سقوط جنينها","answer":"الجواب: يسأل الأطباء المختصون عن هذا الشيء، فإذا كانوا يرون أن شرب الخل يسقط الجنين فهذا عليها به الدية والكفارة؛ لأنها هي المباشرة وهي المخطئة حين أخذت الوصف من غير طبيب، وأما إن كان لا يضر الجنين في المعروف عند الأطباء فهذا أمر من الله وقدر من الله لا يضرها وليس عليها شيء، فقد يكون السبب شيئاً آخر غير الخل. نعم..\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7730/حكم-من-شربت-دواء-ادى-الى-سقوط-جنينها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_247/24702.mp3","categories":["الجنايات والحدود"]},{"id":9587,"question":"وهذه رسالة من المرسل شعبان عبده القاضي من جمهورية مصر العربية يقول: أنا أعمل في العراق وقمت بإرسال مبلغ من المال يزيد عن الألف جنيه مصري عن طريق البنك إلى ابن خالتي وأخي زوجتي فاستلمه من البنك وبعد خروجه سرق المبلغ منه فقال لي: إن المبلغ سرق وضاع مني، فهل لي الحق أن أطالبه بهذا المبلغ؟ وهل يغرم أفيدوني أفادكم الله؟","title":"حكم من أرسل إليه بمال ليحفظه فسرق منه","answer":"الجواب: هذا الأمر بينك وبينه؛ إن سامحته فلا بأس وإن لم تسامحه فبينكما المحكمة تنظر المحكمة في دعواه وفي حجته وفي كيفية السرقة وتحكم بعد ذلك. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7753/حكم-من-ارسل-اليه-بمال-ليحفظه-فسرق-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_248/24808.mp3","categories":["الجنايات والحدود"]},{"id":9593,"question":"وهذه رسالة من المرسل شعبان عبده القاضي من جمهورية مصر العربية يقول: أنا أعمل في العراق وقمت بإرسال مبلغ من المال يزيد عن الألف جنيه مصري عن طريق البنك إلى ابن خالتي وأخي زوجتي فاستلمه من البنك وبعد خروجه سرق المبلغ منه فقال لي: إن المبلغ سرق وضاع مني، فهل لي الحق أن أطالبه بهذا المبلغ؟ وهل يغرم أفيدوني أفادكم الله؟","title":"حكم من أرسل إليه بمال ليحفظه فسرق منه","answer":"الجواب: هذا الأمر بينك وبينه؛ إن سامحته فلا بأس وإن لم تسامحه فبينكما المحكمة تنظر المحكمة في دعواه وفي حجته وفي كيفية السرقة وتحكم بعد ذلك. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7753/حكم-من-ارسل-اليه-بمال-ليحفظه-فسرق-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_248/24808.mp3","categories":["الجنايات والحدود"]},{"id":9759,"question":"هذه رسالة وردت من المستمعة التي لم ترغب ذكر اسمها، وفي هذه الرسالة قضية قتل طفلة لها وعمرها أربعة أشهر، تقول: بأنها كانت نائمة بجانب أختها ومن عادتي أن آخذها إلى سريرها كل ليلة، حتى لا تكون بجانبي ولا بجانب أختها التي أكبر منها، لكن في هذا اليوم كنت مرهقة ومتعبة فنمت وتركتها بجانب أختها واستيقظت وهي ملفوفة في البطانية وقد ماتت وازرق جسمها، والآن والدها يهددني ويقول: إنك قتلتيها بإهمالك، وأنا في الحقيقة شديدة الحرص وكنت دائماً آخذها معي في كل مكان، ولا أتركها لوحدها، ولكن شاء الله قدر الله وما شاء الله فعل.والآن أريد أن أعرف إذا كان علي صوم شهرين، فأنا والله مصابة بفقر الدم وحامل، وإذا كان هناك فدية اعتاق رقبة، فكيف أستطيع ذلك وأنا فقيرة، وإذا كان هناك إطعام ستين مسكين فكيف أفعل، وأنا أيضاً فقيرة أفيدوني أفادكم الله؟","title":"كفارة القتل الخطأ","answer":"الجواب: مادام الحال كما ذكرت فليس عليك شيء؛ لأنك لم تتعمدي قتلها ولم تتسبي في قتلها، مادمت لم تنامي عليها ولم تضعي عليها شيئاً يقتلها، وإنما ماتت بشيء لا تعلمينه فليس عليك شيء.\nأما إذا كنت تعلمين شيئاً سبب موتها بأن جعلت عليها شيئاً ثقيلاً غطها حتى ماتت، هذا عليك الكفارة وهي عتق عبد أو عبدة عتق ذكر أو أنثى، فإن لم يتيسر صمت شهرين متتابعين.\nأما إذا كنت لا تعلمين إنما لما استيقظتي وجدتيها قد ماتت، فليس عليك شيء، لأن الكفارة لا تلزم بمجرد الشك والريب أو التهمة لا بد من أمر مضبوط، وأنت عليك خوف الله جل وعلا وعليك مراقبته، فإن كنت تعلمين أنك تسببت في موتها بأن نمت عليها مثلاً أو وضعت عليها شيئاً ثقيلاً يعني: لحاف ثقيل حتى رص وجهها وقطع نفسها، فأنت عليك الكفارة. نعم.\nوعليك الدية أيضاً. نعم.\nالمقدم: بارك الله فيكم، وما ذكرته الأخت السائلة من قضية إطعام ستين مسكين، هل هذا وارد في كفارة القتل سماحة الشيخ؟\nالجواب: لا، ما في إلا الصيام والعتق، أما الإطعام فليس فيه إطعام، أما الإطعام في كفارة الظهار وفي كفارة الوطء في رمضان، أما القتل فليس فيه إلا أمران: العتق عند القدرة، فإن عجز صام شهرين متتابعين.\nقتل الخطأ يعني. نعم.\nالمقدم: وإن عجز؟\nالشيخ: يبقى في ذمته حتى يسهل الله له القدرة.\nالمقدم: يمكن أن يصوم عنه وليه لو مات وهو في ذمته.\nالشيخ: لو مات. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7924/كفارة-القتل-الخطا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_256/25615.mp3","categories":["الجنايات والحدود"]},{"id":9863,"question":"أولى رسائل هذه الحلقة وردت من المستمع (ع. ع. ز) من العراق محافظة دهوك قضاء سميل، يقول السائل في رسالته: ما حكم من سمع من الناس أن امرأة متزوجة تزني، وشاهدهم في ذلك أن رجلًا غريبًا يدخل عليها بيتها ويبقيان وحدهما، فهل يجوز لأهلها أن يقتلوها، وهل يجوز شهادة المنفرد على ذلك، وماذا يفعل الشاهد، أفيدونا جزاكم الله خيرًا؟","title":"ما موقفنا من دخول رجل غريب على امرأة في بيتها؟","answer":"الجواب: الحمد لله رب العالمين، والصلاة والسلام على عبده ورسوله وخيرته من خلقه وأمينه على وحيه نبينا وإمامنا وسيدنا محمد بن عبد الله وعلى آله وأصحابه ومن سلك سبيله واهتدى بهداه إلى يوم الدين.\nأما بعد: فالواجب على المسلمين التعاون على البر والتقوى والأمر بالمعروف والنهي عن المنكر، فإذا رأى المؤمن شخصًا يدخل على بيت هو فيه محل ريبة أنكر ذلك ولم يقر على ما لا ينبغي بل يناصحه وينكر عليه ويقول له: دع هذا فإن هذا يسبب تهمتك وتهمة أهل البيت، هذا إذا كان يعرف حالهم ويعرف أن دخوله محل ريبة.\nأما ما يتعلق بالحكم من جهة المرأة والمتهم فلا يحكم عليها بالزنا ولا يحكم عليه بالزنا إلا بالإقرار لابد أن تقر هي وأن يقر هو، فإذا أقرت هي أو أقر هو حكم عليهما بحكم الزنا، فإن كانت ثيبة رجمت بالحجارة حتى تموت، وهكذا الرجل إذا كان ثيبًا رجم بالحجارة حتى يموت، والثيب: هو الذي قد تزوج زواجًا شرعيًا ودخل بالمرأة يعني: وطئها، وهكذا الثيبة هي التي قد تزوجت ودخل بها الزوج يعني وطئها الزوج، أما إن كانا بكرين فالبكر يجلد مائة جلدة ويغرب عامًا عن وطنه، هذا حكم البكر ولكن لا يثبت الزنا بقول واحد أو بالتهمة إنما يثبت بإقرار المرأة أربع مرات أو بإقرار الرجل أربع مرات ثم يستمر على إقراره حتى يقام عليه الحد، وهكذا البينة لابد من أربعة شهود يشهدون بأنهم رأوا ذاك منه في ذاك منها، رأوا أنه قد اتصل بها قد جامعها زنا فيقام عليهما جميعًا الحد، أما إذا لم يكن هناك بينة وهي أربعة شهود عدول ولم يكن هناك إقرار فإن المرأة والرجل يعاملان معاملة المتهم فيؤدبان أدب التهمة ولا يقام عليهما الحد ولكن يؤدبان بما يراه ولي الأمر وهو القاضي الشرعي أو الأمير الشرعي الذي تسند إليه الأمور، والقاضي هو أحوط في هذا إذا وجد يقدر التعزير المناسب، والأمير الشرعي المستقيم كذلك له أن يقدر التعزير المناسب فيؤدب الرجل ويؤدب المرأة المتهمين تأديبًا يردعهما وأمثالهما عن الوقوع فيما حرم الله وعن الوقوف في مواقف التهم. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8030/ما-موقفنا-من-دخول-رجل-غريب-على-امراة-في-بيتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_199/19901.mp3","categories":["الجنايات والحدود","قضايا المرأة"]},{"id":10212,"question":"المستمع حسن بليل أحمد بعث برسالة وضمنها سؤال مكون من صفحةٍ كاملة، ملخص هذا  أنه سائق لسيارة وركب معه مجموعة من الركاب، وكان أحدهم قريباً من باب الدخول والخروج، حينئذٍ دخلت السيارة في أماكن صعبة، فسقطت في إحدى الحفر، وهو بالتالي سقط من السيارة ووقع على رقبته ومات، جاء ليبحث عن هوية له فلم يجد، جاء ليبحث عن اسم له فلم يجد، وحينئذٍ احتار في أمره كيف يتصرف، جزاكم الله خيرا؟","title":"حكم من قاد سيارة وسقط منها شخص فمات","answer":"الجواب: هذا يتعلق بالمحكمة، يتعلق بالمحكمة والدوائر الحكومية المتعلقة بهذا الأمر؛ حتى يوجه إلى ما يجب في حقه، .... تعرف الجنازة، ويعرف المستحقون للدية، وهو عليه الكفارة إذا كان تساهل في الأمر؛ لأن عليه أن يجتنب الحفر، ويتأمل الطريق، ويتباعد عن الأخطار، فإذا تساهل في هذا فهو ضامن، كما يضمن إذا أسرع سرعةً زائدة، أو تساهل في أمر آخر من جهة الكفرات، ومن جهة ما يتعلق بإيقاف السيارة الفرملة، وما أشبه ذلك.\nالمقصود إذا كان منه تفريط؛ يلزمه الكفارة، والدية على العصبة على العاقلة، لكن هذا يتعلق بالمحكمة تنظر فيه المحكمة بواسطة رجال المرور، وما يثبتون عليه إذا كان عنده إنكار لشيء، ويعرفون حال الميت، ويسألون عنه بالطرق التي تمكنهم معرفة جنسيته، وأهله. نعم.\nالمقدم: جزاكم الله خيراً، يقول: أعتقد أن سبب سقوطه أنه كان على درجة عالية من السكر، كما ثبت ذلك طبياً، فهل الحكم واحد حينئذ؟\nالشيخ: هذا تفريط عظيم، إذا كان سكران يضمن؛ لأنه ما يجوز له أن يمشي في السيارة، ويسير بالسيارة وهو سكران.\nالمقدم: ليس هو السائق السكران، الراكب هو السكران؟\nالشيخ: إيه.\nالمقدم: نعم.\nالشيخ: هذا مشكل هذا محل نظر يحتاج إلى نظر المحكمة؛ لأنه قد يكون تساهل السائق في عدم ربط الباب، وقد يكون هذا السكران هو الذي فتح الباب، وقد يكون يعني هذا محل نظر يحتاج إلى عناية المحكمة، والتثبت في الأمر. نعم.\nالمقدم: جزاكم الله خيراً، إذاً نعرض عن هذا الموضوع؟\nالشيخ: نعم، نعم.\nالمقدم: جزاكم الله خيراً، تنصحون أخانا بمراجعة المحكمة حتى يبرئ ذمته.\nالشيخ: نعم، هذا الذي نراه يراجع المحكمة حتى تجري المحكمة الإجراءات الشرعية. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8392/حكم-من-قاد-سيارة-وسقط-منها-شخص-فمات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_310/31008.mp3","categories":["الجنايات والحدود"]},{"id":10411,"question":"نعود في بداية هذه الحلقة إلى رسالة المستمع: (ع. ع. غ) من حضرموت، أخونا عرضنا بعض أسئلته في حلقة مضت، وبقي له في هذه الحلقة سؤال واحد يقول: بلغني عن رسول الله ﷺ أنه قال: حد الساحر ضربه بالسيف، هل هذا حديث صحيح، أفيدوني مشكورين مأجورين إن شاء الله؟","title":"الحكم على حديث: (حد الساحر ضربة ..)","answer":"","link":"https://binbaz.org.sa/fatwas/8584/الحكم-على-حديث-حد-الساحر-ضربة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_341/34101.mp3","categories":["الجنايات والحدود","الحكم على الأحاديث"]},{"id":10421,"question":"المستمع حميد كاظم آل عبد بعث يسأل عن امرأة نامت وطفلها بجنبها، ويبدو أنها كتمت أنفاسه أو انقلبت عليه فأصبح ميتاً، ويسألون عن الحكم، جزاكم الله خيراً؟","title":"حكم أم نامت دون قصد على طفلها فمات","answer":"الجواب: إذا كانت تعلم أنها قتلته بالنوم عليه، أو بطرح ثوب عليه يقطع نفسه أو ما أشبه ذلك فعليها الكفارة، أما إذا كانت لا تعلم فليس عليها شيء، فهذا يرجع إليها إن كانت تعلم أنها نامت عليه أو غطته بشيء ثقيل كالمطرحة أو الكنبل فقطع نفسه، عليها كفارة وهي: عتق رقبة مؤمنة، فإن عجزت تصوم شهرين متتابعين، ستين يوماً، هذه الكفارة، أما الدية فعلى العاقلة إذا ثبت أنها قتلته خطأً منها، على العاقلة وهم العصبة إن لم يسمح أولياء الطفل، فالمقصود أن عليها الكفارة، والكفارة عتق رقبة مؤمنة، يوجد في بعض أفريقيا عبيد يباعون فإن لم تجد فصوم شهرين متتابعين ستين يوماً، هذا كله إذا تيقنت أنها قتلته، أما إذا كانت لا تدري ما أسباب موته، فالأصل براءة الذمة ولا يلزمها شيء والحمد لله. نعم.\nالمقدم: جزاكم الله خيراً، كم يكلف بالريالات عتق الرقبة لو تكرمتم سماحة الشيخ؟\nالشيخ: هذه الأيام نشتريها بنحو تسعة آلاف، وتارة بعشرة آلاف، وتارة بأحد عشر ألف نحو هذه القيمة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8595/حكم-ام-نامت-دون-قصد-على-طفلها-فمات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_317/31703.mp3","categories":["الجنايات والحدود","قضايا المرأة"]},{"id":10699,"question":"السائل ( سعد . ن. ع. الدوسري ) من الرياض يقول: قريب لي صدم فتاة صغيرة خطأ، فتوفيت هذه الفتاة ولزمه الصيام شهرين متتابعين، وحتى الآن لم يصم، وإذا قلنا له: صم، قال: إِنَّ اللَّهَ غَفُورٌ رَحِيمٌ [البقرة:173] ماذا نفعل معه، علماً بأنه شاب قادر على الصيام ويبلغ الآن ثماني عشرة سنة أي مراهق، هل يصوم عنه وليه في ذلك مأجورين؟","title":"حكم من تساهل في صيام كفارة قتل الخطأ","answer":"الجواب: الواجب عليه الصوم، ويقال له: )إِنَّ اللَّهَ غَفُورٌ رَحِيمٌ( [البقرة:173] وشديد العقاب أيضاً، قال تعالى: نَبِّئْ عِبَادِي أَنِّي أَنَا الْغَفُورُ الرَّحِيمُ [الحجر:49] وَأَنَّ عَذَابِي هُوَ الْعَذَابُ الأَلِيمُ [الحجر:50] وقال سبحانه: غَافِرِ الذَّنْبِ وَقَابِلِ التَّوْبِ شَدِيدِ الْعِقَابِِ [غافر:3] هو (غافر الذنب وقابل التوب) لمن تاب وأناب واستقام ( شديد العقاب) لمن خالف أمر الله وعصى أمره سبحانه وتعالى، فالواجب الحذر ( نبئ عبادي) يعني: خبرهم (أني أنا الغفور الرحيم) يعني من تاب إليه واستقام على طاعته، (وأن عذابي هو العذاب الأليم) من عصى وخالفه.\nفعلى من قتل جارية أو غيرها خطأ أو شبه عمد عليه الكفارة، عتق رقبة، فإن عجز يصوم شهرين متتابعين ستين يومًا، وإذا كان عاجز مريض حتى يشفيه الله يصوم، عمره ثمانية عشر بالغ لا يجوز له التساهل في هذا، يجب أن ينصح، نعم.\nالمقدم: بارك الله فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/8876/حكم-من-تساهل-في-صيام-كفارة-قتل-الخطا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_285/28522.mp3","categories":["الرقائق","الجنايات والحدود"]},{"id":10717,"question":"إحدى الأخوات المستمعات من الطائف تقول: المرسلة أم نشمي من المدينة بل من المدينة المنورة .... تقول في قضية لها مطولة بعض الشيء: أبعث إليكم هذه الرسالة وبها سؤال واحد فقط، وهو أن لي طفلاً يبلغ من العمر عشرة أشهر، قد توفي على إثر غرق في ماء، أما القصة بالتفصيل فهي: أن أحد الأولاد صب ماءً في سطل كبير، وذلكم الولد عمره ست سنوات، وأنا الذي طلبت منه ذلك؛ لأني كنت أغسل البيت، فأتته أخته أكبر منه سناً فوضعت على الماء الذي في السطل صابون وبعد أن انتهيت من غسيل البيت بقي هذا السطل بالماء مملوءاً، فذهبت أنا إلى الحمام ووجدت أن الماء الذي في السطل نظيف، حاولت أن أكبه في البلاعة لكني رأيت أن الماء كثيراً ونظيف، وأخيراً أغلقت الحمام وأخذت أطفالي معي وهم أربعة أطفال من غير الصغير الذي توفي، وبعد ذلك ذهبت إلى المطبخ كنت أريد أن أعمل الفطور، أما الطفل الصغير فكان يلعب في إحدى الغرف بالمنزل، ولكن القدر مكتوب، وبعد قليل أتاني ولدي الذي يبلغ من العمر ست سنوات يبكي ويقول: وجدت أخي ميت في الماء، وكان متنكس في السطل الذي كان مملوءاً، ذهبت أنا بسرعة ووجدت أخوه قد أخرجه من السطل، وقد أنزله خارج الحمام وهو قد توفي، وقد حصل هذا الحادث في (9/11/1408هـ) أرجو من سماحتكم أن تجيبوني على سؤالي في أسرع وقت، جزاكم الله خيراً؟","title":"موت الطفل غرقاً دون تسببب الأم بذلك","answer":"الجواب: ليس عليك بأس والحمد لله؛ لأنك لم تتسببي بهذا، هذا شيء عادي، وتركتيه حتى ترجعي إليه وتنظري في أمره، والولد ليس عنده بل في مكان آخر، ولكن الله قدر أن يأتي إليه فلا يضرك، ولا حرج عليك إن شاء الله، ولا دية ولا كفارة والحمد لله، ونسأل الله أن يعوضكم عن ذلك الطفل خيراً منه، وأفضل منه، وأن يجعله شافعاً لكم، الحمد لله. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/8896/موت-الطفل-غرقا-دون-تسببب-الام-بذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_343/34311.mp3","categories":["الجنايات والحدود"]},{"id":11312,"question":"بعد هذا رسالة بعثت بها إحدى الأخوات المستمعات، تقول: المرسلة هدى عبدالله، الأخت هدى لها أكثر من قضية تقول: امرأة توفي لها طفلان ولد وبنت، كلاهما لم يتجاوز الخامسة من العمر، غرقًا في بركة ماء، وكان ذلك منذ زمن طويل، كان البيت مزرعة وبه بركة ماء، وهي كانت مشغولة عنهما بأعباء المنزل فما هو توجيهكم لها الآن؟ جزاكم الله خيرًا.","title":"حكم غرق الطفلين دون تفريط من الأم","answer":"الجواب:  ليس عليها شيء الحمد لله لأنها لم تتسبب في ذلك، إلا إذا وضعتهما على البركة وتركتهما فهذا تفريط، أما إذا كانا في البيت على المعتاد وذهبت إلى شغلها وهما ذهبا إلى البركة فليس عليها شيء والحمد لله، نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9498/حكم-غرق-الطفلين-دون-تفريط-من-الام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_377/37709.mp3","categories":["الجنايات والحدود"]},{"id":11388,"question":"إحدى الأخوات المستمعات تقول: المرسلة (م)، أختنا تسأل سؤالين:في سؤالها الأول تقول: أنجبت طفلة وأمضت قرابة الشهر وهي مريضة من ألم في بطنها، وهي تسهرني طوال الليل، وفي إحدى الليالي غالبني النوم، وبعد أن استيقظت وجدت أن الطفلة قد توفيت فهل يلحقني شيء؟ إذ أني أخشى أن يكون اللحاف قد غطى وجهها أو أي شيء آخر جزاكم الله خيرًا.","title":"حكم من مات ولدها وشكت أنها كانت سبباً في موته","answer":"الجواب:  إذا كنت لا تعلمين شيئًا حصل منك سبب وفاتها فليس عليك شيء، الأصل السلامة والعافية، أما إذا كنت تعلمين أنك غطيت وجهها بشيء ثقيل حتى ماتت بسببه فعليك الكفارة، وأما الأصل فالسلامة والعافية الحمد لله، إذا كنت لا تعلمين شيئًا فليس عليك شيء. والحمد لله. المقدم: جزاكم الله خيرًا، تقول أخشى أن يكون حصل كذا؟ الشيخ: .... ليس عليها شيء، حتى تعلم أنه حصل منها ما سبب موتها. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9554/حكم-من-مات-ولدها-وشكت-انها-كانت-سببا-في-موته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_379/37904.mp3","categories":["الجنايات والحدود","قضايا المرأة"]},{"id":11498,"question":"بعد هذا رسالة بعث بها أحد الإخوة المستمعين يقول: أنا عبدالدائم من المدينة المنورة، أخونا يقول: إن زوجة ولدي في يوم من الأيام كان لها ابن يبكي، فأرادت أن تسكته من بكائه شفقة عليه، فخرجت به من الغرفة إلى البلكونة؛ لكي يسكت من بكائه، فرفعته بين يديها بغرض تسليته، فنفض بنفسه من بين يدي أمه إلى خارج العمارة، ولم يلبث إلا يومين في المستشفى فمات، والمطلوب من سماحتكم أن تفتونا فيما يجب عليها من كفارة لذلك، وهل في كفارتها إطعام، أو صيام، أو ما هو؟ جزاكم الله خيرًا.","title":"حكم من سقط ولدها من يديها فمات","answer":"الجواب:  نرجو ألا يكون عليها شيء؛ لأنها مصلحة أرادت خيرًا؛ فلا شيء عليها، وهو الذي فعل، هو الذي رمى بنفسه، وحرص على التخلص منها؛ فلا يضرها -إن شاء الله- لأنها لم ترمه هي، ولم تعرضه للرمي، إنما رفعته، فتملص منها بالقوة؛ حتى طرح نفسه، نرجو ألا يكون عليها شيء.","link":"https://binbaz.org.sa/fatwas/9677/حكم-من-سقط-ولدها-من-يديها-فمات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_383/38310.mp3","categories":["الجنايات والحدود"]},{"id":11528,"question":"تقول: إنه قبل أربعين سنة كانت لها ابنة، ولها سنة ونصف من عمرها، وقد قدمت في المجلس قهوة، وهذه الابنة في ذلكم المجلس، فلما تعدت المجلس سمعت صراخ البنت، فرجعت، فوجدت أن القهوة قد انكبت، وكان بينها وبين ابنتها مسافة، ولم تدر كيف كان ذلك، واستمرت البنت بعد ذلكم الحال مريضة لمدة خمسة وعشرين يومًا، ثم ماتت، وأصبحت تفكر في ذلكم الأمر، بماذا تنصحونها الآن؟ جزاكم الله خيرًا.","title":"حكم من ماتت ابنتها بسبب انسكاب القهوة عليها","answer":"الجواب: إذا كان الواقع هو ما ذكر؛ فليس عليها شيء -إن شاء الله- ليس عليها؛ لأنها لم تفعل ما يوجب موتها، فليس عليها -إن شاء الله- شيء، ونسأل الله أن يعوضها خيرًا.  المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9709/حكم-من-ماتت-ابنتها-بسبب-انسكاب-القهوة-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_385/38505.mp3","categories":["الجنايات والحدود"]},{"id":11555,"question":"المستمع: (س. ع. ق) بعث يقول: توفي لي طفل عمره سنة ونصف غرقًا في البيت منذ سبع سنين، والآن أريد أن أصوم شهرين متتاليين، وفعلًا بعون من الله صمت، والآن أنا في الشهر الثاني، فهل صيامي صحيح بعد مرور سبع سنين من وفاة طفلي؟","title":"حكم من تسبب في موت ولده بغرق أو نحوه","answer":"الجواب:  إذا كانت وفاته غرقًا بأسبابك أنت وضعته حول الماء حتى سقط فيه، فأنت عليك الصيام إن لم تستطع العتق، وإلا فالواجب العتق، فإذا لم يتيسر العتق؛ تصم شهرين متتابعين، ستين يومًا، فكمل، كملها واستعن بالله، ولو كنت تأخرت، فالواجب عليك البدار، ولكن تستغفر الله، وتتوب إليه عما حصل من التأخير، والله يعينك، ويكفر عنا وعنك السيئات. نعم.","link":"https://binbaz.org.sa/fatwas/9738/حكم-من-تسبب-في-موت-ولده-بغرق-او-نحوه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_297/29704.mp3","categories":["الجنايات والحدود"]},{"id":11601,"question":"بعد هذا رسالة بعث بها المستمع: مسعد سعيد القويعاني، أخونا يسأل جمعًا من الأسئلة، في أحدها يقول: عندي زوجة وبينما كانت ترضع طفلها قدر الله ونامت عليه، ومات الطفل، ما هي الكفارة الواجبة عليها؟ مع العلم أنها لا تعلم ذلك، حيث كانت نائمة، وهل على النائم حرج في مثل هذا؟ جزاكم الله خيرًا.","title":"حكم امرأة نامت على ولدها فقتلته وهي لا تعلم","answer":"الجواب: إذا كانت تعلم أنها السبب؛ فعليها الكفارة، وعلى العاقلة الدية (العصبة) الأقرب فالأقرب، إذا كانت تعلم أنه مات بأسباب نومها عليه؛ لأنها قتلته قتل خطأ، والخطأ فيه الكفارة والدية، الدية على العاقلة (العصبة) والكفارة عليها، وهي عتق رقبة مؤمنة، فإن عجزت عن ذلك؛ فإنها تصوم شهرين متتابعين: ستين يومًا متتابعة، هذه كفارة القتل الخطأ. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9778/حكم-امراة-نامت-على-ولدها-فقتلته-وهي-لا-تعلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_387/38704.mp3","categories":["الجنايات والحدود"]},{"id":11604,"question":"يقول: زوجتي كانت لها بنت عمرها سنة ونصف، وخرجت الزوجة من المنزل لقضاء بعض الأمور المتعلقة بالمنزل، وبعد رجوعها وجدت الطفلة قد وقعت في إناء به ماء، فماتت الطفلة، هل تلزمها كفارة في ذلك؟ مع أنها تعلم أن الطفلة خرجت خلفها، ولكن هي لا تعلم بأنها قد تسقط في هذا الإناء، جزاكم الله خيرًا.","title":"حكم من تركت طفلها فوقع في إناء به ماء فمات","answer":"الجواب:  لا شيء عليها -إن شاء الله- لأن هذا شيء معتاد، الطفلة في البيت تمشي مع أمها، تمشي في البيت، ولا تعتبر قاتلة، لا حرج عليها في ذلك -إن شاء الله- ولا كفارة. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9779/حكم-من-تركت-طفلها-فوقع-في-اناء-به-ماء-فمات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_387/38705.mp3","categories":["الجنايات والحدود"]},{"id":12243,"question":"السؤال الأخير لأخينا يقول: سارق أراد أن يتوب عن السرقة بعد أن قطعت يده، هل هناك فرصة للتوبة؟","title":"حكم من تاب بعد إقامة الحد عليه","answer":"الجواب:  السارق متى قطعت يده؛ فهي كفارة له، فالحد كفارة، فإذا لم يسرق بعد ذلك؛ فالحد كفارة له عن السرقة، وإذا تاب مع الحد؛ فهو خير إلى خير، وطهرة إلى طهرة، الله جعل الحدود كفارة، فالمقتول قصاصًا كفارة، والمقتول في حد الزنا بالرجم كفارة، والمقطوع في السرقة كفارة، إلا أن يأتي بذنب آخر بعد ذلك؛ فعليه التوبة إلى الله منه، فإذا جمع مع الحد التوبة إلى الله، والندم؛ صار خيرًا إلى خير، ونعمة إلى نعمة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10431/حكم-من-تاب-بعد-اقامة-الحد-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_448/44807.mp3","categories":["الجنايات والحدود"]},{"id":12531,"question":"بعد هذا رسالة وصلت إلى البرنامج من جدة بعث بها مستمع رمز إلى اسمه بالحروف (أ. أ. ح) يقول: إنني في أثناء قيادتي السيارة على خط طويل، وأنا مسرع، إذ طلع علي شخص من جانب الطريق ليقطع الشارع، ولم أتصرف عنه حيث أنه اصطدم في جنب السيارة صدمة عنيفة، ونظرًا لخوفي ولجهلي بمثل هذا الموقف شردت، ولا أدري كيف صار الحادث، هل الشخص توفي أم سلم؟! وأتمنى أنه سلم، أفيدوني جزاكم الله خيرًا؛ حيث أنني الآن ضميري يؤلمني، فماذا أفعل، علمًا بأن الشخص غير معروف حتى الآن، وقد مضى عليه من الزمن ما يقرب سبع سنوات، وجهوني جزاكم الله خيرًا؟","title":"داس شخصاً بسيارته ثم فر ولم يدر مصيره فماذا عليه؟","answer":"الجواب:  الواجب عليك التوبة إلى الله سبحانه من السرعة، ومن الشرود من الحادث، عليك التوبة إلى الله من ذلك بالندم الصادق، والعزيمة ألا تعود، وعليك أن تجتهد في البحث عن الرجل حسب طاقتك، فإن علمت أنه مات؛ أديت ديته، وعليك الكفارة، وإن سلم؛ فالحمد لله، الواجب عليك ثلاثة أمور: الأمر الأول: التوبة، والندم، والإقلاع، والعزم ألا تعود؛ لأن السرعة لا تجوز، بل يجب على المؤمن أن يسير في الطرقات سيرًا بعيد عن الخطر، عليه وعلى غيره. الأمر الثاني: أن تجتهد في البحث عنه، وماذا صار في أمره؟ والأمر الثالث: أن تؤدي الحق متى عرفت أنه مات، تؤدي الدية، وتؤدي الكفارة، وإن أصابه شيء دون الموت؛ أديت ما يجب من أجرة الطبيب المعالج، وغير ذلك مما يلزم -نسأل الله لنا ولكم الهداية- نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10725/داس-شخصا-بسيارته-ثم-فر-ولم-يدر-مصيره-فماذا-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_408/40804.mp3","categories":["الجنايات والحدود"]},{"id":12562,"question":"إذا ارتكب المسلم إثمًا يستحق الحد والقصاص، أو التعزير، ولم يقام عليه هذا العقاب، ولم يعلم عنه أحد، وتاب توبة نصوحًا، فهل يعاقب يوم الحساب على هذا العمل، أم لا؟","title":"حكم من تاب من ذنب يستحق القصاص أو التعزير","answer":"الجواب:  من توبته في القصاص أن يمكن من نفسه حتى يرضى صاحبه، أو يقتص، أما بقية المعاصي إذا تاب إلى الله؛ فالله يعفو عنها  لكن إذا كان الحق للمخلوق كالسرقة، والقتل ونحوه فهذا لابد من إعطاء المخلوق حقه، فإن لم يعطه حقه؛ فالتوبة تسقط عنه حق الله، وتسقط عنه خطر دخول النار، ولكن يبقى عليه حق القتيل، حق المسروق منه، لابد أن يؤدى عنه، فإن تاب توبة صحيحة؛ فيرجى له أن الله يؤدي عنه  إذا لم يستطع أداء الحق، فالله -جل وعلا- يؤدي عنه  تلك الحقوق إذا كانت التوبة صحيحة وسليمة مستوفية شروطها، ومن شروطها: ألا يستطيع ألا يتمكن من أداء الحق للمخلوق، فإن شروطها ثلاثة: الندم على الماضي، والإقلاع من الذنب، والعزم الصادق ألا يعود فيه، هذه ذنوب متعلقة بالله، جل وعلا.  وهناك شرط رابع يتعلق بالمخلوق كالدم والسرقة وظلم الأموال والأعراض، فهذا الحق يجب أن يؤدى لصاحبه، فإذا عجز عنه بأن مات صاحبه، وليس له ورثة؛ يعطيهم حقهم، فإن حق الميت يبقى، وإذا كانت التوبة صادقة فالله يغنيه عنه -جل وعلا- لأنه صادق في محبته للتوبة، وإعطائه حقه، لكن لم يتمكن من هذا الشيء؛ لأنه مات، وليس وراءه أحد يأخذ الحق، فحينئذ يبقى الأمر بينه وبين الله  والله  يتقبل من عبده التوبة الصادقة في جميع الأشياء، كما قال سبحانه: قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا [الزمر:53]. لكن إذا كان صاحب الحق موجودًا؛ فلابد من إعطائه حقه، أو استباحته، وإلا فإنه يأخذ من حسناته بقدر المظلمة، كما قال -عليه الصلاة والسلام-: من كان عنده لأخيه مظلمة؛ فليتحلله اليوم قبل ألا يكون دينارًا، ولا درهمًا، إن كان له عمل صالح أخذ من حسناته بقدر مظلمته، فإن لم يكن له حسنات يعني الظالم أخذ من سيئات صاحبه فحمل عليه. فهذا يدل على أن حق المخلوق لابد من أدائه حيث أمكن، أما إذا لم يمكن فالله يعذره  والتوبة مقبولة ونافعة ومفيدة، ويبقى حق المخلوق الذي لم يستطع أداءه يرضيه الله، يرضي الله صاحبه عنه بأنواع الثواب والخير، فإنه سبحانه جواد كريم، والعبد معذور بأنه لم يتمكن من أداء الحق، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10776/حكم-من-تاب-من-ذنب-يستحق-القصاص-او-التعزير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_411/41110.mp3","categories":["الجنايات والحدود"]},{"id":12590,"question":"المستمع (م. س. ص) من المجاردة بعث برسالة ضمنها عددًا من الأسئلة، يقول في سؤاله الأول: رجل فقد حذاءه -أجلكم الله- في مكان عام، فقام باستبداله بآخر، هل عليه ذنب؟ وهل تلزمه كفارة؟ أفيدونا بالحكم، جزاكم الله خيرًا.","title":"حكم من سُرقت حذاؤه في مكان عام فأخذ غيرها","answer":"الجواب:  ليس له أن يأخذ حذاءً أخرى، بل يعتبر هذا تعديًا، يعتبر هذا تعديًا على غيره، ولكن يسأل: من وجد الحذاء التي صفتها كذا وكذا، يسألهم، فإن وجد ذلك؛ فالحمد لله، وإلا يرجو من الله الخلف، لكن لو كان في مكان خاص، ووجد مكانها ما يشبهها؛ فلا مانع؛ لأن الذي أخذها قد غلط، ما دامت مشتبهة بالباقية، بالموجودة. فالظاهر أن صاحبها الذي أخذها لم يتعمد الباطل، وإنما أخذها غلطًا يحسب أنها حذاءه؛ لأنهما مشتبهتان، فإذا كان في محل خاص، ووجد مكانها ما يشبهها، ويمكن غلط فيها، فأرجو ألا حرج عليه في ذلك عملًا بالظاهر، وأن الظاهر أن صاحبها تركها هو أخذ غيرها يظنها نعله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10801/حكم-من-سرقت-حذاوه-في-مكان-عام-فاخذ-غيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_413/41304.mp3","categories":["الجنايات والحدود"]},{"id":12711,"question":"إذا أقيم حد من الحدود على مرتكب لمعصية في الدنيا، فهل يكفي هذا عن العقاب في الآخرة؟","title":"حكم العقاب الأخروي للذي أقيم عليه الحد في الدنيا","answer":"الجواب: نعم يكفي، النبي ﷺ لما ذكر الشرك، وجملة من المعاصي قال في ذلك فما أدركه الله في الدنيا كان كفارة له فإذا أقيم الحد في الدنيا؛ كان كفارة له إذا مات على ذلك، ولم يعد إلى الذنب، أما إذا عاد إليه يؤخذ بالآخر، إذا عاد إليه، ولم يتب؛ يؤخذ بالآخر، والأول كفاه الحد، لكن لو زنا، وأقيم عليه الحد، ثم مات على ذلك؛ فإنه لا يؤخذ بزناه، بل الحد كفارة والحمد لله. أما لو عاد إلى زنا ثانٍ بعدما جلد إذا كان بكرًا وعاد؛ فإنه يؤخذ بالآخر والأول؛ كفاه الحد فيه، وهكذا بقية المعاصي، فلو قتل إنسانًا، ثم عفوا عن القصاص، وسمحوا بالدية نعم سقط حقهم، لكن لو عاد إلى قتل آخر؛ بقي عليه حق القاتل الآخر، وهكذا. المقصود: أنه إذا تاب، أو أدى الحقوق من جهة الذنب؛ فإن أداءه الحقوق، والتوبة يغفر بها ما سلف، لكن الذنب الجديد يبقى عليه إلا أن يتوب. نعم. المقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10923/حكم-العقاب-الاخروي-للذي-اقيم-عليه-الحد-في-الدنيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_459/45916.mp3","categories":["الجنايات والحدود"]},{"id":12718,"question":"ما هو مقدار دية الرجل، ودية المرأة، ودية الطفل؟","title":"مقدار دية الرجل ودية المرأة والطفل","answer":"الجواب:  دية الرجل مائة ناقة، والمرأة خمسين، النصف، والطفل مثل الرجل، إن كان رجلًا؛ فهو مائة، وإن كان امرأة؛ فهو خمسون، والطفل مثل الكبير، ومقدارها في المملكة العربية السعودية الآن مائة ألف بالقيمة بدلًا من مائة الناقة؛ لأن مائة الناقة ذات أنواع على أنواع، فيها بنت المخاض، وبنت اللبون، والحقة تختلف حسب العمد، وحسب الخطأ أيضًا. فالحاصل: أنها قدرت بمائة ألف ريال للرجل، وخمسين ألفًا للمرأة في الوقت الحاضر، وقد تزيد في المستقبل، وقد تتغير في المستقبل، أو تنقص على حسب قيمة الإبل. فالمقصود: الأساس الإبل، مائة من الإبل في حق الرجل، وخمسون في حق المرأة، والطفل إن كان ذكرًا فهو مائة ألف، وإن كانت أنثى فهو خمسون ألفًا الصغير كالكبير، ويقدرها ولي الأمر بالنقود على حسب قيمة الإبل المتوسطة، في مملكته، تقدر بحسب قيمتها، حسب القيمة المتوسطة على حسب أنواع الإبل التي جاءت في الأحاديث، وعلى حسب القتل إن كان خطأً له حال، وإن كان عمدًا له حال. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10931/مقدار-دية-الرجل-ودية-المراة-والطفل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_460/46006.mp3","categories":["الجنايات والحدود"]},{"id":12720,"question":"المستمع عبدالوهاب خالد الحليبي -فيما يبدو- من جامعة الملك فيصل بالأحساء، بعث برسالة يقول: لي خال يجيد بعض الأعمال غير العمل المتخصص فيه، وفي يوم من الأيام طلب منه أحد الجيران أن يعمل في منزله ليسلك له بعض الأعمال الكهربائية، فتوفي في حادث التماس كهربائي، حدثني شخص عن الحادثة فقال: عندما التمس التيار الكهربائي طلب خالك من صاحب المنزل أن يطفئ التيار، فلم يستطع صاحب المنزل إطفاء التيار؛ لأنه ذهل بالمشهد، هل على صاحب المنزل كفارة؟ وهل تعتبر الحادثة قتلًا متعمدًا؟ وهل يعتبر المتوفى شهيدًا؟","title":"حكم من مات بماس كهربائي","answer":"الجواب:  إذا كان الواقع كما ذكره السائل فيرجى له الشهادة، وليس بقتل متعمد، وليس على كل منهما شيء؛ لأنهما لم يتعمدا، نسأل الله السلامة. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10933/حكم-من-مات-بماس-كهرباىي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_460/46008.mp3","categories":["الجنايات والحدود"]},{"id":12725,"question":"رسالة مطولة من صفحة كاملة بعث بها أحد الإخوة المستمعين، ذكر اسمه، ومكان عمله، ولكنا نؤثر عدم ذكرهما، ملخص ما في هذه الرسالة أنه سرق من زميل له مبلغًا من المال، فكيف يتصرف ويعيده إليه؟","title":"كيفية التخلص من المال المسروق","answer":"الجواب:  يجب عليه أن يعيد المال إلى زميله، إما بالصراحة فيستسمحه، ويطلب منه العفو، ويعطيه إياه، وإما بطريق أخرى إذا كان لا يرغب أن يعرفه بطريق أخرى بواسطة من يراه من الثقات حتى يوصل إليه المال، ويسلمه له. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10938/كيفية-التخلص-من-المال-المسروق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_460/46013.mp3","categories":["الجنايات والحدود"]},{"id":12736,"question":"ولي زميل آخر بيني وبينه ود ومحبة، قام بسرقة أشياء من مكان العمل، وقمنا بالإبلاغ عنه بحكم عملي بالحراسة، فتوقف عن العمل لمدة خمسة عشر يومًا قطعت من راتبه، فهل أكون قد ارتكبت معصية حين بلغت عنه؟","title":"حكم من قام بالإبلاغ عن زميل له سرق","answer":"الجواب:  لا حرج عليك، قد أحسنت في ذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10950/حكم-من-قام-بالابلاغ-عن-زميل-له-سرق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_418/41807.mp3","categories":["الجنايات والحدود"]},{"id":12821,"question":"إذًا هذا سؤاله عن مقدار الدية التي تعطى لأهل المقتول خطأ؟","title":"مقدار دية المقتول خطأ","answer":"الجواب:  الدية في الخطأ، وفي العمد، وشبه العمد كلها مائة من الإبل في حق المسلم، مائة من الإبل تختلف أنواعها، والقضاة يعرفون أنواعها، والذي يبتلى بشيء من ذلك يرجع المحكمة وتعطيه الطريق المتبع، لكنها مقدرة الآن بمائة ألف ريال، في حق الرجل، وفي حق المرأة خمسين ألف ريال، المسلمة والمسلم، خطأ أو عمدًا، لكن العمد فيه القصاص، وإذا اصطلحوا على شيء ولو أكثر من مائة من الإبل، ولو على مليون؛ لا حرج في العمد، أما الخطأ وشبه العمد؛ ففيه مائة من الإبل فقط، أو قيمتها إذا تراضوا على قيمتها، وقيمتها الآن مقدرة عند المحاكم الشرعية بمائة ألف ريال، هذا الوقت، والمرأة لها خمسون ألف ريال، وقد يتغير الحال في المستقبل عند تغير أحوال الإبل، والذي يحصل له شيء من هذا في إمكانه مراجعة المحكمة الشرعية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11035/مقدار-دية-المقتول-خطا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_463/46309.mp3","categories":["الجنايات والحدود"]},{"id":13020,"question":"رسالة بعث بها المستمع (س. ع) يقول فيها: حصل حادث على رجل، وعلى إثر ذلك انتقل الرجل إلى رحمة الله -تغمده الله بواسع رحمته وأسكنه فسيح جناته- وقد حصل الحادث على الرجل من خلف سيارته التي يقودها، وبمناسبة أن الرجل متوفى له أولاد، وأعتقد أنهم قصر، وقد حصلت محاورة بين أقربائه، البعض منهم يرغب التنازل عن الرجل الذي صدم الرجل المتوفى من الخلف، والبعض منهم يرغبون دية يضعونها، ويصرفون منها على الأولاد، والبعض منهم يقولون: نبني له مسجدًا، ونحفر له بئرًا بأرض فلاة، ويكون الأجر له، والبعض يقولون: نأخذ الدية، ونتصدق بها إذا حكم بها شرعًا، ويكون الأجر للمتوفى، وجهونا حول أحسن الطرق، هل هو العفو، أو ما ذكرنا؟ جزاكم الله خيرًا.","title":"حكم من قتل خطأ وله ورثة قصار","answer":"الجواب: إذا كان المتوفى له أولاد صغار، أو أولاد مجانين، أو غير مرشدين؛ لم يجز العفو، بل يجب على وليهم أن يأخذ الدية، ويحفظها لهم، ويصرفها في مصالحهم، ولا يجوز العفو من وليهم عن الدية، أما إذا كان الورثة مرشدين، ليس فيهم قاصر، وأحبوا أن يسمحوا؛ فلا حرج عليه، أو أحبوا أن يضعوها في تعمير مسجد، أو في حفر بئر بفلاة تنفع المسلمين، أو في صدقة على الفقراء، أو في مساعدة للمجاهدين، كل هذا لا بأس به، هم أحرار؛ لأنهم مرشدون، يتصرفون كيف شاؤوا. والأولى أن يأخذوها، لا يسمحوا بها للصادم حتى لا يتساهل الناس في الصدم والتعدي على الناس، الذي ينبغي أن يأخذوا الدية، ثم يتصرفوا فيما يرون إذا كانوا مرشدين، إما توزعوها بينهم وتصرفوا فيها، وإما صرفوها في جهة بر، كتعمير مسجد، أو صدقة على الفقراء، أو صرفها في المجاهدين في سبيل الله، أو نحو ذلك. أما إذا كانوا غير مرشدين، أو فيهم من هو ليس بمرشد؛ فلا يجوز لولي القاصر أن يسمح عن شيء منها، سواء كان القاصر صغيرًا، أو معتوهًا، أو مجنونًا، أو سفيهًا، ليس لوليه أن يسمح، بل يجب أن يأخذ حقه من الدية، ويحفظه للقاصر حتى ينفق عليه منه، أو يصرفه في مصالحه كتعمير عقاره، وغير ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11237/حكم-من-قتل-خطا-وله-ورثة-قصار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_471/47116.mp3","categories":["الجنايات والحدود"]},{"id":13109,"question":"ننتقل بعد ذلك إلى رسالةٍ بعثت بها السائلة نورة من دمشق، تقول في هذا  إذا أخطأ أحدنا خطأً فهل يجوز للمسلمين أن يفضحوا أمره، وينشروه؟ وما حكم الشرع فيمَن يفعل ذلك يا سماحة الشيخ؟ مأجورين.","title":"وجوب ستر المسلم غير المجاهر بالمعصية","answer":"الجواب: هذا يختلف؛ إن كان الرجل أظهر المنكر؛ فلا بأس أن يُقام عليه، ويُعامل بما يستحق من إقامة الحد، أو التعزير. أما إذا كان أَسَرَّ المنكر؛ فلا تجوز فضيحته، ولا غيبته، بل الواجب الستر عليه؛ لقول النبي ﷺ: مَن ستر مسلمًا؛ ستره الله في الدنيا والآخرة؛ ولقول الله -جلَّ وعلا-: وَلَا يَغْتَبْ بَعْضُكُمْ بَعْضًا [الحجرات:12]. فالمؤمن يستر على أخيه، ولا يفضحه ما دامت المعاصي خفيةً، أما إذا أظهر المنكر، وبارز الله بالمُحاربة؛ فهذا لا بأس أن يظهر أمره، ويرفع أمره؛ حتى تُقام عليه الحدود الشرعية، أو التعزيرات الشرعية، وحتى لا يتجرأ الناس على المعاصي كما تجرأ. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11325/وجوب-ستر-المسلم-غير-المجاهر-بالمعصية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_508/50816.mp3","categories":["الجنايات والحدود"]},{"id":13165,"question":"على بركة الله نبدأ هذا اللقاء بسؤال من السائلة (م. م) تقول: ما كفارة القتل، أو القاتل الغير المتعمد؟ نرجو بهذا الإفادة مأجورين؟","title":"ما كفارة القتل غير المتعمد؟","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  قد أوضح الله  في كتابه الكريم كفارة قتل الخطأ، وهي عتق رقبة مؤمنة، فإن عجز صام شهرين متتابعين؛ لقول الله سبحانه في سورة النساء: وَمَا كَانَ لِمُؤْمِنٍ أَنْ يَقْتُلَ مُؤْمِنًا إِلَّا خَطَأً وَمَنْ قَتَلَ مُؤْمِنًا خَطَأً فَتَحْرِيرُ رَقَبَةٍ مُؤْمِنَةٍ وَدِيَةٌ مُسَلَّمَةٌ إِلَى أَهْلِهِ إِلَّا أَنْ يَصَّدَّقُوا [النساء:92] فالكفارة عتق رقبة مؤمنة، وعليه الدية مع ذلك، إلا أن يصدق أهل الميت، ويسمحوا عن الدية؛ فلا بأس. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11420/ما-كفارة-القتل-غير-المتعمد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_511/51101.mp3","categories":["الجنايات والحدود"]},{"id":13343,"question":"تسأل أختنا وتقول: إذا كان شخص عنده دية لشخص ما، وأعطاه حاجة ثمنها يساوي الدية التي عنده، فهل هذا جائز؟","title":"ما حكم إعطاء الدية من العينيات؟","answer":"الجواب: نعم إذا تراضوا على ذلك لا بأس، إذا تراضوا فأخذ عن الدية أرضًا، أو سيارات، أو حبوبًا، أو غير ذلك لا بأس، مثلما قال النبي ﷺ: الصلح جائز بين المسلمين، إلا صلحًا حرم حلالًا، أو أحل حرامًا نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11629/ما-حكم-اعطاء-الدية-من-العينيات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_477/47703.mp3","categories":["الجنايات والحدود"]},{"id":13504,"question":"على بركة الله نبدأ هذا اللقاء بسؤال للسائل: عبدالرحيم يقول في هذا  سماحة الشيخ! إذا تسبب الرجل في قتل رجل آخر، وعفا أهل القتيل عنه، هل تسقط عنه الكفارة؟ وماذا يلزمه؟ جزاكم الله خيرًا.","title":"هل تسقط كفارة القتل إذا عفى أولياء الدم؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه. إن كان المتسبب متعمدًا؛ فعليه التوبة، ولا كفارة عليه، عليه التوبة إلى الله -جل وعلا- والحمد لله الذي عفوا عنه، عفا عنه أولياء المقتول، والحمد لله، جزاهم الله خيرًا، أما إن كان خطأً، أو شبه عمد، مثل: أراد أن يرمي صيدًا، فأصابه، أو طقه بعصا خفيفة، أو ضربة خفيفة، مات بها، هذا عليه الدية، وعليه الكفارة، الدية معروفة، والكفارة عتق رقبة، فإن لم يستطع؛ صام شهرين متتابعين؛ لقول الله -جل وعلا-: وَمَا كَانَ لِمُؤْمِنٍ أَنْ يَقْتُلَ مُؤْمِنًا إِلَّا خَطَأً وَمَنْ قَتَلَ مُؤْمِنًا خَطَأً فَتَحْرِيرُ رَقَبَةٍ مُؤْمِنَةٍ وَدِيَةٌ مُسَلَّمَةٌ إِلَى أَهْلِهِ إِلَّا أَنْ يَصَّدَّقُوا [النساء:92]. فالواجب على من قتل خطأً، أو شبه خطأ عليه الدية، والكفارة إلا أن يسمحوا عن الدية؛ فلا بأس، أما الكفارة تبقى في ذمته، إن استطاع العتق؛ أعتق، فإن لم يستطيع العتق؛ صام شهرين متتابعين، ستين يومًا بنص القرآن الكريم. أما المتعمد لا، المتعمد توعده الله بالعذاب والنار، قال سبحانه: وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا فَجَزَاؤُهُ جَهَنَّمُ خَالِدًا فِيهَا وَغَضِبَ اللَّهُ عَلَيْهِ وَلَعَنَهُ وَأَعَدَّ لَهُ عَذَابًا عَظِيمًا [النساء:93] ما جعل عليه عتق؛ لأن الأمر أعظم، العتق والكفارة تدخل في الذنب إذا كان أسهل، فإذا عظم الذنب، واشتد ما دخلته الكفارات؛ لعظمه وخطره، فالقتل جريمة عظيمة، لا تدخلها الكفارة، بل يجب القصاص إذا توفرت شروطه، فإن لم يجب القصاص؛ فالدية مع التعزير، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11813/هل-تسقط-كفارة-القتل-اذا-عفى-اولياء-الدم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_518/51813.mp3","categories":["الجنايات والحدود"]},{"id":13613,"question":"السائلة التي رمزت لاسمها بـ (خ. عبدالله . ع) من مدينة أبها تقول: كنت صغيرة، وسرقت سلسلة من الذهب، والآن لا أعرف أصحابها، كيف العمل في ذلك؟","title":"حكم من سرق شيئًا ثم تاب ولم يعرف صاحبه","answer":"الجواب: إذا كنت لا تعرفين أصحابها تصدقي بها عنهم، تصدقي بالسلسلة عن أصحابها، أعطيها بعض الفقراء بالنية عن صاحبها المجهول، فيكون له أجر ذلك، وأنت تبرئين من ذلك مع التوبة إلى الله، والندم، عليك التوبة والندم مما فعلت، والعزم ألا تعودي، وأن تتصدقي بها على بعض الفقراء بالنية عن أصحابها . المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11953/حكم-من-سرق-شيىا-ثم-تاب-ولم-يعرف-صاحبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_528/52807.mp3","categories":["الجنايات والحدود"]},{"id":13704,"question":"السائل أبو عابد من الرياض استعرضنا سؤالًا له في حلقة سابقة، ويسأل في سؤاله ويقول: إنسان مثلًا: قتل شخصًا آخر بقصد الدفاع عن النفس، فهل في ذلك شيء؟","title":"حكم من قتل شخصًا دفاعًا عن النفس","answer":"الجواب: إذا كان القاتل دافع عن نفسه، ظلمه المقتول، وأراد قتله، أو ضربه فلم يزل يدافعه حتى قتله، فلا شيء عليه؛ لأنه مدافع عن نفسه مظلوم، لكن يدفع بالأسهل فالأسهل، فإذا لم يتيسر؛ دفع الصائل إلا بالقتل قتله، والحمد لله، نسأل الله العافية. نعم. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/12070/حكم-من-قتل-شخصا-دفاعا-عن-النفس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53503.mp3","categories":["الجنايات والحدود"]},{"id":14295,"question":"من مدينة المرج في ليبيا المستمعة نوارة سالم محمد بعثت برسالة وضمنتها سبعة أسئلة، في أحد أسئلتها تقول: والدتي يوم أن كانت صغيرة في العقد الأول من عمرها حملت ابن أختها الرضيع فوقع منها على الأرض مما أدى إلى وفاته بعد يومين؛ لكنها لم تخبر أهلها بذلك وظنوا أن وفاته بسبب مرض أو غيره، وقد أخبرتنا وأخبرت والدته منذ فترة بسيطة بما حصل منها، وهي تستفسر عن الحكم فأرجو إفادتها بذلك ماذا عليها تجاه رب العزة والجلال وتجاه أولياء الطفل؟ ولكم من الله المثوبة.","title":"ما يجب على الطفل إذا تسبب بموت إنسان؟","answer":"الجواب: إذا كان الواقع ما ذكرته السائلة فعلى التي وقع منها الحادث أن تخبر أولياء الطفل بما جرى ومرجعهم بعد ذلك في الموضوع إلى المحكمة الشرعية، إذا كانت صغيرة ما بعد بلغت الحلم فليس عليها كفارة، وأما الدية فهي على العاقلة وهم العصبة إذا ثبت ما ذكرته السائلة أن الطفل وقع منها، وإن سمح أهل الطفل فلا حرج إذا سمحوا عن الدية فلا حرج وإن طالبوا فالمرجع في ذلك إلى المحكمة وهي على العاقلة على العصبة؛ لأنه خطأ ليس باختيار المرأة، وإن كانت صغيرة فليس عليها كفارة.\nأما إن كانت كبيرة قد بلغت الحلم فعليها الكفارة وهي عتق رقبة مؤمنة، فإن عجزت تصوم شهرين متتابعين؛ لأن هذا قتل خطأ حصل بسببها، بسبب تفريطها وتساهلها. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12758/ما-يجب-على-الطفل-اذا-تسبب-بموت-انسان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_486/48616.mp3","categories":["الجنايات والحدود"]},{"id":14425,"question":"المستمع (ح. ع. الحميدي) بعث برسالة يقول فيها: حصل علي حادث من مدة عشرة أشهر، ولقد توفيت امرأة بسبب ذلك الحادث، والحادث سببه مشترك بين الطرفين، وقد أمرنا شيخ المحكمة بصيام شهرين متتاليين.الشيخ: أعد.المقدم: يقول: حصل علي حادث من مدة عشرة أشهر، ولقد توفيت امرأة بسبب ذلك الحادث، والحادث سببه مشترك بين الطرفين، وقد أمرنا شيخ المحكمة بصيام شهرين متتالين، وأنا لا أستطيع الصيام؛ فهل يجوز دفع الصدقة عن الصيام؛ لأنني لا أستطيع الصيام؟ وما مقدار الصدقة؟أفيدونا، جزاكم الله خيرًا.","title":"حكم الإطعام في كفارة قتل الخطأ لمن عجز عن الصيام","answer":"الجواب: القتل ليس فيه صدقة، فيه إذًا كفارة: العتق، فإن عجز فصيام شهرين متتابعين، هذا هو الواجب، كما قال الله تعالى: وَمَا كَانَ لِمُؤْمِنٍ أَنْ يَقْتُلَ مُؤْمِنًا إِلَّا خَطَأً وَمَنْ قَتَلَ مُؤْمِنًا خَطَأً فَتَحْرِيرُ رَقَبَةٍ مُؤْمِنَةٍ وَدِيَةٌ مُسَلَّمَةٌ إِلَى أَهْلِهِ إِلَّا أَنْ يَصَّدَّقُوا [النساء:92] إلى أن قال سبحانه: فَمَنْ لَمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ تَوْبَةً مِنَ اللَّهِ [النساء:92] فمن قتل خطأً أو شبه عمد فعليه الكفارة، وهي: عتق رقبة مؤمنة مع الاستطاعة، فإذا عجز عن ذلك فإنه يصوم شهرين متتابعين بنص القرآن الكريم، وليس في ذلك إطعام، الإطعام في تحريم المرأة والظهار منها، وفي الوطء في رمضان، هذا هو الذي فيه الإطعام، أو فيه العتق، فإن عجز فصيام شهرين متتابعين، فإن عجز فإطعام ستين مسكينًا، هذا في الظهار من المرأة وتحريمها، وفي الوطء في رمضان. أما القتل فليس إلا كفارتان: العتق والصيام، العتق أولًا لمن قدر عليه، فمن عجز صام شهرين متتابعين ستين يومًا، وليس فيه صدقة، نسأل الله لنا ولك العون، وعليك أن تصوم متى قدرت على ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12911/حكم-الاطعام-في-كفارة-قتل-الخطا-لمن-عجز-عن-الصيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_624/62402.mp3","categories":["الجنايات والحدود"]},{"id":14439,"question":"المستمع (ح. ع. الحميدي) بعث برسالة يقول فيها: حصل علي حادث من مدة عشرة أشهر، ولقد توفيت امرأة بسبب ذلك الحادث، والحادث سببه مشترك بين الطرفين، وقد أمرنا شيخ المحكمة بصيام شهرين متتاليين.الشيخ: أعد.المقدم: يقول: حصل علي حادث من مدة عشرة أشهر، ولقد توفيت امرأة بسبب ذلك الحادث، والحادث سببه مشترك بين الطرفين، وقد أمرنا شيخ المحكمة بصيام شهرين متتالين، وأنا لا أستطيع الصيام؛ فهل يجوز دفع الصدقة عن الصيام؛ لأنني لا أستطيع الصيام؟ وما مقدار الصدقة؟أفيدونا، جزاكم الله خيرًا.","title":"حكم الإطعام في كفارة قتل الخطأ لمن عجز عن الصيام","answer":"الجواب: القتل ليس فيه صدقة، فيه إذًا كفارة: العتق، فإن عجز فصيام شهرين متتابعين، هذا هو الواجب، كما قال الله تعالى: وَمَا كَانَ لِمُؤْمِنٍ أَنْ يَقْتُلَ مُؤْمِنًا إِلَّا خَطَأً وَمَنْ قَتَلَ مُؤْمِنًا خَطَأً فَتَحْرِيرُ رَقَبَةٍ مُؤْمِنَةٍ وَدِيَةٌ مُسَلَّمَةٌ إِلَى أَهْلِهِ إِلَّا أَنْ يَصَّدَّقُوا [النساء:92] إلى أن قال سبحانه: فَمَنْ لَمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ تَوْبَةً مِنَ اللَّهِ [النساء:92] فمن قتل خطأً أو شبه عمد فعليه الكفارة، وهي: عتق رقبة مؤمنة مع الاستطاعة، فإذا عجز عن ذلك فإنه يصوم شهرين متتابعين بنص القرآن الكريم، وليس في ذلك إطعام، الإطعام في تحريم المرأة والظهار منها، وفي الوطء في رمضان، هذا هو الذي فيه الإطعام، أو فيه العتق، فإن عجز فصيام شهرين متتابعين، فإن عجز فإطعام ستين مسكينًا، هذا في الظهار من المرأة وتحريمها، وفي الوطء في رمضان. أما القتل فليس إلا كفارتان: العتق والصيام، العتق أولًا لمن قدر عليه، فمن عجز صام شهرين متتابعين ستين يومًا، وليس فيه صدقة، نسأل الله لنا ولك العون، وعليك أن تصوم متى قدرت على ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12911/حكم-الاطعام-في-كفارة-قتل-الخطا-لمن-عجز-عن-الصيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_624/62402.mp3","categories":["الجنايات والحدود"]},{"id":14569,"question":"ما حكم من ارتكب ذنبًا يقام عليه الحد، وهو لم يبلغ الحلم، هل يسجل هذا الذنب في الصحف، ويعاقب عليه يوم القيامة أم لا؟جزاكم الله خيرًا.","title":"هل يُؤاخذ غير البالغ إذا ارتكب معصية فيها حد؟","answer":"الجواب: إذا كان لم يبلغ الحلم لا يؤخذ بذلك حتى يبلغ الحلم، كما قال ﷺ في الحديث الصحيح: رفع القلم عن ثلاثة: عن النائم حتى يستيقظ، وعن المجنون حتى يفيق، وعن الصغير حتى يبلغ من فعل معصية وهو صغير ضرب أحد أو سب أحد أو سرق، أو ما أشبه ذلك، لا يؤخذ من جهة الله؛ لأنه غير بالغ، لكن على ولي أمره وعلى المسؤولين منعه من التعدي، يؤدب حتى يستقيم مثلما أمر النبي ﷺ ضرب من بلغ عشرًا إذا تخلف عن الصلاة، هكذا إذا فعل ما لا ينبغي يؤدب إذا تعدى على أحد سرق أو ضرب أحدًا بغير حق أو سب أحد يؤدب حتى يعتاد الخير ويتعلم الخير، لكنه لا يؤخذ بهذا يوم القيامة؛ لأنه غير بالغ، وإنما على أوليائه أن يعلموه ويؤدبوه وينصحوه ويحذروه من التعدي على المسلمين أو فعل المعاصي التي حرمها الله، نعم.","link":"https://binbaz.org.sa/fatwas/13066/هل-يواخذ-غير-البالغ-اذا-ارتكب-معصية-فيها-حد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_556/55607.mp3","categories":["الجنايات والحدود"]},{"id":14781,"question":"المستمعة (ز. ع. س) من اليمن، بعثت تسأل وتقول: لقد حدث مرة أن استلفت جارة لي من عندي زجاجة مملؤة بالغاز، وحدث يومًا أنني بحاجة إلى الغاز بمثل ما استلفته مني تلك الجارة، فذهبت إليها وطلبت منها ذلك، فأشارت إلى إناء فيه غاز تحت سرير لها، فقالت: خذي لك منه ما تحتاجين، فملأت من ذلك الإناء زجاجتي، وأرجعت الإناء مكانه، وكان هناك طفل على السرير نائمًا فاستيقظ وشرب من الغاز من ذلك الإناء الذي تحت السرير، فرأته أمه، وصاحت به بصوت مرتفع، فخاف الطفل، ودخل الغاز في أنفه فاختنق ومات، وزعمت أمه أني أنا السبب في موته، فما الحكم في هذا؟ وهل علي شيء من ذلك؟ أفيدوني، جزاكم الله خيرًا.","title":"ما يلزم من صاحت على طفلها لشربه الغاز فختنق فمات؟","answer":"الجواب: إذا كان الواقع كما ذكرت، فليس عليك شيء، وليس عليها شيء، هي صاحت عليه حتى يسلم، وأنت ما عليك شيء، كلاكما ليس عليه شيء تم أجله، والحمد لله، الله المستعان. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13270/ما-يلزم-من-صاحت-على-طفلها-لشربه-الغاز-فختنق-فمات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_490/49018.mp3","categories":["الجنايات والحدود"]},{"id":15075,"question":"هذه رسالة وردتنا من المستمعة جوهرة محمد الطريقي، من بريدة، رسالتها طويلة جدًا، لكن ملخصها تقول:إن لها بنتًا تبلغ من العمر سنة ونصف، وذات يوم ذهبت إلى أهلها زائرة كالعادة، منذ تزوجت في مزرعتهم، والمزرعة فيها بركة كبيرة، وتصب في بركة صغيرة، وذكرت قصة السباحة فيها للأطفال مع أولاد الأهل، ثم قالت: فقدنا البنت، وبعد البحث عنها جاءت بها أختي على يديها، وإذا بها قد أغمي عليها، فذهبت مثلًا أزيل ما فيها من ماء أو كذا أو أجعلها تنصل على الرأس، المهم أن الفتاة قد توفيت، وتقول: هل يجب علي صيام أم غير واجب؟ وإذا كان الصيام واجبًا فهل أصوم شهرين متتابعين دون انقطاع إذا جاءت العادة الشهرين، أم أفطر إذا جاءت العادة... إلى آخره؟","title":"ما حكم من كان إهمالها سببًا في موت ابنتها؟","answer":"الجواب: الأحوط لك الصيام -أيها الأخت في الله-، الأحوط لك الكفارة؛ لأنك فرطت في تركها مع الصبية الصغار عند البركة التي فيها الماء، وفيها الخطر، ومثل هذه عمر سنة ونصف ينبغي ألا تترك، بل ينبغي أن يحافظ عليها، وأن تكون بيد ثقة من الرجال أو النساء، حتى يحافظ عليها.  أما إهمالك لها حتى ذهبت إلى الماء، وأنت تعرفين البركة، وأنها موجودة، فهذا تفريط، ينبغي لك أن تكفري بعتق رقبة مؤمنة، فإن لم تجدي فصيام شهرين متتابعين، ووجود الحيض لا يضر، ولا يقطع الصيام، إذا أفطرت بقدر أيام الحيض فقط إذا طهرت بادرت بالصيام، فإنه لا يقطع الصيام، ويستمر الصيام شهرين متتابعين، والحيض عذر شرعي لا يقطع الصيام، لكن بشرط أن تبادري بالصوم من اليوم الذي يلي يوم الطهر، حتى تكملي ستين يومًا، نعم.","link":"https://binbaz.org.sa/fatwas/13585/ما-حكم-من-كان-اهمالها-سببا-في-موت-ابنتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_664/nour_66402.mp3","categories":["الجنايات والحدود","قضايا المرأة"]},{"id":15225,"question":"يقول هذا السائل: رجل كان في حياته يسرق أموال الناس، ولكنه الآن تاب إلى الله ، ولا يعرف هؤلاء أصحاب الأموال التي سرق منهم، وإذا عرفهم قد يتسبب له بعض الإحراجات، فماذا يفعل الآن يا سماحة الشيخ؟ وهل تقبل منه التوبة؟ وماذا يعمل بتلك الأموال التي قد سرقها من هؤلاء الناس؟","title":"الواجب على السارق بعد التوبة","answer":"الجواب:  عليه التوبة إلى الله، والندم والإقلاع من ذلك، والحذر من السرقة مستقبلًا، والاستغفار من ذلك، والإكثار من العمل الصالح، والعزم الصادق أن لا يعود هذه التوبة، يندم على الماضي، ويقلع من ذلك، ويعزم عزمًا صادقًا أن لا يعود، ويكثر من استغفار الله، ومن العمل الصالح، كما قال الله سبحانه: وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى [طه:82] قال تعالى: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31] وعليه رد الأموال إلى أصحابها إذا عرفهم، عليه أن يردها إليهم بالطريقة التي تمكن، ولو من غير أن يعلموا أنها منه، يرسلها إليهم بواسطة من يرى حتى يوصلها إليهم، من طريق البريد، أو من غير طريق البريد، ولا يجوز له عدم ردها، بل يجب ردها إذا عرفهم، بأي طريقة على وجه لا يعلمون أنها منه، يعطيها إنسان يقول: سلمها لهم، قل لهم: إن هذه أعطانيها إنسان يقول: إنها حق لكم عنده وأعطانيها أسلمها لكم، والحمد لله. أما إن جهلهم، فإنه يتصدق بها، يعطيها الفقراء بالنية عن أصحابها، يتصدق بالأموال التي سرقها بالنية عن أصحابها، كلها، لا يخلي شيء، أما إذا عرفهم ولو بعيدين، ولو كانوا بعيدين يوصلها إليهم بالطريقة التي تصلهم بها من دون حاجة إلى أن يعلموا أنها منه، بواسطة من يرى من الناس الذين يوصلونها من الثقات، ولا يبينون أنها منه، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13720/الواجب-على-السارق-بعد-التوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_565/56504.mp3","categories":["الجنايات والحدود"]},{"id":15298,"question":"هذه رسالة من المستمع (م. م. المختار) من مدينة الجبيل الصناعية، يقول: ما حكم من أخذ مالًا حرامًا من عدة أشخاص؛ وذلك قبل أن يبلغ سن الرشد، وبعدما بلغ سن الرشد تاب إلى ربه واستغفره، ويريد أن يرجع المال لأصحابه، وهو لا يعرف كم مقدار ذلك المبلغ، ولكنه اجتهد في تقديره، وبدون أن يظلم أحدًا منهم -إن شاء الله-، وأيضًا يوجد شخص من هؤلاء الأشخاص لا يعرف اسمه، ولا مكان إقامته، فهل يتصدق به عنه أم لا؟أفيدونا، أفادكم الله.","title":"ما يلزم من سرق مالًا ولا يعرف بعض أصحابه؟","answer":"الجواب: أما من عرفهم فإنه يسلم إليهم حقهم، حسب اجتهاده، وحسب ما يغلب على ظنه، ويستبيحهم ويسألهم العفو عما مضى، وعما حصل.  وأما من جهل ولم يعرف هل هو حي أو ميت؟ ولم يعرف ورثته، فإنه يتصدق به عنه بالنية، عن صاحب الحق، مع التوبة إلى الله، والصدق في ذلك، وتبرأ ذمتك -إن شاء الله- بذلك، نعم.","link":"https://binbaz.org.sa/fatwas/13816/ما-يلزم-من-سرق-مالا-ولا-يعرف-بعض-اصحابه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_676/nour_67603.mp3","categories":["الجنايات والحدود"]},{"id":15304,"question":"هذان سؤالان من المستمع (س. م) من جيزان، سؤاله الأول يقول: لو أن شخصًا سرق أو ارتكب كبيرة يترتب عليها حد شرعي، ثم تاب إلى الله، ولم يقم عليه الحد، فهل يغفر الله له، أم لا؟","title":"هل يُغفر لمن تاب من كبيرة ولم يقم عليه الحد؟","answer":"الجواب: التوبة كافية، إذا فعل المسلم معصية فيها حد لله كالزنا أو السرقة، ثم تاب إلى الله  فالتوبة تجب ما قبلها، ولكن عليه أن يؤدي المال الذي سرقه، عليه أن يوصله إلى صاحبه بالطرق التي تمكنه، ولا حاجة إلى أن يتصل بصاحبه، أو يقام عليه الحد، متى ستر الله عليه فالله -جل وعلا- يتوب على التائبين، وليس من شرط ذلك أن يعلن معصيته حتى يقام عليه الحد، من تاب تاب الله عليه، وإن لم يقم عليه الحد، لكن متى بلغ ولي الأمر أمر السرقة، أو أمر الزنا وجب عليه إقامة الحد؛ لما جاء في الحديث: إذا بلغت الحدود السلطان فلعن الله الشافع والمشفع وفي الحديث الآخر: ما بلغني من حد فقد وجب. فالمقصود: أنه متى رفعت الحدود إلى السلطان وجبت إقامتها؛ ولهذا لما سرقت امرأة من قريش يوم الفتح وطلب بعض الناس من النبي ﷺ ألا يقيم عليها الحد، وتوسطوا بأسامة بن زيد أن يشفع، فشفع أسامة  في ذلك، فغضب النبي ﷺ وقال: أتشفع في حد من حدود الله، ثم خطب الناس، فحمد الله، وأثنى عليه، ثم قال: إنما هلك من كان قبلكم أنهم كانوا إذا سرق فيهم الشريف تركوه، وإذا سرق فيهم الضعيف أقاموا عليه الحد، وايم الله لو أن فاطمة بنت محمد سرقت لقطعت يدها. فبيَّن -عليه الصلاة والسلام- أن الحدود يجب أن تقام على الشريف وغيره، والصغير والكبير، ممن بلغ التكليف، ولا يجوز التراخي فيها بعد بلوغ السلطان، ولا تجوز الشفاعة فيها بعد بلوغ السلطان، أما قبل ذلك فيما بين الناس إذا تعافوا فيما بينهم وتسامحوا ولم يرفعوها للسلطان فلا حرج، والتوبة تجب ما قبلها. فإذا جاء السارق إلى المسروق منه، وقال: سامحني هذا مالك، ولا ترفع بأمري، واصطلح معه على ذلك، وتسامح المسروق منه، فلا حرج في ذلك، وقد جاء في الحديث الصحيح أن صفوان بن أمية سرق منه إنسان رداءه وهو مضطجع عليه، فأمسكه صفوان ورفعه إلى النبي ﷺ فأمر النبي ﷺ أن تقطع يده، فقال صفوان: «يا رسول الله، قد سامحته، ردائي له، قال: هلا كان ذلك قبل أن تأتيني به يعني: لو سامحته قبل ذلك لا بأس، أما بعد المجيء بالسارق ورفعه للسلطان فلا مسامحة، بل لا بد من القطع، وهكذا في الزنا، هكذا في اللواط، والعياذ بالله، وما أشبه ذلك من الحدود، نعم.","link":"https://binbaz.org.sa/fatwas/13813/هل-يغفر-لمن-تاب-من-كبيرة-ولم-يقم-عليه-الحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_682/nour_68203.mp3","categories":["الجنايات والحدود"]},{"id":15325,"question":"أول سؤال نطرحه على فضيلته، ورد إلينا من المستمع (س. ع. ع) من السودان، يقول فيه: أعلمكم بأن أحد أصدقائي كان يعمل مع شخص ما في مطعم، وقام بسرقة بعض نقوده؛ وذلك بدون علم من صاحب هذا المطعم، ولكنه في النهاية تاب إلى ربه، وسمع أن هذا الشخص قد توفي، ويريد أن يرجع هذه النقود، مع العلم أنه لا يعرف مكان أهله، أفيدونا هل يجوز له أن يتصدق بها على نية صاحب المطعم أم لا؟ وفقكم الله.","title":"كيفية رد المال المسروق إذا مات صاحبه","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فهذا الذي سرق النقود من صاحب المطعم الواجب عليه التوبة إلى الله ، وإذا كان قد تاب فالحمد لله على ذلك، أما النقود فإن عرف صاحبها، أو عرف الورثة، فإنه يلزمه أن يؤديها إلى الورثة إذا كان صاحبها قد مات، وعليه أن يبحث ويجتهد حتى يوصلها إلى الورثة، فإن عجز ولم يجد سبيلًا إلى معرفة الورثة، فإنه يتصدق بذلك بالنية عن صاحب المطعم، يتصدق بها عنه، والله -جل وعلا- ينفعه بها إذا كان مسلمًا ينفعه بهذه الصدقة، وهذا هو طريق البراءة من ذمته، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13823/كيفية-رد-المال-المسروق-اذا-مات-صاحبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_677/nour_67701.mp3","categories":["الجنايات والحدود"]},{"id":15498,"question":"هذه السائلة (م. م) تقول: سماحة الشيخ، تذكر بأنها فتاة تبلغ من العمر عشرون سنة، تقول: وقد سرقت من زوجة أبيها مبلغ ثلاثة آلاف ريال تقريبًا، وكانت تبلغ من العمر أربع عشرة سنة، وقد هداها الله  وتابت مما فعلته من ذلك، ومضى على ذلك ما يقارب من ست سنوات، تقول: سماحة الشيخ، ماذا أفعل؟ لأنني لا أستطيع أن أرد المال الذي أخذته من زوجة أبي؛ لأنني يتيمة الأب، وما عندي ما يكفي، ولا أعتبر ذلك -إن شاء الله- إلا خطأً مني وقد تبت، فماذا يلزمني؟مأجورين.","title":"ما يلزم من تابت من سرقة مال ولا تستطيع رده؟","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فالواجب عليك رد الدراهم إلى صاحبتها، واستباحتها، قولي: سامحيني، هذا الواجب عليك، اجتهدي حتى تردي إليها المال، هذا هو الواجب عليك، وإذا كنت لا تستطيعين -قولي- أخبريها لعلها تسامحك، فإذا أخبرتيها وسامحتك وأباحتك فلا بأس، قولي: إني أخطأت وأنا صغيرة وأخطأت، أرجو أن تسامحيني، أنا ما عندي فلوس أعطيك، وإذا سامحتك فلا بأس، وإلا فالواجب عليك الحرص على أدائها إليها ولو بالاستدانة إذا كان لك وفاء، إذا كان عندك وفاء، فاقترضي وأديها إليها، ثم سلمي القرض لصاحبه، إذا كنت تستطيعين القضاء، نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/14026/ما-يلزم-من-تابت-من-سرقة-مال-ولا-تستطيع-رده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_691/nour_69101.mp3","categories":["الجنايات والحدود","قضايا المرأة"]},{"id":15839,"question":"حسن يحيى من أبها يقول في هذا  سماحة الشيخ، أنا إنسان قدر الله علي بحادث سير، وقد كان معي أربعة أشخاص توفوا جميعًا، ماذا يجب علي، فأنا أعلم بأن الرقبة عليها صيام شهرين متتابعين، فهل الأربعة لهم حكم الواحد، أم أصوم عن كل رقبة شهرين متتابعين؟","title":"حكم من وقع عليه حادث فمات بسببه عدة أشخاص","answer":"الجواب: إذا كان الحادث بأسباب تفريطك فعليك الصوم عن كل رقبة شهرين ثمانية أشهر إلا إذا وجد عدة رقاب عبيد مملوكين، ملكًا معروف، فعن كل نفس رقبة تعتق، أما عند عدم العتق فعليك أن تصوم عن كل نفس شهرين إذا كنت قد حملت ذلك قد تسببت في ذلك، نعم. المقدم: يلزمه ثمانية أشهور؟\nالشيخ: ثمانية أشهر، كل شهرين لحالها، كل شهرين متتابعة وحدها.\nالمقدم: إذا صادفه رمضان يا شيخ وهو يصوم؟\nالشيخ: يفطر رمضان، ويواصل، إذا كمل شعبان ثم يصل شوال به، ويجزئ؛ لأن هذا عذر شرعي، يكمل شهرين ستين يومًا، إذا فصل رمضان، أو فصل العيد لا يضر، وإن صامها قبل رمضان أو بعد رمضان يكون أحسن حتى لا يجتمع ثلاثة شهور؟\nالمقدم: طيب.. يا شيخ، إذا نوى رمضان، والشهر الذي بعده يا شيخ؟\nالشيخ: ما يجزئ؛ لا بد من شهرين غير رمضان. المقدم: غير رمضان، أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14430/حكم-من-وقع-عليه-حادث-فمات-بسببه-عدة-اشخاص","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_575/57531.mp3","categories":["الجنايات والحدود"]},{"id":15866,"question":"تقول: امرأة نامت، وطفلها الرضيع في حجرها، ولم يكن مريضًا، وفي الصباح فوجئت الأم بأن طفلها قد مات، ولا تعرف إن كانت انقلبت عليه دون أن تحس بذلك، أو أنها عندما كانت ترضعه نامت قبل أن تخرج الثدي من فمه، فهل عليها أن تصوم شهرين متتابعين؟وإن كان عليها صيام الشهرين، فكيف تستطيع ذلك والدورة تأتي كما تعلمون وتقطع الصيام، وجهوها جزاكم الله خيرًا، وهل إذا انقضت الدورة تستأنف الصيام وحينئذٍ لا تؤثر الدورة على التتابع؟وجهوها جزاكم الله خيرًا.","title":"حكم الأم إذا شكت في قتل رضيعها خطأ","answer":"الجواب: إذا كانت لا تعلم فليس عليها شيء، لكن الاحتياط أن تصوم؛ لأن الظاهر أنه مات بأسبابها، إما أن تكون نامت عليه، أو أنه شرغ باللبن؛ لأنها نامت والثدي في فمه، فالأظهر -والله أعلم- أنه مات بأسبابها، فإذا احتاطت، إذا احتطت -أيها الأخت في الله- وأعتقت رقبة، يوجد رقاب تعتق في بعض أفريقيا، تكتبي لنا، ونشتري لك، يوجد رقاب تعتق بقيمة عشرة آلاف تقريبًا، وإذا صمت واحتطت لدينك فهو أفضل وأحوط؛ لأن الظاهر من هذا الواقع أنك السبب، ولا يضرك قطع الدورة، الدورة إذا جاءت أفطري، وإذا ذهبت بادري بالصوم، من حين تغتسلين تصومين اليوم الذي يليه، تكملين ستين يومًا، صيام ستين يومًا، والأيام التي تخللتها بالدورة لا تضر، لكن لا بد تكملين ستين يومًا متتابعة صومًا بإسقاط أيام الدورة منها، وعدم احتسابها، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14457/حكم-الام-اذا-شكت-في-قتل-رضيعها-خطا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_744/nour_74407.mp3","categories":["الجنايات والحدود"]},{"id":16054,"question":"بعد هذا رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين له قضية يقول فيها: وقع علينا حادث مروري في شهر رمضان أنا وأحد زملائي، ونتج عن ذلك وفاة زميلي الذي كان يرافقني، وأنا أغمي علي، ولم أعلم عن وفاة زميلي -رحمة الله عليه- إلا بعد مرور أسبوعين، وبعد ما طلعت من المستشفى ذهبت إلى أهله، وطلبت السماح منهم، وكذلك طلبت السماح من خاله الأكبر حيث كان موجودًا، ثم سامحوني -جزاهم الله خيرًا- ولم يطلبوا مني شيئًا، وكان ذلك في يوم عشرين من رمضان، وقد أفطرت عشرة أيام، وأنا في المستشفى؛ لذا أرجو من سماحتكم كيف يكون الحكم بالنسبة لي؟ جزاكم الله خيرًا.","title":"كفارة من تسبب في وفاة شخص بحادث","answer":"الجواب: إذا كان موته بسببك؛ فعليك الكفارة لسرعة، أو نعاس، أو غير هذا من الأسباب التي حصل بسببها الحادث، فعليك الكفارة وهي عتق رقبة مؤمنة، فإن لم تستطع؛ فعليك أن تصوم شهرين متتابعين، شهرين متتابعين، ستين يومًا، لقول الله : وَمَا كَانَ لِمُؤْمِنٍ أَنْ يَقْتُلَ مُؤْمِنًا إِلَّا خَطَأً وَمَنْ قَتَلَ مُؤْمِنًا خَطَأً فَتَحْرِيرُ رَقَبَةٍ مُؤْمِنَةٍ وَدِيَةٌ مُسَلَّمَةٌ إِلَى أَهْلِهِ إِلَّا أَنْ يَصَّدَّقُوا [النساء:92] إلى أن قال سبحانه: فَمَنْ لَمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ تَوْبَةً مِنَ اللَّهِ [النساء:92] الآية، فإذا كان أهله قد سمحوا عن الدية فجزاهم الله خيرًا. أما الكفارة فعليك أن تؤدي الكفارة، وهي عتق رقبة مؤمنة، فمن لم يستطع؛ صام شهرين متتابعين -ستين يومًا- نسأل الله لك العون والتوفيق. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14679/كفارة-من-تسبب-في-وفاة-شخص-بحادث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_711/nour_71104.mp3","categories":["الجنايات والحدود"]},{"id":16269,"question":"هذه السائلة أم إبراهيم كتبت هذا السؤال، تقول: سماحة الشيخ! كان لي ولد في الثالثة عشرة من عمره، لديه حمام يربيها في الدور الثاني في الدرج، وخرج بالحمام، لكن المكان الذي وضع فيه الحمام خطر، وإخوته، وأولاد العم يصعدون إليه، وكنت أريد أن أحدثه بأن ذلك المكان خطر، لكنني لم أتحدث معه، وجلس عشرة أيام، وطاح من المكان الذي وضع فيه الحمام، ومات، هل مات بسببي؟ سؤالي يا سماحة الشيخ، وهل علي شيء في ذمتي؟ وله سبعة شهور، وأنا أصلي عنه، هل هذا جائز؟","title":"حكم الولد إذا مات دون سبب من أمه والصلاة عنه","answer":"الجواب: ليس عليك شيء، والحمد لله؛ لأنك ما تسببت في موته، ولا تصلي عنه، ليس لك الصلاة عنه، ما دام صعد إلى الحمام وهو إنسان مميز. المقصود: أنه ليس عليك شيء؛ لأنك ما تسببت أنت في شيء، نعم.","link":"https://binbaz.org.sa/fatwas/14956/حكم-الولد-اذا-مات-دون-سبب-من-امه-والصلاة-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_581/58107.mp3","categories":["الجنايات والحدود"]},{"id":16465,"question":"سؤاله الأخير يقول فيه: كثير من السائقين يتجاوزون السرعة المحددة من قبل المرور، بل إن بعضهم يكمل العداد، فهل من يموت بسبب هذه السرعة يعتبر قاتلًا لنفسه؟","title":"ما حكم من يموت بسبب زيادة السرعة؟","answer":"الجواب: ليس للسائق أن يتعدى الحد المحدود، بل يجب عليه أن يتقيد بذلك، أو يخفض منه احتياطًا، أما الزيادة فلا تجوز له، وإذا فعل ذلك؛ فهو ضامن، ومتعدٍ، ويستحق التأديب والتعزير؛ لأنه بفعله ذلك عرّض نفسه ومن معه للخطر، فلا يجوز له ذلك، حتى ولو كان ليس معه أحد؛ لأنه إذا فعل ذلك فقد عرّض نفسه للخطر. فالواجب عليه ترك التهور، وترك الزيادة على الشيء المحدود له في السير، والواجب عليه أيضًا عدم تجاوز الإشارة، يقف عند الإشارة، ولو ظن أن ما هناك أحد، يجب أن يقف عند الإشارة، قد يظن، ويخطئ ظنه، يقف عند الإشارة لا يتجاوز الإشارة، ولا يتجاوز الحد المحدود في السير، ومن فعل ذلك؛ استحق التأديب من ولاة الأمور، نعم. المقدم: جزاكم الله خيرًا، من قتل وهو مسرع السرعة الزائدة عن الحد المعروف، هل يعتبر قاتلًا لنفسه؟ الشيخ: لا شك أنه مشارك في قتل نفسه، ولا شك أنه في هذا ظالم، ومتعدٍ، ويعتبر قاتلًا نفسه من حيث تعاطيه أسباب القتل، والنبي ﷺ يقول: من قتل نفسه بشيء؛ عذّب به يوم القيامة فالتعدي في السير، والتهور في السير زيادة على القدر المحدود، لاشك أنه مساعدة في قتل النفس، وظلم وجريمة يستحق عليها صاحبها العقوبة. فالواجب على السائقين، سواء كانوا في سيارات خصوصية، أو في سيارات الأجرة، الواجب على الجميع التقيد بما حد لهم، أو الخفض عنه بعض الشيء؛ حتى يتباعدوا عن الخطر، وليس لهم الزيادة، ولا يتجاوزون الإشارة؛ لما في ذلك من الخطر، والعدوان على النفس، وعلى الغير، نعم. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/15202/ما-حكم-من-يموت-بسبب-زيادة-السرعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_813/nour_81307.mp3","categories":["الجنايات والحدود"]},{"id":16637,"question":"من محافظة مرسى مطروح في جمهورية مصر العربية المستمع (ف. أ. ع) رسالة يقول فيها: أقوم بقيادة سيارة نقل ثقيل، وصدمت طفلًا، وتصالحت مع أهله، ودفعت الدية، وأفتاني بعض الإخوة بصيام شهرين كفارة، فهل هذه الفتوى صحيحة، مع العلم أنني -كما قلت- سائق، ويصعب علي الصوم نظرًا لمشقة عملي كسائق نقل ثقيل، أفيدوني جزاكم الله خيرًا.","title":"كفارة قتل الخطأ","answer":"الجواب:  نعم، عليك عتق رقبة، عتق رقبة مؤمنة إذا تيسر ذلك، واستطعت ذلك، فإذا لم يتيسر؛ فعليك أن تصوم شهرين متتابعين، ستين يومًا، في الوقت الذي تستطيع، يبقى في ذمتك حتى تستطيع في وقت الإجازة، في وقت تستريح فيه عن السياقة، في الوقت الذي تستطيع فيه الصيام، هذا واجب عليك بنص القرآن الكريم؛ لأن قتلك خطأ، وقتل الخطأ يوجب عليك الكفارة، عتق رقبة مؤمنة، فإن عجزت؛ تصوم شهرين متتابعين، وليس في ذلك إطعام، ليس في ذلك إلا العتق، وعند العجز يكون فيه الصيام، يكون صوم شهرين متتابعين، ستين يومًا، نسأل الله لك العون والتوفيق. المقدم: اللهم آمين، جزاكم الله خيرًا، إذًا لابد من الصيام سماحة الشيخ! الشيخ: لابد من الصيام، نعم، إن لم يتيسر العتق، يوجد في موريتانيا، وبعض البلاد الإفريقية يوجد فيها عبيد يباعون، فإذا وصى من يشتري له من الثقات ووجد، طيب. المقدم: وإن لم يتمكن من العتق فلابد من الصيام، وإن كان سائقًا؟ الشيخ: ولو كان سائقًا، نعم. المقدم: بارك الله فيكم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15370/كفارة-قتل-الخطا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_716/nour_71614.mp3","categories":["الجنايات والحدود"]},{"id":16647,"question":"سماحة الشيخ! إحدى الأخوات بعثت تسأل وتقول: كان لدي طفل في الشهر السادس أصيب بعين، ثم مرض لمدة شهر.الشيخ: كان.المقدم: كان لدي طفل في الشهر السادس، أصيب بعين، ثم مرض لمدة شهر، ثم ازداد مرضه في الأسبوع الأخير، وكنت أسهر معه طوال الليل، وفي إحدى الليالي وضعته بجانبي، وأنا مضطجعة على جانبي، وغلبتني عيني، ثم استيقظت فزعة، فأخذت طفلي، فإذا هو في النفس الأخير، ثم أسلم الروح لبارئها، وعندما استيقظت كنت على جنبي الذي اضطجعت عليه، ولم أنقلب، ولم أتحرك منه، وبعد سنوات عدة قيل لي: إنه يجب عليك صيام شهرين متتابعين؛ كفارة القتل الخطأ، فهل يجب علي صيام الشهرين، وإذا لم أستطع الصيام نظرًا لكبر سني، هل يمكن أن أتصدق، أو أن أفعل شيئًا آخر؟ أفيدوني جزاكم الله خيرًا، علمًا بأني أبلغ من العمر الآن ستين عامًا.","title":"ما يلزم الأم إذا توفي طفلها دون سبب منها؟","answer":"الجواب: إذا كان الواقع هو ما ذكرت؛ فليس عليك شيء والحمد لله، لا صيام، ولا غيره؛ لأنك لم تقتليه، هذا أجله، هو مريض، وجاءه أجله، أما إذا كنت تعلمين أنك غطيتيه، نمت عليه، يعني صار صدرك عليه حتى مات، أو فعلت شيئًا يوجب موته؛ فعليك عتق رقبة مؤمنة، عتق عبد وإلا عبدة، فإن عجزت؛ صومي شهرين متتابعين، ستين يومًا، لكن مادام الواقع كما ذكرت فليس عليك شيء، لأنك -الحمد لله- لم تقتليه، بل جاءه أجله، فأنت -بحمد الله- ليس عليك شيء. وأسأل الله أن يعظم أجرك فيه، ولا ينبغي أن توسوسي، أنت بحمد الله ليس عليك شيء، مادام الواقع مثلما ذكرت، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15380/ما-يلزم-الام-اذا-توفي-طفلها-دون-سبب-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_717/nour_71710.mp3","categories":["الجنايات والحدود"]},{"id":16860,"question":"تقول: توفي لي أخ شاب مطيع لله، ومؤمن، قتل، لكنه قتلٌ غير عمد، إذ أراد أن يبعد السلاح عن صديقه، فأصابته، وتوفي، فهل هو شهيد؛ علمًا أنه قتل خارج بلدته، وبعيدًا عن أهله؟","title":"حكم من قتل نفسه خطأ","answer":"الجواب: ترجى له الشهاده؛ لأنه لم يتعمد، قتل نفسه، فأشبه المقتول ظلمًا، المقتول خطأً، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15607/حكم-من-قتل-نفسه-خطا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_764/nour_76408.mp3","categories":["الجنايات والحدود"]},{"id":16864,"question":"من المستمعة (م. إبراهيم) من جدة، الهنداوية، رسالة تذكر فيها قضية تقول: لقد كان عندي طفل صغير، وأصيب بمرض الحصبة، ووصف بعض الناس لي دواءً شعبيًا، فعملت ذلك الدواء، وهو خليط من البلح، والدخن، والثوم، ثم إني أسقيته للطفل، وأثناء عملي ذلك؛ خرج الماء من أنفه؛ ثم إنه توفي في اللحظة، وأنا من تلك اللحظة أعاني كثيرًا، وأقول: أنا السبب في موته، وأنا على يقين بأن المميت هو الله، ولكن لكل شيء سببًا، فأنا كنت السبب في موته، فهل علي ذنب في موته؟ أم أني بريئة من ذنبه؟ وفي حيرة من أمري حتى تفيدوني، وتحلو قضيتي، جزاكم الله خيرًا.","title":"حكم من أعطت طفلها دواءً فمات بسببه","answer":"الجواب: إذا كانت التي وصفت هذا الدواء امرأة معروفة بالعلاج، وأنها ناجحة في علاجها، مجربة؛ فلا شيء عليك، أما إذا كانت غير معروفة بالعلاج، غير معروفة بالنجاح في علاجها؛ فعليك الكفارة: وهي عتق رقبة مؤمنة؛ فإن عجزت؛ تصومي شهرين متتابعين... ستين يومًا.. ونسأل الله أن يجبر مصيبتك، وأن يغفر ذنبك. المقصود: إن كانت المرأة التي وصفت العلاج امرأة معروفة بالطب.. بالعلاج، ناجحة مجربة ثقة؛ فلا شيء عليكِ إذا كنت ما فعلت ما قالت فقط، ولم تزيدي شيئًا، أما إن كنت غيرت، ولم تلتزمي بما قالت، أو كانت غير معروفة بالعناية بالعلاج، وغير معروفة بالنجاح في العلاج؛ فأنت السبب، وعليك الكفارة: وهي عتق رقبة مؤمنة، ذكرًا، أو أنثى، فإن لم يتيسر ذلك؛ فصيام شهرين متتابعين، ستين يومًا، وعليك الدية على العاقلة، إن طلب الورثة الدية، فالدية على العاقلة على العصبة إن طلب الورثة الدية، وإن لم يطلبوا؛ فلا شيء عليك، فلا شيء في ذلك، إنما المهم الكفارة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15616/حكم-من-اعطت-طفلها-دواء-فمات-بسببه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_764/nour_76410.mp3","categories":["الجنايات والحدود"]},{"id":17011,"question":"هل على الإنسان غير المكلف -غير البالغ- صيام شهرين متتابعين كفارة لقتل الخطأ، وذلك لأنه تسبب في قتل أخيه الأصغر بواسطة السيارة، حيث أنه يبلغ من العمر خمس عشرة سنة، ولم يخط شاربه بعد؟","title":"حكم كفارة قتل الخطأ على غير المكلف","answer":"الجواب: إذا كان قد بلغ خمسة عشر سنة فهذا عليه كفارة؛ لأنه بالغ، يصوم شهرين، أو يعتق، والعتق مقدم إذا تيسر العتق فهو مقدم، فإن عجز عن العتق؛ صام شهرين متتابعين عن قتل الخطأ. المقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15789/حكم-كفارة-قتل-الخطا-على-غير-المكلف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_720/nour_72009.mp3","categories":["الجنايات والحدود"]},{"id":17069,"question":"سماحة الشيخ! هذا السائل يقول: بعض الناس عندما يقال: فلان مات، يقول للحاضرين: حللوه، أو أبيحوه، هل الأفضل أن يقول مثل ذلك؟ أو أن يقول: ادعوا له بالمغفرة؟","title":"ما المشروع أن يقال إذا مات الشخص؟","answer":"الجواب: السنة أن يقال: استغفروا له، ادعوا له بالمغفرة، ترحموا عليه، أما إذا كان ما بينهم وبينه شيء ما في حاجة للتحليل، أما إذا كان يعرف أن بينهم حسابات، ومنازعات، إذا طلب منهم تحليله، ومسامحته جزاه الله خيرًا. نعم. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/15874/ما-المشروع-ان-يقال-اذا-مات-الشخص","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_588/58809.mp3","categories":["مسائل متفرقة في الجنائز","الجنايات والحدود"]},{"id":17767,"question":"سماحة الشيخ هذه سائلة للبرنامج كتبت هذا السؤال بأسلوبها الخاص وتذكر في رسالتها بأن لديها بنت عمرها أربع سنوات وكانت منذ ولادتها وهي مصابة بالشلل، وقد نومت في المستشفى، وتقول هذه السائلة: وفي يوم وفاتها كانت في غيبوبة تامة منذ الصباح ولم تأكل شيئًا منذ الصباح، ولقد قمت بإعطائها بعض الحليب خوفًا عليها من الجوع، وأول ما شربت هذا الحليب طلع من فمها وفارقت الحياة، وفي الحقيقة بأنني لم أعرف أنها ماتت إلا بعد ما شاهدها الطبيب؛ لأنني لم أشاهد أحدًا يموت أمامي سوى ابنتي هذه الصغيرة، وقد حدث هذا قبل ستة عشر سنة تقريبًا فهل علي كفارة في ذلك علمًا بأنني لا أريد أن أعطيها هذا الحليب إلا لخوفي عليها من الجوع، أرجو إفادتي يا سماحة الشيخ؟","title":"حكم من سقت طفلتها حليبًا فماتت","answer":"الجواب: ليس عليك شيء أنت محسنة، والله يقول سبحانه: مَا عَلَى الْمُحْسِنِينَ مِنْ سَبِيلٍ[التوبة:91]، وأنت بإعطائها الحليب محسنة فلا حرج عليك ولا بأس أجلها تم، والحمد لله. نعم.\nالمقدم: جزاكم الله عنا وعن المسلمين خير الجزاء.","link":"https://binbaz.org.sa/fatwas/16757/حكم-من-سقت-طفلتها-حليبا-فماتت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_778/nour_77804.mp3","categories":["الجنايات والحدود"]},{"id":17854,"question":"تقول: والدتي لها طفلةٌ تبلغ من العمر سنتين، توفيت غرقًا، وتقول والدتي: هل علي شيءٌ في ذلك؟ خصوصًا وأنها أغلقت الباب، والطفلة خارج المنزل، ظنًا من الأم أن الطفلة داخل المنزل، وبعد فترة اكتشفت الأم أن ابنتها خارج المنزل، وعندما ذهبت للبحث عنها، وجدتها قد فارقت الحياة غرقًا، فإذا كان عليها شيءٌ في ذلك؛ فما هو؟ جزاكم الله خيرًا.","title":"ما يلزم من ماتت ابنتها من غير إهمال منها؟","answer":"الجواب: إذا كان قد تسببت في غرقها؛ بأن جعلتها عند محلٍ مكشوف، خزانٍ مكشوف، أو حوضٍ من الماء مكشوف، وليس عندها أحد؛ فإنها تضمنها ... ديتها.\nوأما إذا كان المحل بعيد، وليس حولها، ولكن قدر أنها اندرجت إليه، وذهبت إليه، فلا عليها شيء، ليس عليها ضمان في هذا. نعم.\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16847/ما-يلزم-من-ماتت-ابنتها-من-غير-اهمال-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_758/nour_75808.mp3","categories":["الجنايات والحدود"]},{"id":17972,"question":"من الأخت المستمعة (ب. م. ن) رسالة تقول فيها: أنا سيدة توفي لي طفل بالبيت غرقًا منذ سبع سنوات، والآن أريد بمشيئة الله تعالى أن أصوم شهرين متتاليين ولكن قيل لي: إنه بعد مرور هذه الفترة لا يصح لك صيام، هل صحيح لا يصح الصيام كما قيل؟ جزاكم الله خيرًا.","title":"حكم الكفارة على من مات طفلها غرقًا في البيت","answer":"الجواب: هذا فيه تفصيل إن كان موته غرقًا بأسبابك فعليك الصوم إلا إذا وجدت رقبة عبد أو أمة فاشتريتها واعتقت فلا بأس؛ لأن قتل الخطأ يوجب الكفارة، والكفارة عتق عبد أو أمة، يعني: عبد مؤمن أو أمة مؤمنة، فإن تيسر ذلك فهذا هو الواجب، فإن لم يتيسر ذلك فعليك صوم شهرين متتابعين؛ ستين يومًا، إذا كان موته غرقًا بأسبابك. أما إذا كان موته غرقًا ليس بأسبابك وليس لك فيه أثر فليس عليك صوم ولا عتق، فإذا كنت وضعتيه عند محل الغرق وهو صغير ما يحسن ولا يصرف نفسه فأنت متسببة، أما إذا كان بعيدًا عن أسباب الغرق في البيت أو في أي محل بعيد ولكنه ذهب عند غفلتك في بعض الحاجات وسقط في نهر أو في حوض ماء أو ما أشبه وهو بعيد عنك ليس لك فيه تسبب، ولا تعتبرين في هذا مفرطة ولا متسببة فليس عليك شيء، وأنت أعلم بنفسك وأعلم بالواقع.  وإن كنت تعلمين أو يغلب على ظنك أنك السبب فالصوم يكفي ولو بعد مدة سنين، فإن كنت يغلب على ظنك أنك لا سبب لك في ذلك وأن الأمر وقع ....... الحرص ليس لك فيه تسبب ولم تقربيه إلى محل الغرق فليس عليك شيء والحمد لله. نعم.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/16993/حكم-الكفارة-على-من-مات-طفلها-غرقا-في-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_848/nour_84802.mp3","categories":["الجنايات والحدود"]},{"id":17978,"question":"من الأخت المستمعة (ب. م. ن) رسالة تقول فيها: أنا سيدة توفي لي طفل بالبيت غرقًا منذ سبع سنوات، والآن أريد بمشيئة الله تعالى أن أصوم شهرين متتاليين ولكن قيل لي: إنه بعد مرور هذه الفترة لا يصح لك صيام، هل صحيح لا يصح الصيام كما قيل؟ جزاكم الله خيرًا.","title":"حكم الكفارة على من مات طفلها غرقًا في البيت","answer":"الجواب: هذا فيه تفصيل إن كان موته غرقًا بأسبابك فعليك الصوم إلا إذا وجدت رقبة عبد أو أمة فاشتريتها واعتقت فلا بأس؛ لأن قتل الخطأ يوجب الكفارة، والكفارة عتق عبد أو أمة، يعني: عبد مؤمن أو أمة مؤمنة، فإن تيسر ذلك فهذا هو الواجب، فإن لم يتيسر ذلك فعليك صوم شهرين متتابعين؛ ستين يومًا، إذا كان موته غرقًا بأسبابك. أما إذا كان موته غرقًا ليس بأسبابك وليس لك فيه أثر فليس عليك صوم ولا عتق، فإذا كنت وضعتيه عند محل الغرق وهو صغير ما يحسن ولا يصرف نفسه فأنت متسببة، أما إذا كان بعيدًا عن أسباب الغرق في البيت أو في أي محل بعيد ولكنه ذهب عند غفلتك في بعض الحاجات وسقط في نهر أو في حوض ماء أو ما أشبه وهو بعيد عنك ليس لك فيه تسبب، ولا تعتبرين في هذا مفرطة ولا متسببة فليس عليك شيء، وأنت أعلم بنفسك وأعلم بالواقع.  وإن كنت تعلمين أو يغلب على ظنك أنك السبب فالصوم يكفي ولو بعد مدة سنين، فإن كنت يغلب على ظنك أنك لا سبب لك في ذلك وأن الأمر وقع ....... الحرص ليس لك فيه تسبب ولم تقربيه إلى محل الغرق فليس عليك شيء والحمد لله. نعم.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/16993/حكم-الكفارة-على-من-مات-طفلها-غرقا-في-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_848/nour_84802.mp3","categories":["الجنايات والحدود"]},{"id":18285,"question":"[إذا اقتتلت طائفتان وبغت إحداهما على الأخرى فما حكم قتلى الطائفتين]؟قال الله  في كتابه العزيز:بسم الله الرحمن الرحيم: وَإِنْ طَائِفَتَانِ مِنَ الْمُؤْمِنِينَ [الحجرات:9] ............","title":"حكم القتلى من طائفتين إذا كانت إحداهما باغية","answer":"الجواب: .............. باغية، يعتبر مقاتلًا في سبيل الله، فهو من الشهداء إذا قتل، وله الجنة، وإنما الإشكال في المقتول من الفئة الباغية، التي أبت الصلح، فهذا هو المحل -محل البحث- فيقال في حقها: إن كانت ظالمة متعمدة تعلم أنها باغية وأنها ظالمة فهي متوعدة بالنار؛ لأنه قتل بغير حق..........","link":"https://binbaz.org.sa/fatwas/17334/حكم-القتلى-من-طاىفتين-اذا-كانت-احداهما-باغية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_912/nour_91202.mp3","categories":["الجنايات والحدود"]},{"id":18397,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الجزائر باعثها أحد الإخوة من هناك يقول: (س. ع. ف) أخونا يسأل في أول أسئلته عن حكم امرأة كانت حاملًا؛ فأكلت دواء فسبب مرضًا فأسقط الجنين، هل عليها شيء أو لا؟","title":"حكم المرأة إذا تسببت بإسقاط جنينها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإن الله  أباح لعباده التداوي، بل شرعه لهم بما لا محذور فيه، فقال: عباد الله! تداووا ولا تداووا بحرام، وقال عليه الصلاة والسلام: ما أنزل الله داء إلا أنزل له شفاء علمه من علمه وجهله من جهله، وقال أيضًا عليه الصلاة والسلام: لكل داء دواء؛ فإذا أصيب دواء الداء برأ بإذن الله. فللرجل والمرأة أن يتداوى بالأمر المباح الذي يرجو فيه الفائدة، فإذا تداوت المرأة بشيء من الدواء وحصل بسببه إسقاط حبلها؛ فإنه يكون من باب القتل الخطأ، فإن قتل الخطأ هو أن يفعل الإنسان ما له فعله فيترتب عليه قتل؛ كأن يرمي الصيد فيصيب إنسانًا، أو يرمي الهدف فيصيب إنسانًا، فهذا هو قتل الخطأ. فإذا تعاطت شيئًا من الدواء لا لقصد إسقاط الحبل، ولكن لأجل التداوي فذكر الأطباء، أو العارفون بهذا الدواء وآثاره على الحمل أنه هو السبب في قتله فإن عليها دية؛ وهي غرة عبد أو أمة إذا سقط ميتًا بأسباب هذا الدواء، وعليها كفارة إذا كان قد مضى عليه أربعة أشهر؛ لأنه حينئذ تنفخ فيه الروح، ويكون إنسانًا فعليها عنه غرة عبد أو أمة للورثة، وعليها كفارة: عتق رقبة مؤمنة، فإن لم تستطع فصيام شهرين متتابعين، كأمثاله من النفوس المعصومة، إلا أن يسمح الورثة عن الغرة فلا حرج في ذلك، كما لو سمح الورثة عن الدية الكاملة إذا كانوا عقلاء مرشدين، وهذه الغرة التي هي عبد أو أمة تكون للورثة قيمتها خمس من الإبل عشر دية أمه. وأما الكفارة فهي حق لله ليس للورثة فيها حق، فعليها أن تصوم إذا عجزت عن العتق، فإن لم تستطع العتق ولا الصيام بقي في ذمتها حتى تقدر على شيء من ذلك، تبقى الكفارة في ذمتها حتى تقدر على العتق أو تقدر على الصيام، والله ولي التوفيق. نعم.","link":"https://binbaz.org.sa/fatwas/17467/حكم-المراة-اذا-تسببت-باسقاط-جنينها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_863/nour_86301.mp3","categories":["الجنايات والحدود","الطب والتداوي"]},{"id":18451,"question":"من جمهورية مصر العربية أخونا (ف. م. أ) يقول مقيم في عنيزة، يسأل على طريقته الخاصة يقول: جاءت إلي ابنة خالي الصغيرة وقالت لي: إن أبوها قامت معه معركة بينه وبين أناس آخرين، ذهبت لأرى ماذا حدث ولعلي أقدر على الصلح بينهم، ولكن عندما وصلت إلى مكان المعركة قوبلت من الطرف الثاني بالضرب منهم، فأخذت أدافع عن نفسي وفجأة قام خالي بقتل واحد منهم من غير أن أراه عندما قتله، فهل علي إثم في ذلك؟ وهل أكون شريكًا مع خالي في القتل؟ وإذا كنت آثمًا في ذلك ماذا أفعل لأكفر عن ذنبي؟ أفيدوني أثابكم الله.","title":"حكم المقتول أثناء العراك","answer":"الجواب: إذا كان الواقع كما ذكرت في السؤال فلا شيء عليك؛ لأنك لم تعن على القتل، ولم تأمر به، وإنما هو من غيرك، ومن غير مساعدة منك، أما كونك تدافع عن نفسك لما ضربوك لعلك تسلم هذا لا تعلق له بالقتل، وليس عليك فيه شيء إذا كان الدفاع بقصد، الدفاع من غير زيادة ولا ظلمًا منك لأحد فلا شيء عليك؛ لأن المؤمن مأمور بالدفاع عن نفسه بالأسهل فالأسهل حتى يتخلص وحتى يسلم من الظالمين. وأما كون خالك قتل قتيلًا؛ فإن هذا لا يتعلق بك أنت إذا كنت لم تساعد في ذلك ولم تأمر بذلك فإنه لا يضرك بل ذلك المسئول عنه خالك. والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/17547/حكم-المقتول-اثناء-العراك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_865/nour_86507.mp3","categories":["الجنايات والحدود"]},{"id":18455,"question":"من جمهورية مصر العربية أخونا (ف. م. أ) يقول مقيم في عنيزة، يسأل على طريقته الخاصة يقول: جاءت إلي ابنة خالي الصغيرة وقالت لي: إن أبوها قامت معه معركة بينه وبين أناس آخرين، ذهبت لأرى ماذا حدث ولعلي أقدر على الصلح بينهم، ولكن عندما وصلت إلى مكان المعركة قوبلت من الطرف الثاني بالضرب منهم، فأخذت أدافع عن نفسي وفجأة قام خالي بقتل واحد منهم من غير أن أراه عندما قتله، فهل علي إثم في ذلك؟ وهل أكون شريكًا مع خالي في القتل؟ وإذا كنت آثمًا في ذلك ماذا أفعل لأكفر عن ذنبي؟ أفيدوني أثابكم الله.","title":"حكم المقتول أثناء العراك","answer":"الجواب: إذا كان الواقع كما ذكرت في السؤال فلا شيء عليك؛ لأنك لم تعن على القتل، ولم تأمر به، وإنما هو من غيرك، ومن غير مساعدة منك، أما كونك تدافع عن نفسك لما ضربوك لعلك تسلم هذا لا تعلق له بالقتل، وليس عليك فيه شيء إذا كان الدفاع بقصد، الدفاع من غير زيادة ولا ظلمًا منك لأحد فلا شيء عليك؛ لأن المؤمن مأمور بالدفاع عن نفسه بالأسهل فالأسهل حتى يتخلص وحتى يسلم من الظالمين. وأما كون خالك قتل قتيلًا؛ فإن هذا لا يتعلق بك أنت إذا كنت لم تساعد في ذلك ولم تأمر بذلك فإنه لا يضرك بل ذلك المسئول عنه خالك. والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/17547/حكم-المقتول-اثناء-العراك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_865/nour_86507.mp3","categories":["الجنايات والحدود"]},{"id":18556,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات رمزت إلى اسمها بثلاثة حروف، تقول: السائلة (ن. د. ق) من الكامل، أختنا ككثير من الأخوات المستمعات يسألن عن وفاة الأطفال الذين قد تكون وفاتهم بسبب الإهمال، فتقول مثلًا:أنا سيدة من منطقة الكامل التابعة لمدينة مكة المكرمة، لي عندكم هذه القضية، أرجو أن تفتوني فيها، كان عندي طفل صغير، تركته مع والده في السيارة وكان ذاهبًا في مشوار، وانقلبت بهما السيارة في الطريق، ومات الطفل، ثم بعد تلك الفترة رزقني الله بطفلة، وفي أحد الأيام تركتها تلعب بجوار البيت، فوقعت في خزان ماء، فغرقت في ذلك الخزان وماتت.سؤالي هو: هل علي ذنب في وفاة الطفل والطفلة؟ أو هل أعد مهملة ويجب علي الكفارة أو صدقة أو أن أفعل أي شيء؟أفتوني جزاكم الله خيرًا.","title":"حكم الأبوين إذا توفي طفلهما بسبب إهمالهما","answer":"الجواب: أما الطفل الأول الذي مات مع أبيه، فهذا ليس عليك منه شيء، وإنما الحكم معلق بأبيه إن كان أبوه قد فعل ما يوجب الضمان من سرعة، أو نحوها، فإنه عليه الكفارة وعلى العاقلة الدية؛ لأنها شبه العمد، وإذا سمحت أنت والورثة فلا شيء عن الدية. أما الكفارة فتكون في ماله إذا كان قد فعل شيئًا يوجب الضمان، وهذا يرجع إلى سؤال المرور عن صفة الواقع، فإذا كان قد فعل ما يوجب الضمان حتى حصل الانقلاب بسبب ذلك فعليه كفارة من ماله، وهي عتق رقبة مؤمنة، فإن لم يستطع ذلك فصيام شهرين متتابعين، وإذا صام عنه بعض أقربائه، فجزاه الله خيرًا. أما أنت فليس عليك شيء. وأما الطفلة التي تركتها عند الخزان فهذا فيه تفصيل: إن كان الخزان قريبًا منها مفتوحًا، وأنت تعلمين ذلك، فهذا تفريط منك، وعليك الكفارة؛ لأنك فرطت في هذا. أما إن كان الخزان بعيدًا، أو كان مغلقًا، ثم فتح وأنت لا تعلمين فليس عليك شيء؛ لأن مثل هذا يقع كثيرًا والسلامة من هذا عزيزة، لكن إذا كان قريبًا من البنت -من الطفلة- وأنت تعرفين أنه قريب ومفتوح، فهذا يعتبر تفريطًا منك، أما إن كان بعيدًا عرفًا فليس عليها شيء -إن شاء الله-، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17666/حكم-الابوين-اذا-توفي-طفلهما-بسبب-اهمالهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_916/nour_91607.mp3","categories":["الجنايات والحدود"]},{"id":18561,"question":"أخونا يسأل عن فعل الذنب مع الجهل بحكمه، هل يسقط الحد أم لا؟","title":"حكم من ارتكب ذنبًا له حد جاهلًا","answer":"الجواب: هذا يختلف: إن كان مما يعرف عند المسلمين، ويندر الجهل به؛ لأن صاحبه بين المسلمين؛ فهذا لا يسقط الحد ولا يقبل قوله: إني ما أعرف أن الزنا حرام، أو ما أعرف إن الخمر حرام؛ لأن هذا معروف بين المسلمين، فلا يقبل قوله: إني جاهل بل يقام عليه الحد. أما لو كان في محل بعيد عن المسلمين، في غابات بعيدة عن المسلمين، مجاهيل لا يعرفوا أحكام الإسلام، فهذا لا يقام عليه الحد، حتى يعلم ويبين له، فإذا عاد إليه بعد ذلك أقيم عليه الحد. فالمقصود: أنه يختلف الأمر، فالشخص الذي بين المسلمين وتبلغه شريعة الله، ويعرف أن هذا بين المسلمين محرم، هذا لا يعذر بدعواه الجهل؛ لأن هذا شائع منتشر بين المسلمين ومشهور، فالزنا وشرب الخمر تحريم اللواط تحريم العقوق القطيعة للرحم، وأشباه ذلك.  فأما من كان عاش في جاهلية بعيدة عن الإسلام بعيدة عن المسلمين في مجاهل أفريقيا ومجاهل أمريكا، يعني: فيما موضع بعيد عن معرفة أحكام الله، فهذا يعلم، نعم. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/17672/حكم-من-ارتكب-ذنبا-له-حد-جاهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_917/nour_91703.mp3","categories":["الجنايات والحدود"]},{"id":18661,"question":"رسالة وصلت إلى البرنامج من المستمع (ع. ج. الألمعي) أخونا رسالته مفصلة بعض الشيء، لخصتها في العبارات التالية يقول: إنه سرق من مستودع كان يقوم بحراسته، وكان عمره تسع عشرة سنة، والآن استيقظ ضميره، وبدأ يفكر في المخرج، علمًا بأن المسروق قد بيع، ولا يستطيع البوح به، فكيف يتصرف؟","title":"حكم من سرق شيئًا ولم يستطع إرجاعه","answer":"الجواب: إن كان يستطيع فعليه رد القيمة -قيمة المسروق- إلى أهل المستودع بأي طريق، ولو لم يسم نفسه، يرسله إليهم بأي طريق توصل هذا المال إليهم؛ فإن لم يستطع تصدق به عنهم بالنية، أعطاه بعض الفقراء، أو ساهم به في مشروع خيري، كتعمير المساجد بالنية عن صاحب المال، لكن متى استطاع أن يوصله إلى صاحب المال بأي وسيلة، فالواجب عليه إيصاله، مع التوبة إلى الله، والندم والحرص الكامل على عدم العودة، يعني: يعزم عزمًا صادقًا أن لا يعود إلى مثل هذا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17768/حكم-من-سرق-شيىا-ولم-يستطع-ارجاعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_919/nour_91907.mp3","categories":["الجنايات والحدود"]},{"id":18694,"question":"من اليمن السائل (عبد الله. أ) يقول في هذا  سماحة الشيخ، السلام عليكم ورحمة الله وبركاته، يقول: رجل طلب منه شخص مريض أن يشتري له إبرة لضيق التنفس؛ وذلك من الصيدلية؛ لأنه تعود على شرائها من قبل ذلك، فذهب واشتراها له هذا الرجل، فأمره أن يضربها له، فضربها له في العضل، وهذه الإبرة تضرب في الوريد، فضربها له في المساء، وفي الصباح مات الرجل المريض.والآن الرجل الذي ضرب له هذه الإبرة لا ينام الليل لهول ما أصابه، فهو يظن بأنه هو الذي قتله بتلك الإبرة التي ضربها له، بالرغم أنهم ذهبوا إلى الأطباء بمثل هذه الإبرة، وسألوهم عن ذلك: هل هي تقتل إذا ضربت في العضل، ولم تضرب في الوريد لجهل الرجل هذا؟ قالوا لهم: لا. ولكن قد تسبب بعض الالتهابات بعد ضربها، وعلى الرغم من هذا لم يقتنع هذا الرجل، بل يقول بأنه هو الذي قتله.نرجو منكم أن توضحوا لنا ذلك مأجورين.","title":"حكم من يظن أنه تسبب في قتل رجل مريض","answer":"الجواب: على الفاعل أن يسأل المختصين من الأطباء، فإذا قالوا: إن فعله سبب الموت؛ عليه الكفارة في قتل الخطأ، وهي عتق رقبة، فإن عجز يصوم شهرين متتابعين، وإن قالوا: إنها لا تسبب الموت فلا شيء عليه، والحمد لله. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17796/حكم-من-يظن-انه-تسبب-في-قتل-رجل-مريض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_788/nour_78806.mp3","categories":["الجنايات والحدود","الطب والتداوي","قضايا المرأة"]},{"id":18705,"question":"ما هي عقوبة الذي يتعامل بالسحر ويؤذي الناس، ما هي عقوبته في الدنيا والآخرة سماحة الشيخ؟","title":"عقوبة الساحر في الدنيا والآخرة","answer":"الجواب: إذا علم أنه ساحر فهو مشرك، عقوبته القتل في الدنيا، وفي الآخرة النار إذا مات على سحره ولم يتب، يقول الله -جل وعلا-: وَاتَّبَعُوا مَا تَتْلُوا الشَّيَاطِينُ عَلَى مُلْكِ سُلَيْمَانَ وَمَا كَفَرَ سُلَيْمَانُ وَلَكِنَّ الشَّيَاطِينَ كَفَرُوا يُعَلِّمُونَ النَّاسَ السِّحْرَ وَمَا أُنزِلَ عَلَى الْمَلَكَيْنِ بِبَابِلَ هَارُوتَ وَمَارُوتَ وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّى يَقُولا إِنَّمَا نَحْنُ فِتْنَةٌ فَلا تَكْفُرْ[البقرة:102] فدل على أن السحر كفر. فالواجب على من يتعاطاه التوبة إلى الله، فإن مات على سحره صار كافرًا من أهل النار؛ لأن السحر من آثار دعاء الشياطين، والاستغاثة بالشياطين، واللجأ إليهم، فهو كفر لما يترتب عليه من دعاء الجن، والاستغاثة بالجن - والعياذ بالله -، هذا هو الواجب من جهة الآخرة. أما من جهة الدنيا فالواجب على ولاة الأمور إذا عرفوا الساحر أن يقتل حد الساحر ضرب بالسيف أمر عمر بقتل السحرة، أمر عماله في الشام أن يقتلوا السحرة، وحفصة كان عندها جارية سحرتها فقتلتها، الساحر يقتل في الدنيا، وإذا مات على سحره مات كافرًا، نسأل الله العافية، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17820/عقوبة-الساحر-في-الدنيا-والاخرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_788/nour_78813.mp3","categories":["الجنايات والحدود","السحر والكهانة"]},{"id":18871,"question":"أختنا تقول أيضًا: أما البنت الثانية فإنها ولدت وهي عمياء العينين، وعاشت معي أربع سنوات، وهي على حالتها المذكورة، وكل مرة كنت أرجعها من الخطر، فمثلًا: كانت تريد أن ترمي بنفسها من فوق المنزل إلى الشارع، وكنت أحافظ عليها، ولكن في يوم من الأيام قذفت بنفسها إلى الشارع من فوق أربعة أدوار، ولبثت قليلًا وماتت.فهل أنا يا فضيلة الشيخ قصرت بحقها، وكلما افتكرتها فإن ضميري يؤنبني، فهل علي إثم أو ذنب لأني تركتها؟ أم أن هذا قضاء وقدر عليّ؟ وإذا كان علي إثم، فهل ينبغي علي أن أصوم شهرين، أم ماذا أعمل إذا كان علي إثم أو ذنب بحقها؟ والله الموفق، وجزاكم الله خيرًا.","title":"ضابط التقصير والضمان في وفاة ابنة عمياء","answer":"الجواب: إذا كنت تركتيها في السطح الأعلى، وليس فيه حجا ولا مانع؛ فقد فرطت، وعليك الدية والكفارة، الدية للورثة، وعليك الكفارة، وهي عتق رقبة مؤمنة إن تيسر ذلك، فإن عجزت فصيام شهرين متتابعين؛ لأن الواجب عليك حفظها وصيانتها، وهي أمانة في الذمة، فإذا كنت لم تفرطي وكانت في السطح المصون الذي مثله لا تستطيع أن تسقط نفسها منه، ولكنها تعبثت حتى صعدت على الجدار، أو مع كوة أسقطت نفسها معها، وهي مرتفعة عن الأرض، ولكن حاولت بعبثها؛ فليس عليك شيء -إن شاء الله-؛ لأنك لم تفرطي في مثل هذا. أما إذا كانت في محل يعرف أنها بإطلاقها فيه سوف تسقط؛ لأنه ليس له حمى يحميها من السقوط، هذا تفريط يوجب الضمان، ونسأل الله أن يعوضك خيرًا.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18041/ضابط-التقصير-والضمان-في-وفاة-ابنة-عمياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_880/nour_88009.mp3","categories":["الجنايات والحدود"]},{"id":19373,"question":"رسالة وصلت إلى البرنامج من اليمن الشمالي تعز باعثها أخ لنا من هناك يقول: محمد بن أحمد وأخوه عبد العزيز بن شرف نعمان، الأخوان يسألان هذا  ما حكم الجماعة الذين يقتلون الواحد، هل يقتلون به؟ أم تؤخذ منهم الدية مع الدليل؟","title":"حكم قتل الجماعة بالواحد","answer":"الجواب: الصواب أن الجماعة تقتل بالواحد، إذا اجتمعوا على قتل واحد وتعاونوا على قتله، فالصواب أنهم يقتلون بذلك؛ لأنهم مجرمون ظالمون، وقد فعل ذلك عمر  فقتل جماعة بواحد . وهذا هو الذي عليه جمهور أهل العلم، ولا يسع أهل الإسلام والمسئولين في الدول الإسلامية إلا هذا؛ لأن في ذلك منعًا للجريمة التي قد يتواطأ عليها الجماعة إذا علموا أنهم لا يقتلون قد يتواطأ الاثنان والثلاثة على ما يريدون. فالواجب الحكم بالقصاص على الجماعة في قتل واحد إذا توافرت الشروط، وثبت ما يوجب ذلك عند الحاكم الشرعي. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18594/حكم-قتل-الجماعة-بالواحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_934/nour_93403.mp3","categories":["الجنايات والحدود"]}]
